-- Revisão teológica de 23-24/11/2026: um teólogo por mistério reviu a coerência de cada
-- comentário com a sua passagem, acrescentou Padres, Doutores e autores espirituais
-- tradicionais e perguntas do Catecismo Maior de São Pio X.
-- Gerado a partir de src/data/content/*Meditation.json (mesmo conteúdo do fallback offline).
-- Textos entre aspas simples comuns (apóstrofo duplicado), para funcionar também no SQL Editor.
-- Substitui passagens e comentários dos 20 mistérios; imagens e referências de estudo não mudam.

delete from public.passages;
delete from public.commentaries;

-- joyful-1 · Lc 1, 26-27
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, (estando Isabel) no sexto mês, foi enviado por Deus o anjo Gabriel a uma cidade da Galileia, chamada Nazaré, a uma virgem desposada com um varão, que se chamava José, da casa de David; o nome da Virgem era Maria.', 'Lc 1, 26-27', 0
from public.mysteries m where m.type = 'joyful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Leão Magno', 'Sermo 21 (In Nativitate Domini I), 1 (texto abreviado; tradução a partir do latim)', 'Escolhe-se uma Virgem de estirpe real, da linhagem de David, que, havendo de ser fecundada com o sagrado fruto, concebesse a prole divina e humana primeiro na mente e depois no corpo. E, para que, ignorando o desígnio do alto, não se assustasse perante efeitos tão inauditos, aprende pelo colóquio com o Anjo o que nela havia de ser operado pelo Espírito Santo. Nem julga perda para o seu pudor ser em breve Mãe de Deus…'),
  (1, 'Catecismo da Igreja Católica', 'CIC 488 (grafia adaptada ao Brasil)', '«Deus enviou o seu Filho» (Gl 4, 4). Mas, para Lhe «formar um corpo», quis a livre cooperação duma criatura. Para isso, desde toda a eternidade, Deus escolheu, para ser a Mãe do seu Filho, uma filha de Israel, uma jovem judia de Nazaré, na Galileia, «virgem que era noiva de um homem da casa de David, chamado José. O nome da virgem era Maria» (Lc 1, 26-27): «O Pai das misericórdias quis que a aceitação, por parte da que Ele predestinara para Mãe, precedesse a Encarnação, para que, assim como uma mulher contribuiu para a morte, também outra mulher contribuísse para a vida».'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 30, a. 2 (texto abreviado; tradução a partir do latim). O sermão citado como de S. Jerônimo é hoje atribuído a Pascásio Radberto.', 'Convinha que o mistério da divina Encarnação fosse anunciado à Mãe de Deus por um Anjo, por três razões. Primeiro, para que também nisto se guardasse a ordem divina, segundo a qual as coisas divinas chegam aos homens por meio dos Anjos… Segundo, isto convinha à restauração humana, que havia de realizar-se por Cristo. Por isso diz Beda: «Princípio apropriado da restauração humana foi que um Anjo fosse enviado por Deus à Virgem que havia de ser consagrada pelo parto divino, porque a primeira causa da perdição humana foi quando a serpente era enviada pelo diabo à mulher, para a enganar com o espírito de soberba.» Terceiro, porque isto convinha à virgindade da Mãe de Deus. Por isso diz Jerônimo: «Bem é enviado um Anjo à Virgem, porque a virgindade é sempre parente dos Anjos.»'),
  (3, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 7 (texto abreviado; tradução a partir do latim)', 'Bem desposada, mas virgem, porque é figura da Igreja, que é imaculada, mas esposa. Virgem, concebeu-nos do Espírito; virgem, dá-nos à luz sem gemido…'),
  (4, 'São Tomás de Aquino', 'Suma Teológica, III, q. 30, a. 1, corpo e ad 2 (texto abreviado; tradução a partir do latim)', 'Era conveniente que fosse anunciado à bem-aventurada Virgem que havia de conceber Cristo. Primeiro, para que se guardasse a devida ordem na união do Filho de Deus com a Virgem, a saber, que primeiro a sua mente fosse instruída acerca d’Ele, antes de O conceber na carne… Segundo, para que pudesse ser testemunha mais certa deste mistério, sendo sobre ele instruída por Deus. Terceiro, para que oferecesse a Deus os dons voluntários da sua obediência, ao que se mostrou pronta, dizendo: «Eis a serva do Senhor». Quarto, para mostrar que há um certo matrimônio espiritual entre o Filho de Deus e a natureza humana. E por isso, na Anunciação, esperava-se o consentimento da Virgem em lugar de toda a natureza humana. … A bem-aventurada Virgem tinha fé explícita na futura Encarnação; mas, sendo humilde, não pensava de si coisas tão altas. E por isso devia ser instruída sobre isto.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 1;

-- joyful-1 · Lc 1, 28-33
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, entrando o anjo onde ela estava, disse-lhe: «Deus te salve, cheia de graça; o Senhor é contigo; bendita és tu entre as mulheres.» E ela, tendo ouvido estas coisas, turbou-se com as suas palavras, e discorria pensativa que saudação seria esta. E o anjo disse-lhe: «Não temas, Maria, pois achaste graça diante de Deus; eis que conceberás no teu ventre, e darás à luz um filho, a quem porás o nome de JESUS. Este será grande, e será chamado Filho do Altíssimo, e o Senhor Deus lhe dará o trono de seu pai David; e reinará sobre a casa de Jacob eternamente; e o seu reino não terá fim.»', 'Lc 1, 28-33', 1
from public.mysteries m where m.type = 'joyful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. III «Da Ave-Maria», 5ª e 6ª perguntas do capítulo. Tradução a partir do italiano.', '— Quando foi que o Anjo disse a Maria estas palavras? — O Anjo disse a Maria estas palavras quando foi anunciar-lhe, da parte de Deus, o mistério da Encarnação que nela se havia de operar. — Que pretendemos fazer ao saudar a Santíssima Virgem com as mesmas palavras do Arcanjo? — Ao saudar a Santíssima Virgem com as palavras do Arcanjo, alegramo-nos com ela, fazendo memória dos singulares privilégios e dons que Deus lhe concedeu de preferência a todas as outras criaturas.'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 8-9 (texto abreviado; tradução a partir do latim)', 'Reconhece a virgem pelos costumes, reconhece-a pelo pudor, pela palavra, pelo mistério. Próprio das virgens é estremecer… Estava sozinha no interior da casa, onde nenhum homem a visse e só o Anjo a encontrasse… Bem se diz só ela cheia de graça, pois só ela alcançou a graça que nenhuma outra merecera: ser repleta do próprio Autor da graça.'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 30, a. 4, ad 1 (tradução a partir do latim)', 'Para uma alma humilde, nada há de mais admirável do que ouvir falar da sua própria excelência. Ora, a admiração é o que mais desperta a atenção do espírito. Por isso o Anjo, querendo tornar a mente da Virgem atenta para ouvir tão grande mistério, começou pelo seu louvor.'),
  (3, 'Catecismo da Igreja Católica', 'CIC 490 (grafia adaptada ao Brasil)', 'Para vir a ser Mãe do Salvador, Maria «foi adornada por Deus com dons dignos de uma tão grande missão». O anjo Gabriel, no momento da Anunciação, saúda-a como «cheia de graça». Efetivamente, para poder dar o assentimento livre da sua fé ao anúncio da sua vocação, era necessário que Ela fosse totalmente movida pela graça de Deus.'),
  (4, 'São Tomás de Aquino', 'Expositio Salutationis angelicae (Sobre a Ave-Maria), a. 1 (texto abreviado; tradução a partir do latim)', 'O Senhor é contigo… De um modo está o Senhor com a bem-aventurada Virgem e de outro com o Anjo: com ela, como Filho; com o Anjo, como Senhor… Assim, a bem-aventurada Virgem é mais familiar de Deus do que o Anjo, porque com ela está o Senhor Pai, o Senhor Filho, o Senhor Espírito Santo, isto é, toda a Trindade.'),
  (5, 'São Tomás de Aquino', 'Expositio Salutationis angelicae (Sobre a Ave-Maria), a. 1 (texto abreviado; tradução a partir do latim)', 'Os outros santos praticaram certas virtudes especiais: um foi humilde, outro casto, outro misericordioso… Mas a bem-aventurada Virgem é dada como exemplo de todas as virtudes: nela encontras exemplo de humildade — «Eis a serva do Senhor», e depois: «olhou para a humildade da sua serva» —, de castidade — «pois não conheço varão» —, e de todas as virtudes.'),
  (6, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 10 (texto abreviado; tradução a partir do latim)', 'Também de João disse o anjo que seria grande; mas aquele, como homem grande; este, como Deus grande: «Grande é o Senhor e digno de todo o louvor, e a sua grandeza não tem fim.» … Grande era João, mas grande diante do Senhor.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 1;

-- joyful-1 · Lc 1, 34-38
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E Maria disse ao anjo: «Como se fará isso, pois eu não conheço varão?» E, respondendo o anjo, disse-lhe: «O Espírito Santo descerá sobre ti, e a virtude do Altíssimo te cobrirá com a sua sombra. E, por isso mesmo, o Santo, que há de nascer de ti, será chamado Filho de Deus. Eis que também Isabel, tua parenta, concebeu um filho na sua velhice; e este é o sexto mês da que se dizia estéril; porque a Deus nada é impossível.» Então disse Maria: «Eis aqui a serva do Senhor, faça-se em mim a tua palavra.» E o anjo afastou-se dela.', 'Lc 1, 34-38', 2
from public.mysteries m where m.type = 'joyful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Bernardo de Claraval', 'In laudibus Virginis Matris, homilia 4, 8-9 (texto abreviado)', 'Ouviste, ó Virgem, que vais conceber e dar à luz um Filho… O Anjo aguarda a tua resposta… Nós também, miseravelmente oprimidos… esperamos a tua palavra de misericórdia. Em tuas mãos está o preço da nossa salvação. Dá, depressa, ó Virgem, a tua resposta. Responde sem demora ao Anjo, ou, para melhor dizer, ao Senhor por meio do Anjo. Pronuncia uma palavra e recebe a Palavra. Profere a tua palavra humana e concebe a divina.'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 16 (texto abreviado; tradução a partir do latim)', 'Vê a humildade, vê a devoção. Chama-se serva do Senhor aquela que é escolhida para Mãe, e não se exaltou com a súbita promessa… Havendo de dar à luz o manso e humilde, devia ela também mostrar humildade. «Eis a serva do Senhor, faça-se em mim segundo a tua palavra.» Tens aqui a obediência, vês o desejo.'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. IV «Do terceiro artigo», 1ª e 3ª perguntas do capítulo. Tradução a partir do italiano. Texto abreviado.', '— Que nos ensina o terceiro artigo: «O qual foi concebido do Espírito Santo, nasceu de Maria Virgem»? — O terceiro artigo do Credo ensina-nos que o Filho de Deus tomou um corpo e uma alma, como nós temos, no seio puríssimo de Maria Virgem, por obra do Espírito Santo, e que nasceu desta Virgem. … — Por que se diz só: «foi concebido do Espírito Santo»? — Diz-se só «foi concebido do Espírito Santo» porque a encarnação do Filho de Deus é obra de bondade e de amor, e as obras de bondade e de amor atribuem-se ao Espírito Santo.'),
  (3, 'São Bernardo de Claraval', 'In laudibus Virginis Matris (Super Missus est), homilia I, 5 (texto abreviado; tradução a partir do latim)', 'Se Maria não fosse humilde, o Espírito Santo não teria repousado sobre ela… Ainda que tenha agradado pela virgindade, foi pela humildade que concebeu.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 494 (texto abreviado; grafia adaptada ao Brasil)', 'Ao anúncio de que dará à luz «o Filho do Altíssimo», sem conhecer homem, pela virtude do Espírito Santo, Maria respondeu pela «obediência da fé», certa de que «a Deus nada é impossível»: «Eis a serva do Senhor, faça-se em mim segundo a tua palavra» (Lc 1, 38). Assim, dando o seu consentimento à palavra de Deus, Maria tornou-se Mãe de Jesus… «o nó da desobediência de Eva foi desatado pela obediência de Maria; e aquilo que a virgem Eva atou, com a sua incredulidade, desatou-o a Virgem Maria com a sua fé».'),
  (5, 'Santo Agostinho', 'De sancta virginitate, 3 (texto abreviado; tradução a partir do latim, conferida com a citação em S. Tomás, Suma Teológica, III, q. 30, a. 1)', 'Mais bem-aventurada é Maria por receber a fé de Cristo do que por conceber a carne de Cristo… Assim também o parentesco materno de nada teria aproveitado a Maria, se não tivesse trazido Cristo mais felizmente no coração do que na carne.'),
  (6, 'São Tomás de Aquino', 'Suma Teológica, III, q. 30, a. 4, ad 3 (texto abreviado; tradução a partir do latim)', 'Como diz Ambrósio, «por isso muitas estéreis deram à luz antes, para que se creia no parto da Virgem». E por isso se aduz a conceição de Isabel, estéril, não como argumento suficiente, mas como um exemplo figurativo…'),
  (7, 'Bento XVI', 'Carta encíclica Deus caritas est, n. 41 (texto abreviado)', 'Maria é grande, precisamente porque não quer fazer-Se grande a Si mesma, mas engrandecer a Deus. Ela é humilde: não deseja ser mais nada senão a serva do Senhor (cf. Lc 1, 38.48). Sabe que contribui para a salvação do mundo, não realizando uma sua obra, mas apenas colocando-Se totalmente à disposição das iniciativas de Deus…')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 1;

-- joyful-1 · Jo 1, 14
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E (para isso) o Verbo se fez carne, e habitou entre nós; e nós vimos a sua glória, glória como de (Filho) Unigênito do Pai, cheio de graça e de verdade.', 'Jo 1, 14', 3
from public.mysteries m where m.type = 'joyful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'São Leão Magno', 'Sermo 21 (In Nativitate Domini I), 2 (texto abreviado; tradução a partir do latim)', 'O Verbo de Deus, Deus Ele mesmo, Filho de Deus, que no princípio estava junto de Deus, por quem foram feitas todas as coisas e sem o qual nada foi feito, para libertar o homem da morte eterna, fez-se homem; inclinando-se a assumir a nossa humildade sem diminuição da sua majestade, de tal modo que, permanecendo o que era e assumindo o que não era, uniu a verdadeira forma de servo àquela forma em que é igual a Deus Pai… Salva, pois, a propriedade de ambas as naturezas, que se juntam numa só pessoa, a humildade é assumida pela majestade, a fraqueza pela força, a mortalidade pela eternidade.'),
  (1, 'Catecismo da Igreja Católica', 'CIC 461 (grafia adaptada ao Brasil)', 'Retomando a expressão de São João («o Verbo fez-Se carne»: Jo 1, 14), a Igreja chama «Encarnação» ao fato de o Filho de Deus ter assumido uma natureza humana, para nela levar a efeito a nossa salvação. Num hino que nos foi conservado por São Paulo, a Igreja canta este mistério: «Tende em vós os mesmos sentimentos que havia em Cristo Jesus. Ele, que era de condição divina, não se valeu da sua igualdade com Deus, mas aniquilou-Se a Si próprio, assumindo a condição de servo, tornou-Se semelhante aos homens. Aparecendo como homem, humilhou-Se ainda mais, obedecendo até à morte, e morte de Cruz» (Fl 2, 5-8).'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. IV «Do terceiro artigo», 4ª e 5ª perguntas do capítulo. Tradução a partir do italiano.', '— O Filho de Deus, fazendo-se homem, deixou de ser Deus? — Não, o Filho de Deus fez-se homem sem deixar de ser Deus. — Então Jesus Cristo é Deus e homem ao mesmo tempo? — Sim, o Filho de Deus encarnado, isto é, Jesus Cristo, é Deus e homem ao mesmo tempo, perfeito Deus e perfeito homem.'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 1, a. 2 (texto abreviado; tradução a partir do latim). S. Tomás cita S. Agostinho, De Trinitate, XIII.', 'Diz Agostinho: «Nada foi tão necessário para levantar a nossa esperança como mostrar-nos quanto Deus nos amava. E que sinal mais manifesto disto do que dignar-se o Filho de Deus entrar em comunhão com a nossa natureza?» … A soberba do homem, que é o maior impedimento para que se una a Deus, «pode ser refutada e curada por tão grande humildade de Deus», como diz Agostinho no mesmo lugar.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 460 (texto abreviado; grafia adaptada ao Brasil)', 'O Verbo fez-Se carne, para nos tornar «participantes da natureza divina» (2 Pe 1, 4): «Pois foi por essa razão que o Verbo Se fez homem, e o Filho de Deus Se fez Filho do Homem: foi para que o homem, entrando em comunhão com o Verbo e recebendo assim a adoção divina, se tornasse filho de Deus». «Porque o Filho de Deus fez-Se homem, para nos fazer deuses»…')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 1;

-- joyful-2 · Lc 1, 39-40
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Naqueles dias, levantando-se Maria, foi com pressa às montanhas, a uma cidade de Judá. E entrou em casa de Zacarias, e saudou Isabel.', 'Lc 1, 39-40', 0
from public.mysteries m where m.type = 'joyful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 19 (texto abreviado). Tradução do Ofício das Leituras de 21 de dezembro, Liturgia das Horas (CNBB), conferida com o latim. O número começa por «Morale est omnibus…», aqui omitido.', '… O Anjo anunciara à Virgem Maria coisas misteriosas. Para fortalecer sua fé com um exemplo, anunciou-lhe a maternidade de uma mulher idosa e estéril, como prova de que é possível a Deus tudo que ele quer. Logo ao ouvir a notícia, Maria dirigiu-se às montanhas, não por falta de fé na profecia ou falta de confiança na mensagem, nem por duvidar do exemplo dado, mas guiada pela felicidade de ver cumprida a promessa, levada pela vontade de prestar um serviço, movida pelo impulso interior de sua alegria. Já plena de Deus, aonde ir depressa senão às alturas? A graça do Espírito Santo ignora a lentidão.'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 20 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', 'Aprendei vós, santas mulheres, a solicitude que deveis mostrar às vossas parentes que estão para dar à luz. A Maria, que antes vivia sozinha no mais recôndito da casa, não a retardaram nem o pudor virginal diante do público, nem a aspereza dos montes no seu empenho, nem a extensão do caminho no seu serviço. Às montanhas foi a Virgem, com pressa; a Virgem lembrada do serviço, esquecida da fadiga, forte pelo afeto e não pela condição de mulher, deixou a sua casa e partiu.'),
  (2, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 22 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', 'Aprendestes, virgens, o pudor de Maria; aprendei a humildade. Veio a parente à sua próxima, a mais nova à mais velha; e não só veio, mas foi a primeira a saudar. … Há nisto também uma razão de piedade e uma norma de doutrina. Deve-se considerar que o superior vem ao inferior, para que o inferior seja ajudado: Maria a Isabel, Cristo a João. …'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte V, cap. I «Das virtudes principais», § 7 «Da Caridade», 9.ª e 11.ª perguntas do parágrafo (texto abreviado). Tradução a partir do italiano.', '— Por que devemos amar o próximo? — Devemos amar o próximo por amor de Deus, porque Ele no-lo manda, e porque todo o homem é imagem d’Ele. … — Que quer dizer amar o próximo como a si mesmo? — Amar o próximo como a si mesmo quer dizer desejar-lhe e fazer-lhe, quanto se pode, aquele bem que devemos desejar a nós mesmos, e não lhe desejar nem fazer mal algum.'),
  (4, 'São João Paulo II', 'Carta encíclica Redemptoris Mater, n. 12 (texto abreviado). Omitem-se a localização de Ain-Karim e a referência ao anúncio do Anjo sobre Isabel.', '… Maria dirigiu-se para lá «apressadamente», para visitar Isabel, sua parente. … Maria dirige-se, pois, impelida pela caridade, a casa da sua parente. …')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 2;

-- joyful-2 · Lc 1, 41-45
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E aconteceu que, apenas Isabel ouviu a saudação de Maria, o menino saltou no seu ventre, e Isabel ficou cheia do Espírito Santo; e exclamou em alta voz, e disse: «Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre. Donde a mim esta dita, que a mãe do meu Senhor venha ter comigo? Porque, logo que a voz da tua saudação chegou aos meus ouvidos, o menino exultou de alegria no meu ventre. Bem-aventurada tu, que creste, porque se hão de cumprir as coisas que da parte do Senhor te foram ditas.»', 'Lc 1, 41-45', 1
from public.mysteries m where m.type = 'joyful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 717', '«Apareceu um homem, enviado por Deus, que tinha o nome de João» (Jo 1, 6). João é «cheio do Espírito Santo já desde o seio materno» (Lc 1, 15) (81), pelo próprio Cristo que a Virgem acabava de conceber por obra e graça do Espírito Santo. A « visitação» de Maria a Isabel tornou-se, assim, «visita de Deus ao seu povo» (82).'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 23 (texto abreviado). Mesma tradução do Ofício das Leituras, 21 de dezembro (CNBB), conferida com o latim de II, 23 («Vocem prior Elizabeth audivit, sed Ioannes prior gratiam sensit»).', 'Notai como cada palavra está escolhida com perfeita precisão e propriedade: Isabel foi a primeira a ouvir a voz, mas João foi o primeiro a pressentir a graça; aquela ouviu segundo a ordem da natureza, este exultou em virtude do mistério. Ela percebeu a chegada de Maria, ele, a do Senhor; a mulher ouviu a voz da mulher, o menino sentiu a presença do Filho; elas proclamam a graça de Deus, eles realizam-na interiormente, iniciando no seio de suas mães o mistério de misericórdia; e, por um duplo milagre, as mães profetizam sob a inspiração de seus filhos. A criança exultou, a mãe ficou cheia do Espírito Santo. A mãe não se antecipou ao filho; mas estando o filho cheio do Espírito Santo, comunicou-o a sua mãe. …'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte II, cap. VII «Da festa da Natividade de S. João Batista», 5.ª pergunta do capítulo. Tradução a partir do italiano.', '— S. João Batista não nasceu em pecado como os outros homens? — S. João Batista não nasceu em pecado como os outros homens, porque foi santificado no seio de sua mãe Santa Isabel, na presença de Jesus Cristo e da Santíssima Virgem.'),
  (3, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 25 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', 'Não o diz como quem ignora: sabe bem que é graça e operação do Espírito Santo que a mãe do Profeta seja saudada pela Mãe do Senhor, para proveito do seu filho; mas, como quem reconhece que isto não é mérito humano, e sim dom da graça divina, diz: Donde a mim isto? Isto é: que grande bem me acontece, que a Mãe do meu Senhor venha ter comigo? Não reconheço nisto nada de meu. Donde a mim, por que justiça, por que obras, por que méritos? … Sinto o milagre, reconheço o mistério: a Mãe do Senhor, fecunda do Verbo, está cheia de Deus.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. III «Da Ave-Maria», 7.ª, 8.ª e 9.ª perguntas do capítulo. Tradução a partir do italiano.', '— Quais são as palavras de Santa Isabel? — As palavras de Santa Isabel são: «Tu és bendita entre as mulheres, e bendito é o fruto do teu ventre». — Quando foi que Santa Isabel disse estas palavras? — Santa Isabel disse estas palavras, inspirada por Deus, quando, três meses antes de dar à luz S. João Batista, foi visitada pela Santíssima Virgem, que já trazia no seio o seu divino Filho. — Que fazemos nós ao dizer estas palavras? — Ao dizer as palavras de Santa Isabel, alegramo-nos com Maria Santíssima pela sua excelsa dignidade de Mãe de Deus, e bendizemos a Deus e lhe agradecemos por nos ter dado Jesus Cristo por meio de Maria.'),
  (5, 'Catecismo da Igreja Católica', 'CIC 2676 (texto abreviado). Omitidas as secções da saudação do anjo («Ave, Maria» e «Cheia de graça»); fica a saudação de Isabel.', '… «Bendita sois vós entre as mulheres e bendito é o fruto do vosso ventre, Jesus». Depois da saudação do anjo, fazemos nossa a de Isabel. «Cheia [...] do Espírito Santo» (Lc 1, 41), Isabel é a primeira, na longa sequência das gerações, a declarar Maria bem-aventurada (26): «Feliz d''Aquela que acreditou...» (Lc 1, 45); Maria é «bendita entre as mulheres», porque acreditou no cumprimento da Palavra do Senhor. Abraão, pela sua fé, tornou-se uma bênção «para todas as nações da terra» (Gn 12, 3). Pela sua fé, Maria tornou-se a mãe dos crentes, graças a quem todas as nações da terra recebem Aquele que é a própria bênção de Deus: Jesus, «fruto bendito do vosso ventre».'),
  (6, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 26 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada. O resto do número («Esteja em cada um a alma de Maria…») está na passagem do Magnificat.', 'Vês que Maria não duvidou, mas acreditou; e por isso alcançou o fruto da fé. Bem-aventurada, diz, tu que acreditaste. Mas também vós sois bem-aventurados, que ouvistes e acreditastes; porque toda a alma que crê concebe e gera o Verbo de Deus e reconhece as suas obras. …'),
  (7, 'São Beda, o Venerável', 'Catena Aurea de S. Tomás de Aquino, sobre Lc 1, lição 13 (trecho atribuído a Beda). Tradução a partir do latim do Corpus Thomisticum; a Catena atribui o trecho a Beda e não se conferiu na obra original de Beda.', 'Nem é de admirar que o Senhor, vindo para remir o mundo, tenha começado a sua obra pela Mãe: para que aquela por quem a salvação se preparava para todos fosse a primeira a colher, do Filho que trazia no seio, o fruto da salvação.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 2;

-- joyful-2 · Lc 1, 46-55
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então Maria disse: «A minha alma glorifica o Senhor; e o meu espírito exulta (de alegria) em Deus meu Salvador. Porque lançou os olhos para a baixeza da sua serva; portanto, eis que, de hoje em diante, todas as gerações me chamarão bem-aventurada. Porque fez em mim grandes coisas aquele que é poderoso, e cujo nome é santo. E cuja misericórdia (se estende) de geração em geração sobre aqueles que o temem. Manifestou o poder do seu braço; dissipou aqueles que se orgulhavam nos pensamentos do seu coração. Depôs do trono os poderosos, e elevou os humildes. Encheu de bens os famintos, e despediu vazios os ricos. Tomou cuidado de Israel, seu servo, lembrado da sua misericórdia; conforme tinha prometido a nossos pais, a Abraão e à sua posteridade para sempre.»', 'Lc 1, 46-55', 2
from public.mysteries m where m.type = 'joyful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Bernardo de Claraval', 'Sermo in dominica infra octavam Assumptionis B. V. Mariae (De duodecim praerogativis B. V. Mariae), n. 12 (texto abreviado). Tradução a partir do latim consultado em duas transcrições (colunas cerca de 436); não é o Lírio Católico nem uma edição portuguesa. As cópias online deturpam «dicta» («aicta» / «acta»); aqui segue-se o texto de Lc 1, 45 que Bernardo cita.', '… Chegou-se então a Isabel, e logo a glória singular da Virgem lhe foi revelada pelo Espírito. Admirava-se também da pessoa que vinha, dizendo: Donde me vem isto, que a Mãe do meu Senhor venha a mim? Louvava também a voz da que saudava, acrescentando: Quando a voz da tua saudação chegou aos meus ouvidos, o menino exultou de alegria no meu ventre; e chamava bem-aventurada a fé da que acreditou: Bem-aventurada, dizia, a que acreditou, porque se hão de cumprir em ti as coisas que te foram ditas da parte do Senhor. Grandes louvores, sem dúvida; mas a humildade devota não sofreu reter nada para si, e antes devolveu tudo àquele cujos benefícios nela eram louvados. Tu, diz ela, engrandeces a mãe do Senhor; mas a minha alma magnifica o Senhor. …'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 26-27 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', '… Esteja em cada um a alma de Maria, para engrandecer o Senhor; esteja em cada um o espírito de Maria, para exultar em Deus. Se, segundo a carne, uma só é a Mãe de Cristo, segundo a fé Cristo é fruto de todos; porque toda a alma recebe o Verbo de Deus, contanto que, imaculada e livre de vícios, guarde a castidade com pudor intacto. Toda a alma, pois, que puder ser assim engrandece o Senhor, como a alma de Maria engrandeceu o Senhor e o seu espírito exultou em Deus Salvador. …'),
  (2, 'São Beda, o Venerável', 'Catena Aurea de S. Tomás de Aquino, sobre Lc 1, lição 16 (dois trechos atribuídos a Beda, unidos; texto abreviado). Tradução a partir do latim do Corpus Thomisticum; a Catena atribui o trecho a Beda e não se conferiu na obra original de Beda.', 'Aquela cuja humildade é olhada por Deus é com razão chamada bem-aventurada por todos. … Convinha que, assim como pela soberba do primeiro pai a morte entrou no mundo, assim pela humildade de Maria se mostrasse a entrada da vida.'),
  (3, 'São Beda, o Venerável', 'Catena Aurea de S. Tomás de Aquino, sobre Lc 1, lição 17 (trecho atribuído a Beda). Tradução a partir do latim do Corpus Thomisticum; a Catena atribui o trecho a Beda e não se conferiu na obra original de Beda.', 'Isto remete para o início do cântico, onde se disse: A minha alma engrandece o Senhor; pois só a alma a quem o Senhor se digna fazer grandes coisas O pode engrandecer com louvores dignos.'),
  (4, 'São João Paulo II', 'Carta encíclica Redemptoris Mater, n. 36 (texto abreviado). Cita-se o início do número e a passagem sobre «grandes coisas» e «exulta»; omitem-se as citações conciliares e o fim, sobre Abraão (grafia adaptada ao Brasil).', 'Quando Isabel saudou a jovem parente, que acabava de chegar de Nazaré, Maria respondeu com o Magnificat. … As palavras usadas por Maria, no limiar da casa de Isabel, constituem uma profissão inspirada desta sua fé, na qual se exprime a resposta à palavra da revelação, com a elevação religiosa e poética de todo o seu ser no sentido de Deus. … Maria é a primeira a participar nesta nova revelação de Deus e, mediante ela, nesta nova «autodoação» de Deus. Por isso proclama: «Grandes coisas fez em mim ... e santo é o seu nome». As suas palavras refletem a alegria do espírito, difícil de exprimir: «O meu espírito exulta em Deus, meu Salvador». …'),
  (5, 'Catecismo da Igreja Católica', 'CIC 971 (texto abreviado). Omitem-se as notas e o fim da citação conciliar (grafia adaptada ao Brasil).', '«Todas as gerações me hão de proclamar ditosa» (Lc 1, 48): «a piedade da Igreja para com a santíssima Virgem pertence à própria natureza do culto cristão». A santíssima Virgem «é com razão venerada pela Igreja com um culto especial. E, na verdade, a santíssima Virgem é, desde os tempos mais antigos, honrada com o título de "Mãe de Deus", e sob a sua proteção se acolhem os fiéis implorando-a em todos os perigos e necessidades [...]». … Encontra a sua expressão nas festas litúrgicas dedicadas à Mãe de Deus e na oração mariana, como o santo rosário, «resumo de todo o Evangelho».'),
  (6, 'São Beda, o Venerável', 'Catena Aurea de S. Tomás de Aquino, sobre Lc 1, lição 18 (trecho atribuído a Beda). Tradução a partir do latim do Corpus Thomisticum; a Catena atribui o trecho a Beda e não se conferiu na obra original de Beda.', 'Passando dos dons especiais aos juízos gerais de Deus, descreve o estado de todo o gênero humano, acrescentando: E a sua misericórdia de geração em geração sobre aqueles que o temem; como se dissesse: não só a mim fez grandes coisas aquele que é poderoso, mas em toda nação quem teme a Deus lhe é aceito.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 2;

-- joyful-2 · Lc 1, 56
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Maria ficou com Isabel cerca de três meses; e (depois) voltou para sua casa.', 'Lc 1, 56', 3
from public.mysteries m where m.type = 'joyful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 21 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', '… Maria, séria em casa, apressada em público, ficou três meses com a sua parente. Com efeito, a que viera para servir permanecia no serviço. …'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro II, 29 (texto abreviado). Latim de la.wikisource (PL 15, col. 1560-1562), conferido com os excertos da Catena Aurea de S. Tomás (Corpus Thomisticum); tradução a partir do latim, não é edição portuguesa publicada.', 'Bem se mostra Santa Maria como quem cumpriu um serviço e guardou um número místico. Pois não foi só a familiaridade a causa de ter ficado tanto tempo, mas também o proveito de tão grande profeta. Porque, se à primeira chegada houve tão grande progresso que, à saudação de Maria, o menino exultou no ventre e a mãe do menino ficou cheia do Espírito Santo, quanto pensamos que terá acrescentado a presença de Santa Maria pelo convívio de tanto tempo? … Era ungido, pois, e como bom atleta se exercitava no ventre da mãe o profeta; porque a sua virtude se preparava para um combate amplíssimo. …'),
  (2, 'Bento XVI', 'Carta encíclica Deus caritas est, n. 41 (texto abreviado). Cita-se o início do número; o resto trata da fé de Maria e de Caná.', 'Entre os Santos, sobressai Maria, Mãe do Senhor e espelho de toda a santidade. No Evangelho de Lucas, encontramo-La empenhada num serviço de caridade à prima Isabel, junto da qual permanece «cerca de três meses» (1, 56) assistindo-a na última fase da gravidez. «Magnificat anima mea Dominum – A minha alma engrandece o Senhor» (Lc 1, 46), disse Ela por ocasião de tal visita, exprimindo assim todo o programa da sua vida: não colocar-Se a Si mesma ao centro, mas dar espaço ao Deus que encontra tanto na oração como no serviço ao próximo — só então o mundo se torna bom. …'),
  (3, 'São Beda, o Venerável', 'Catena Aurea de S. Tomás de Aquino, sobre Lc 1, lição 13 (trecho atribuído a Beda). Tradução a partir do latim do Corpus Thomisticum; a Catena atribui o trecho a Beda e não se conferiu na obra original de Beda.', 'Toda a alma que concebeu na mente o Verbo de Deus sobe logo, com o passo do amor, aos altos cumes das virtudes, para poder entrar na cidade de Judá, isto é, na cidadela da confissão e do louvor, e aí permanecer como que três meses, até a perfeição da fé, da esperança e da caridade.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 2;

-- joyful-3 · Lc 2, 4-7
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E José foi também da Galileia, da cidade de Nazaré, à Judeia, à cidade de David, que se chamava Belém, porque era da casa e família de David, para se recensear juntamente com Maria, sua esposa, que estava grávida. E, estando ali, aconteceu completarem-se os dias em que devia dar à luz. E deu à luz o seu filho primogênito, e o enfaixou, e o reclinou numa manjedoura, porque não havia lugar para eles na estalagem.', 'Lc 2, 4-7', 0
from public.mysteries m where m.type = 'joyful' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 526 (grafia adaptada ao Brasil)', '«Tornar-se criança» diante de Deus é a condição para entrar no Reino, e para isso, é preciso abaixar-se, tornar-se pequeno. Mais ainda: é preciso «nascer do Alto» (Jo 3, 7), «nascer de Deus» para se «tornar filho de Deus». O mistério do Natal cumpre-se em nós quando Cristo «Se forma» em nós. O Natal é o mistério desta «admirável permuta»: «O admirabile commercium! Creator generis humani, animatum corpus sumens de Virgine nasci dignatus est; et, procedens homo sine semine, largitus est nobis suam deitatem». – «Oh admirável permuta! O Criador do gênero humano, tomando corpo e alma, dignou-Se nascer duma Virgem; e, feito homem sem progenitor humano, tornou-nos participantes da sua divindade!»'),
  (1, 'Santo Ambrósio', 'Comentário ao Evangelho de São Lucas, livro II, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 2; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'Por tua causa a fraqueza, n''Ele o poder; por tua causa a pobreza, n''Ele a opulência. Não consideres o que vês, mas reconhece que foste resgatado. Mais devo, Senhor Jesus, às tuas injúrias, pelas quais fui remido, do que ao teu poder, pelo qual fui criado. De nada me aproveitaria ter nascido, se não me tivesse aproveitado também ser remido.'),
  (2, 'São João Crisóstomo', 'Texto que a Catena Aurea atribui a S. João Crisóstomo, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 2; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'Certamente, se quisesse, podia vir movendo o céu, abalando a terra, lançando raios; mas não veio assim, porque não queria perder, mas salvar, e desde os primeiros começos calcar aos pés a soberba humana. Por isso não Se faz somente homem, mas homem pobre, e escolheu uma mãe pobre, a quem falta até onde reclinar o Filho recém-nascido; por isso se segue: «e o reclinou numa manjedoura».'),
  (3, 'São Beda, o Venerável', 'Comentário a São Lucas, livro I, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 2; tradução a partir do latim da Catena (texto em corpusthomisticum.org) (texto abreviado)', 'Aquele que veste o mundo inteiro com variado ornato é envolto em pobres panos, para que nós possamos recuperar a primeira veste. … Aquele que tem o céu por trono é contido na estreiteza de uma dura manjedoura, para nos dilatar nas alegrias do reino celeste. Aquele que é o pão dos Anjos é reclinado numa manjedoura, para nos alimentar, como a animais santos, com o trigo da sua carne. … Aquele que está sentado à direita do Pai não encontra lugar na estalagem, para nos preparar muitas moradas na casa de seu Pai.'),
  (4, 'Santo Agostinho', 'Sermão 187, In Natali Domini, 1 (trad. Lírio Católico; texto abreviado). Numeração conferida com o Sermo CLXXXVII da edição de Migne (PL 38) em Wikisource, incipit «Laudem Domini loquetur os meum» e a frase «magnus dies Angelorum, parvus in die hominum».', 'A minha boca proclamará o louvor do Senhor: daquele Senhor por quem todas as coisas foram feitas, e que foi feito entre todas as coisas: … grande dia dos anjos, pequeno no dia dos homens: … fundador do sol, fundado sob o sol: … autor do céu e da terra, surgido sob o céu sobre a terra: … enchendo o mundo, jazendo numa manjedoura: … tão grande na forma de Deus, tão pequeno na forma de servo…'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte I, cap. II «Do santo Natal», 6ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que nos ensina Jesus Cristo com as circunstâncias do seu nascimento? — Com as circunstâncias do seu nascimento, Jesus Cristo ensina-nos a renunciar às vaidades do mundo e a apreciar a pobreza e os sofrimentos.»'),
  (6, 'São Pio X', 'Discurso à Cúria Romana pelos votos de Natal, 23 de dezembro de 1903 (AAS 36, 1903-04, pp. 321-324; tradução a partir do italiano em vatican.va)', 'A cabana de Belém é uma escola, de onde o divino Redentor começa o seu magistério, não com palavras, mas com obras, ensinando que o único meio de reabilitação é o sacrifício na pobreza e na dor.'),
  (7, 'Bento XVI', 'Homilia na Missa da Noite de Natal, 24 de dezembro de 2007 (texto abreviado; grafia adaptada ao Brasil)', '… Na hospedaria, porém, não havia lugar. De algum modo a humanidade espera Deus, a sua proximidade. Mas quando chega o momento, não tem lugar para Ele. Está tão ocupada consigo mesma, sente necessidade tão imperiosa de todo o espaço e de todo o tempo para as próprias coisas, que não resta nada para o outro: para o próximo, para o pobre, para Deus. E quanto mais ricos se tornam os homens, tanto mais preenchem tudo de si mesmos. Tanto menos pode entrar o outro.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 3;

-- joyful-3 · Lc 2, 8-14
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Ora, naquela mesma região, havia uns pastores que velavam e faziam de noite a guarda ao seu rebanho. E eis que apareceu junto deles um anjo do Senhor, e uma claridade divina os cercou, e tiveram grande temor. Porém o anjo disse-lhes: «Não temais; porque eis que vos anuncio uma grande alegria, que terá todo o povo. Nasceu-vos hoje na cidade de David um Salvador, que é o Cristo Senhor. E eis o (que vos servirá de) sinal: Encontrareis um menino envolto em panos, e deitado numa manjedoura.» E subitamente apareceu com o anjo uma multidão de milícia celeste louvando a Deus, e dizendo: «Glória a Deus no mais alto dos céus, e paz na terra aos homens, (objeto) da boa vontade (de Deus).»', 'Lc 2, 8-14', 1
from public.mysteries m where m.type = 'joyful' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 525 (grafia adaptada ao Brasil)', 'Jesus nasceu na humildade dum estábulo, no seio duma família pobre. As primeiras testemunhas deste acontecimento são simples pastores. E é nesta pobreza que se manifesta a glória do céu. A Igreja não se cansa de cantar a glória desta noite: «Hoje a Virgem dá à luz o Eterno e a terra oferece uma gruta ao Inacessível. Cantam-n''O os anjos e os pastores, e com a estrela os magos põem-se a caminho, porque Tu nasceste para nós, pequeno Infante. Deus eterno!»'),
  (1, 'São Leão Magno', 'Sermão 26 (In Nativitate Domini VI), 1 (PL 54, 213), na tradução portuguesa citada por Bento XVI, Audiência geral de 21 de dezembro de 2011 (grafia adaptada ao Brasil)', 'Hoje o Autor do mundo foi gerado do seio de uma virgem: Aquele que fez todas as coisas tornou-se filho de uma mulher, por Ele mesmo criada. Hoje, o Verbo de Deus apareceu revestido de carne e, embora nunca tivesse sido visível aos olhos humanos, tornou-se também visivelmente palpável. Hoje, os pastores ouviram da voz dos anjos que nasceu o Salvador, na substância do nosso corpo e da nossa alma.'),
  (2, 'Santo Agostinho', 'Sermão 185, In Natali Domini, 1 (trad. Lírio Católico; texto abreviado). Numeração conferida com o incipit latino «Natalis Domini dicitur» em augustinus.it e com o Sermo CLXXXV da edição de Migne (PL 38) em Wikisource.', 'Chama-se Natal do Senhor quando a Sabedoria de Deus se mostrou infante, e o Verbo de Deus, sem palavras, emitiu a voz da carne. Contudo, aquela divindade oculta foi tanto assinalada aos Magos pelo testemunho de uma estrela, quanto anunciada aos pastores pela voz de um anjo. Celebramos, pois, com solenidade anual este dia, no qual se cumpriu a profecia que diz: a Verdade brotou da terra, e a justiça olhou do céu. A Verdade, que está no seio do Pai, brotou da terra, para estar também no seio de uma mãe. A Verdade, pela qual o mundo é mantido, brotou da terra, para ser carregada por mãos de mulher. A Verdade, pela qual a bem-aventurança dos anjos é incorruptivelmente nutrida, brotou da terra, para ser amamentada por peitos carnais. A Verdade, para a qual o céu não basta, brotou da terra, para ser posta numa manjedoura. Para bem de quem veio tão grande sublimidade em tão grande humildade? Certamente para nenhum bem seu; mas para grande bem nosso, se cremos. Desperta, ó homem: por ti Deus se fez homem. …'),
  (3, 'São João Crisóstomo', 'Texto que a Catena Aurea atribui a S. João Crisóstomo, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 3; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'A José o Anjo apareceu em sonhos; aos pastores, porém, visivelmente, como a homens mais rudes. E o Anjo não foi a Jerusalém, não procurou os escribas e os fariseus, porque estavam corrompidos e atormentados pela inveja; estes, porém, eram sinceros e guardavam o antigo modo de viver dos patriarcas e de Moisés. A inocência é, com efeito, um caminho que conduz à verdadeira sabedoria.'),
  (4, 'São Beda, o Venerável', 'Comentário a São Lucas, livro I, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 3; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'Em nenhum lugar de toda a série do Antigo Testamento encontramos que os Anjos, que tão assiduamente apareceram aos patriarcas, tenham aparecido com luz. Este privilégio foi com razão reservado a este tempo, em que nasceu nas trevas a luz para os retos de coração; por isso se segue: «e uma claridade divina os cercou».'),
  (5, 'São Pio X', 'Discurso à Cúria Romana pelos votos de Natal, 23 de dezembro de 1903 (AAS 36, 1903-04, pp. 321-324; tradução a partir do italiano em vatican.va; texto abreviado)', 'A cabana de Belém, finalmente, é uma escola, na qual, se o cumprimento das divinas promessas não é revelado aos sábios e prudentes do século, mas somente aos pequeninos, isto é, aos simples pastores, não é porque Jesus quisesse preferir uma condição a outra. … Jesus não veio mudar esta ordem chamando somente os pobres, mas nasceu para todos. Tanto é verdade que, para mostrar este caráter de universalidade, quis nascer num lugar público, cujo acesso não podia ser impedido a ninguém; quis descender de sangue real, para que os príncipes não O desdenhassem; quis nascer pobre, para que todos, sem receio, pudessem ir a Ele; e, para Se fazer tudo para todos e para que ninguém tivesse medo de se aproximar d''Ele, apareceu menino.'),
  (6, 'Bento XVI', 'Homilia na Missa da Noite de Natal, 24 de dezembro de 2010 (texto abreviado; grafia adaptada ao Brasil)', 'Lucas não disse que os anjos cantaram. Muito sobriamente, escreve que o exército celeste louvava a Deus e dizia: «Glória a Deus nas alturas…» (Lc 2, 13-14). Mas desde sempre os homens souberam que o falar dos anjos é diverso do dos homens; e que, precisamente nesta noite da jubilosa mensagem, tal falar foi um canto no qual brilhou a glória sublime de Deus. … Diz Santo Agostinho: Cantare amantis est – cantar é próprio de quem ama. … Sim, Senhor, nós Vos damos graças por vossa imensa glória. Nós Vos damos graças pelo vosso amor. Fazei que nos tornemos cada vez mais pessoas que amam juntamente convosco e, consequentemente, pessoas de paz.'),
  (7, 'São Beda, o Venerável', 'Comentário a São Lucas, livro I, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 4; tradução a partir do latim da Catena (texto em corpusthomisticum.org) (texto abreviado)', 'Porque nasce Deus e homem, canta-se paz aos homens e glória a Deus. … Desejam também a paz aos homens, quando acrescentam: «e paz na terra aos homens»; porque aqueles que antes tinham desprezado como fracos e abjetos, agora, nascendo o Senhor na carne, já os veneram como companheiros. … E declaram a que homens pedem a paz, dizendo: «de boa vontade», isto é, àqueles que recebem o Cristo nascido; pois não há paz para os ímpios, mas muita paz para os que amam o nome de Deus.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 3;

-- joyful-3 · Lc 2, 15-20
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, depois que os anjos se retiraram deles para o céu, os pastores diziam entre si: «Vamos até Belém, e vejamos o que é que lá sucedeu, e o que é que o Senhor nos manifestou.» E foram com grande pressa, e encontraram Maria e José, e o Menino deitado na manjedoura. E, vendo isto, conheceram o que lhes tinha sido dito acerca deste Menino. E todos os que ouviram, se admiraram das coisas que lhes diziam os pastores. Ora Maria conservava todas estas coisas, meditando-as no seu coração. E os pastores voltaram, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, conforme lhes tinha sido dito.', 'Lc 2, 15-20', 2
from public.mysteries m where m.type = 'joyful' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Santo Ambrósio', 'Comentário ao Evangelho de São Lucas, livro II, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 5; tradução a partir do latim da Catena (texto em corpusthomisticum.org) (texto abreviado)', 'Não te pareça pequeno este exemplo de fé: não é vil a pessoa dos pastores; pois o que se procura é a simplicidade, não se deseja a ambição. Segue-se: «e foram com grande pressa»; porque ninguém procura a Cristo com preguiça.'),
  (1, 'São Beda, o Venerável', 'Comentário a São Lucas, livro I, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 5; tradução a partir do latim da Catena (texto em corpusthomisticum.org) (texto abreviado)', 'A exemplo destes pastores, passemos, pois, rejeitados os desejos carnais, com todo o desejo da alma até à Belém do alto, isto é, à casa do pão vivo, para que Aquele que eles viram chorando na manjedoura, nós mereçamos vê-Lo reinando no trono do Pai. Não se deve procurar tão grande bem-aventurança com negligência e torpor, mas é preciso seguir com prontidão os passos de Cristo. … Também nós apressemo-nos a abraçar com pleno amor o que foi dito do nosso Salvador, para que o possamos compreender no futuro, na visão do conhecimento perfeito.'),
  (2, 'Bento XVI', 'Homilia na Missa da Noite de Natal, 24 de dezembro de 2009 (texto abreviado; grafia adaptada ao Brasil)', '«Apressaram-se»: diz, literalmente, o texto grego. O que lhes fora anunciado era tão importante que deviam ir imediatamente. … Na nossa vida ordinária, as coisas não acontecem assim. A maioria dos homens não considera prioritárias as coisas de Deus. … O Evangelho diz-nos: Deus tem a máxima prioridade. Se alguma coisa na nossa vida merece a nossa pressa sem demora, isso só pode ser a causa de Deus. … É precisamente esta prioridade que nos ensinam os pastores. Deles queremos aprender a não deixar-nos esmagar por todas as coisas urgentes da vida de cada dia. Deles queremos aprender a liberdade interior de colocar em segundo plano outras ocupações – por mais importantes que sejam – a fim de nos encaminharmos para Deus, a fim de O deixarmos entrar na nossa vida e no nosso tempo.'),
  (3, 'Santo Ambrósio', 'Comentário ao Evangelho de São Lucas, livro II, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 5; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'Não julgues desprezíveis, como coisa vil, as palavras dos pastores: pois dos pastores Maria recolhe a fé; por isso se segue: «Ora Maria conservava todas estas coisas, meditando-as no seu coração». Aprendamos a castidade da santa Virgem em todas as coisas, que, não menos pura nos lábios do que no corpo, meditava no coração os argumentos da fé.'),
  (4, 'São Beda, o Venerável', 'Comentário a São Lucas, livro I, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 2, lição 5; tradução a partir do latim da Catena (texto em corpusthomisticum.org)', 'Guardando as leis do pudor virginal, não queria divulgar a ninguém os segredos de Cristo que conhecia; mas comparava o que lera que havia de se cumprir com o que agora via cumprido, não o proferindo com a boca, mas guardando-o fechado no coração.'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte I, cap. II «Do santo Natal», 5ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que pretende a Igreja ao propor-nos a consideração dos mistérios das três Missas do Natal? — Ao propor-nos a consideração dos mistérios das três Missas do Natal, a Igreja pretende que agradeçamos ao divino Redentor o ter-Se feito homem para nossa salvação, que O reconheçamos juntamente com os pastores e O adoremos como verdadeiro Filho de Deus, escutando as instruções que Ele tacitamente nos dá com as circunstâncias do seu nascimento.»')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 3;

-- joyful-4 · Lc 2, 22-24
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, depois que foram concluídos os dias da purificação de Maria, segundo a lei de Moisés, levaram-no a Jerusalém para o apresentarem ao Senhor, segundo o que está escrito na lei do Senhor: Todo o varão primogênito será consagrado ao Senhor; e para oferecerem em sacrifício, conforme o que (também) está escrito na lei do Senhor, um par de rolas ou dois pombinhos.', 'Lc 2, 22-24', 0
from public.mysteries m where m.type = 'joyful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. IV «Da Purificação de Maria Virgem», 4ª pergunta do capítulo. Tradução a partir do italiano.', '— Por que se sujeitou a Santíssima Virgem à lei da purificação, à qual não estava obrigada? — A Santíssima Virgem sujeitou-se à lei da purificação, à qual não estava obrigada, para nos dar exemplo de humildade e de obediência à lei de Deus.'),
  (1, 'São Tomás de Aquino', 'Suma Teológica, III, q. 37, a. 4, respondeo (tradução integral do latim; não é texto original em português)', 'Assim como a plenitude da graça deriva de Cristo para a Mãe, assim convinha que a Mãe se conformasse à humildade do Filho, pois Deus dá a graça aos humildes, como se diz na carta de Tiago. Por isso, assim como Cristo, embora não estivesse sujeito à Lei, quis submeter-se à circuncisão e aos outros encargos da Lei, para dar exemplo de humildade e de obediência, para aprovar a Lei e para tirar aos judeus ocasião de calúnia, pelas mesmas razões quis que também a sua Mãe cumprisse as observâncias da Lei, às quais, contudo, não estava sujeita.'),
  (2, 'São Beda, o Venerável', 'Homilia na Purificação de Santa Maria (Hom. I, 18), citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 7 (tradução a partir do latim)', 'Se considerares com mais atenção as próprias palavras da lei, verás que a Mãe de Deus, assim como é isenta de união com varão, assim também o é da obrigação legal. Pois não é toda a mulher que dá à luz que é declarada impura e mandada purificar pelo rito, mas aquela que concebeu de semente recebida; para a distinguir daquela que virgem concebeu e deu à luz. Mas, para que nós fôssemos soltos do vínculo da lei, assim como Cristo, também a bem-aventurada Maria se sujeitou espontaneamente à lei.'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 37, a. 3, ad 2 (citando Santo Atanásio e São Beda; tradução própria, conferida com o latim da Catena Aurea in Lc 2, lect. 7, e com a versão inglesa dos Dominicanos)', 'Assim como o Filho de Deus se fez homem e foi circuncidado na carne, não por causa de si mesmo, mas para nos fazer deuses pela graça e para que fôssemos circuncidados espiritualmente, assim também por nós é apresentado ao Senhor, para que aprendamos a apresentar-nos a nós mesmos a Deus. E isto se fez depois da sua circuncisão, para mostrar que ninguém, se não estiver circuncidado dos vícios, é digno do olhar divino.'),
  (4, 'São Beda, o Venerável', 'Homilia na Purificação de Santa Maria (Hom. I, 18), citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 7 (tradução a partir do latim; texto abreviado)', 'Esta era a oferta dos pobres. … Assim o Senhor, sendo rico, dignou-se fazer-se pobre, para nos tornar participantes das suas riquezas pela sua pobreza. … A pomba significa a simplicidade, a rola a castidade: porque a pomba é amante da simplicidade e a rola da castidade, de tal modo que, se por acaso perde o seu par, não cuida de procurar outro. Com razão, pois, a rola e a pomba são oferecidas ao Senhor em sacrifício: porque a vida simples e pudica dos fiéis é para Ele um agradável sacrifício de justiça.'),
  (5, 'São Bernardo de Claraval', 'In Purificatione Beatae Mariae, sermo III, 2 (PL 183, 370) (texto abreviado; tradução do latim)', 'Verdadeiramente, ó bem-aventurada Virgem, verdadeiramente não tens motivo, nem te é necessária a purificação. … Oferece o teu Filho, Virgem sagrada, e apresenta ao Senhor o fruto bendito do teu ventre. Oferece, para reconciliação de todos nós, uma vítima santa, agradável a Deus. … Mas esta oblação, irmãos, parece assaz delicada, quando apenas é apresentado ao Senhor, resgatado com aves e logo reconduzido. Virá quando não será oferecido no templo, nem entre os braços de Simeão, mas fora da cidade, entre os braços da cruz. … Aquela será o sacrifício vespertino; esta é o matutino.'),
  (6, 'São Paulo VI', 'Marialis Cultus, 20 (texto abreviado)', 'Maria é, enfim, a Virgem oferente. … A mesma Igreja, sobretudo a partir dos séculos da Idade Média, entreviu no coração da Virgem Maria, que leva o Filho a Jerusalém «para o oferecer ao Senhor» (cf. Lc 2,22), uma vontade oblativa, que transcendia o sentido ordinário do rito. … Esta união da Mãe com o Filho na obra da Redenção alcança o ponto culminante no Calvário, onde Cristo «se ofereceu a si mesmo a Deus como vítima sem mancha» (Hb 9,14), e onde Maria esteve de pé, junto à Cruz (cf. Jo 19,25) …')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 4;

-- joyful-4 · Lc 2, 25-35
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Havia então em Jerusalém um homem, chamado Simeão, e este homem (era) justo e temente (a Deus), e esperava a consolação de Israel; e o Espírito Santo estava nele. … ele também o tomou em seus braços, e louvou a Deus, dizendo: «Agora, Senhor, podes deixar partir o teu servo em paz, segundo a tua palavra; porque os meus olhos viram a tua salvação, a qual preparaste ante a face de todos os povos; luz para iluminar as nações, e glória de Israel, teu povo.» … E Simeão os abençoou, e disse a Maria, sua mãe: «Eis que este (Menino) está posto para ruína e para ressurreição de muitos em Israel, e para ser alvo de contradição. E uma espada trespassará a tua alma, a fim de se descobrirem os pensamentos escondidos nos corações de muitos.»', 'Lc 2, 25-35', 1
from public.mysteries m where m.type = 'joyful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 529 (grafia adaptada ao Brasil)', 'A apresentação de Jesus no templo mostra-O como Primogênito que pertence ao Senhor. Com Simeão e Ana, é toda a expectativa de Israel que vem ao encontro do seu Salvador (a tradição bizantina designa por encontro este acontecimento). Jesus é reconhecido como o Messias tão longamente esperado, «luz das nações» e «glória de Israel», mas também como «sinal de contradição». A espada de dor, predita a Maria, anuncia essa outra oblação, perfeita e única, da cruz, que trará a salvação que Deus «preparou diante de todos os povos».'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. IV «Da Purificação de Maria Virgem», 9ª pergunta do capítulo. Tradução a partir do italiano.', '— Que fez Simeão quando Jesus Menino foi apresentado no templo? — Quando Jesus Menino foi apresentado no templo, Simeão tomou-o em seus braços e, dando graças ao Senhor, disse o cântico Nunc dimittis, com o qual exprimiu que morria contente depois de ter visto o Salvador; predisse, além disso, as contradições que Jesus Cristo havia de sofrer e as penas que por elas havia de sentir a sua santa Mãe.'),
  (2, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, II (sobre Lc 2, 29), citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 9 (tradução a partir do latim)', 'Vê o justo, como que encerrado no cárcere da massa corpórea, desejar ser solto, para começar a estar com Cristo. Mas quem quer ser despedido, venha ao templo, venha a Jerusalém, espere o Cristo do Senhor, receba nas mãos o Verbo de Deus e abrace-o como com os braços da sua fé; então será despedido, para não ver a morte, aquele que tiver visto a vida.'),
  (3, 'São Sofrônio de Jerusalém', 'Orat. 3 de Hypapante, 6-7 (PG 87, 3, 3291-3293) (texto abreviado; grafia adaptada ao Brasil)', 'Todos nós que celebramos e veneramos com tanta piedade o mistério do Encontro do Senhor, corramos para Ele com todo o fervor do nosso espírito. Ninguém deixe de participar neste Encontro, ninguém se recuse a levar a sua luz. … Nenhum fique excluído deste esplendor, nenhum persista em continuar imerso na noite, mas avancemos todos resplandecentes; iluminados por este fulgor, vamos todos juntos ao seu encontro e com o velho Simeão recebamos a luz clara e eterna; associemo-nos à sua alegria e cantemos com ele um hino de ação de graças ao Pai da luz, que enviou a luz verdadeira e, afastando todas as trevas, nos fez participantes do seu esplendor. A salvação de Deus, com efeito, preparada diante de todos os povos, manifestou a glória que nos pertence a nós, que somos o novo Israel; e nós próprios, graças a Ele, vimos essa salvação e fomos absolvidos da antiga e tenebrosa culpa, tal como Simeão, depois de ver a Cristo, foi libertado dos laços da vida presente. …'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. IV «Da Purificação de Maria Virgem», 14ª pergunta do capítulo. Tradução a partir do italiano.', '— Como devemos nós assistir à procissão que se faz na festa da Purificação? — Assistindo à procissão que se faz na festa da Purificação, devemos renovar a fé em Jesus Cristo, nossa verdadeira luz, e pedir-lhe que nos ilumine com a sua graça e nos torne dignos de ser um dia admitidos no templo da glória, pela intercessão da sua santíssima Mãe.'),
  (5, 'São João Crisóstomo', 'citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 10 (tradução a partir do latim; texto abreviado)', 'Assim como a luz, ainda que perturbe os olhos fracos, continua a ser luz, assim o Salvador permanece, ainda que muitos caiam; pois a destruição não é obra sua, mas da loucura deles. … A ressurreição é uma vida nova: quando o lascivo se torna casto, o avarento misericordioso, o cruel manso, celebra-se uma ressurreição, morto o pecado e ressurgindo a justiça.'),
  (6, 'São João Paulo II', 'Rosarium Virginis Mariae, 20 (texto abreviado; grafia adaptada ao Brasil)', '… Os dois últimos mistérios, porém, mesmo conservando o sabor da alegria antecipam já os sinais do drama. A apresentação no templo, de fato, enquanto exprime a alegria da consagração e extasia o velho Simeão, registra também a profecia do « sinal de contradição » que o Menino será para Israel e da espada que trespassará a alma da Mãe (cf. Lc 2, 34-35). …'),
  (7, 'São João Paulo II', 'Redemptoris Mater, 16 (texto abreviado; grafia adaptada ao Brasil)', '… Maria, um pouco mais tarde, ouve outras palavras: aquelas que foram pronunciadas por Simeão, no templo de Jerusalém. Estava-se já no quadragésimo dia depois do nascimento de Jesus, quando Maria e José, segundo a prescrição da Lei de Moisés, «levaram o menino a Jerusalém, para o oferecer ao Senhor» (Lc 2, 22). … Nessa mesma altura, porém, Simeão dirige-se a Maria com as seguintes palavras: «Ele é destinado a ser ocasião de queda e de ressurgimento para muitos em Israel e a ser um sinal de contradição... a fim de se revelarem os pensamentos de muitos corações»; e acrescenta, com referência direta a Maria: «E tu mesma terás a alma trespassada por uma espada» (Lc 2, 34-35). … Aquilo que Simeão diz apresenta-se como um segundo anúncio a Maria, uma vez que indica a dimensão histórica concreta em que o Filho realizará a sua missão, ou seja, na incompreensão e na dor. Se este outro anúncio confirma, por um lado, a sua fé no cumprimento das promessas divinas da salvação, por outro, também lhe revela que ela terá que viver a sua obediência de fé no sofrimento, ao lado do Salvador que sofre, e que a sua maternidade será obscura e marcada pela dor. …')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 4;

-- joyful-4 · Lc 2, 36-39
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Havia também uma profetisa, (chamada) Ana, filha de Fanuel, da tribo de Aser; estava em idade muito avançada, e tinha vivido sete anos com seu marido, desde a sua virgindade. E (tinha permanecido) viúva até aos oitenta e quatro anos; e não se afastava do templo servindo a Deus noite e dia com jejuns e orações. Ela também, sobrevindo nesta mesma ocasião, louvava o Senhor, e falava dele a todos os que esperavam a redenção de Israel. Depois que cumpriram tudo, segundo o que mandava a lei do Senhor, voltaram para a Galileia, para a sua cidade de Nazaré.', 'Lc 2, 36-39', 2
from public.mysteries m where m.type = 'joyful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. IV «Da Purificação de Maria Virgem», 10ª pergunta do capítulo. Tradução a partir do italiano.', '— Quando Jesus Cristo foi apresentado no templo, que fez a profetisa Ana? — Quando Jesus Cristo foi apresentado no templo, a profetisa Ana louvava e agradecia ao Senhor por ter enviado o Salvador do mundo, e falava dele a todos os que esperavam a sua vinda.'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, II (sobre Lc 2, 36-37), citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 11 (tradução a partir do latim; texto abreviado)', 'Profetizara Simeão, profetizara uma mulher unida em matrimônio, profetizara uma virgem; devia profetizar também uma viúva, para que não faltasse nenhum estado nem nenhum sexo. … Ana, pelos méritos da viuvez e pelos costumes, é apresentada de tal modo que se crê ter sido digna de anunciar o Redentor de todos.'),
  (2, 'São Beda, o Venerável', 'Exposição sobre o Evangelho de S. Lucas, I (sobre Lc 2, 36-37), citado por S. Tomás de Aquino, Catena Aurea in Lc 2, lect. 11 (tradução a partir do latim; texto abreviado)', 'Segundo o sentido místico, Ana significa a Igreja, que no tempo presente está como que viúva pela morte do seu Esposo. O número dos anos da sua viuvez designa o tempo em que a Igreja, enquanto vive no corpo, peregrina longe do Senhor. … Por isso, quer a Igreja universal, quer qualquer alma fiel que procura consagrar todo o tempo da sua vida aos ensinamentos apostólicos, é louvada por servir ao Senhor oitenta e quatro anos. … Ana, que se interpreta “graça dele”, é filha de Fanuel, que quer dizer “face de Deus”, e descende da tribo de Aser, isto é, “bem-aventurado”.'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. IV «Da Purificação de Maria Virgem», 11ª pergunta do capítulo. Tradução a partir do italiano.', '— Que devemos nós aprender dos mistérios da Purificação de Maria Virgem e da Apresentação de Jesus Cristo? — Dos mistérios da Purificação de Maria Virgem e da Apresentação de Jesus Cristo devemos aprender principalmente três coisas: a cumprir exatamente a lei de Deus, e não buscar pretextos para nos dispensarmos de a observar; a desejar só a Deus, e oferecer-nos a Ele para fazer a sua divina vontade; a ter grande estima da humildade, e purificar-nos cada vez mais com a penitência.')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 4;

-- joyful-5 · Lc 2, 41-45
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Seus pais iam todos os anos a Jerusalém, no dia solene da Páscoa. E, quando chegou aos doze anos, indo eles a Jerusalém segundo o costume daquela festa, acabados os dias (que ela durava), quando voltaram, ficou o Menino Jesus em Jerusalém, sem que seus pais o advertissem. E, julgando que ele fosse na comitiva, caminharam uma jornada, e (depois) procuravam-no entre os parentes e conhecidos. E, não o encontrando, voltaram a Jerusalém em busca dele.', 'Lc 2, 41-45', 0
from public.mysteries m where m.type = 'joyful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Beda, o Venerável', 'Comentário a S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim; texto abreviado)', '«Que o Senhor fosse todos os anos a Jerusalém pela Páscoa com seus pais é sinal da humildade humana: é próprio do homem acorrer a oferecer sacrifícios a Deus e torná-lo propício com orações. … Sigamos, pois, o caminho da sua vida humana, se nos deleitamos em contemplar a glória da sua divindade.»'),
  (1, 'Orígenes', 'Homilias sobre S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim; texto abreviado)', '«Não é encontrado logo que é procurado: Jesus não se encontra entre os parentes e os próximos segundo a carne, pois o parentesco humano não podia conter o Filho de Deus. Não se encontra entre os conhecidos, porque é maior que todo conhecimento mortal. … Na companhia de muitos não pode ser encontrado.»'),
  (2, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 8 («Da familiar amizade de Jesus»), nn. 1 e 3 (texto abreviado; tradução a partir do latim)', '«Quando Jesus está presente, tudo é bom e nada parece difícil; mas quando Jesus não está presente, tudo é duro. … Quão árido e duro és sem Jesus! … Não é isto dano maior do que se perdesses o mundo inteiro?» … «Grande arte é saber conversar com Jesus, e grande prudência saber retê-lo.»'),
  (3, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 7 («Do amor de Jesus sobre todas as coisas»), n. 3 (texto abreviado; tradução a partir do latim)', '«Se em todas as coisas procuras Jesus, certamente acharás Jesus. Mas se procuras a ti mesmo, também acharás a ti mesmo, porém para tua ruína.»'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. III «Da Ave-Maria», 14ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que nos ensinam os Santos sobre a devoção a Maria? — Sobre a devoção a Maria, os Santos nos ensinam que os seus verdadeiros devotos são amados e protegidos por Ela com amor de terníssima Mãe, e que por meio dela têm a certeza de encontrar Jesus e de alcançar o paraíso.»')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 5;

-- joyful-5 · Lc 2, 46-50
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E aconteceu que, três dias depois, o encontraram no templo sentado no meio dos doutores, ouvindo-os e interrogando-os. E todos os que ouviam estavam maravilhados da sua sabedoria e das suas respostas. Quando o viram, admiraram-se. E sua Mãe disse-lhe: «Filho, por que procedeste assim conosco? Eis que teu pai e eu te procurávamos cheios de aflição.» E ele disse-lhe: «Para que me buscáveis? Não sabíeis que devo ocupar-me nas coisas de meu Pai?» E eles não entenderam o que lhes disse.', 'Lc 2, 46-50', 1
from public.mysteries m where m.type = 'joyful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Orígenes', 'Homilias sobre S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim)', '«Não o encontraram em toda parte, mas no templo. Procura, pois, também tu a Jesus no templo de Deus, procura-o na Igreja, onde acharás a palavra e a sabedoria de Cristo, isto é, o Filho de Deus.»'),
  (1, 'Orígenes', 'Homilias sobre S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim; texto abreviado)', '«Por que o procuravam aflitos? … Assim como tu, quando lês as Escrituras, procuras nelas o sentido com dor, … assim eles procuravam Jesus. Convém, pois, que quem procura Jesus não o procure com negligência e descuido, como muitos que procuram e não encontram, mas com trabalho e com dor.»'),
  (2, 'Santo Agostinho', 'Sermão 51, 17-18 (tradução a partir da versão inglesa da série Nicene and Post-Nicene Fathers; texto abreviado)', '«Encontraram-no a discutir no templo com os anciãos … Mas que admira? A Palavra de Deus nunca se cala, ainda que nem sempre seja ouvida.» … «Era humílima: nem sequer se antepôs ao marido na ordem dos nomes, dizendo "eu e teu pai", mas diz: "Teu pai e eu". Não olhou à alta honra do seu seio, mas à ordem do matrimônio; pois Cristo, humilde, não teria ensinado a sua Mãe a ser soberba.»'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 12, a. 3, ad 1 (tradução a partir do latim)', '«Como diz Orígenes, o Senhor interrogava, não para aprender alguma coisa, mas para ensinar interrogando. Pois de uma única fonte de doutrina brotam o interrogar e o responder sabiamente.»'),
  (4, 'São Beda, o Venerável', 'Comentário a S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim)', '«Não os repreende por procurarem o Filho, mas obriga-os a levantar os olhos da mente para aquilo que Ele deve Àquele de quem é Filho eterno.»'),
  (5, 'Santo Ambrósio', 'Exposição sobre S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 13 (tradução a partir do latim)', '«Depois de três dias é encontrado no templo, para que fosse sinal de que, três dias depois da sua paixão triunfal, Aquele que se julgava morto, ressuscitando, se mostraria à nossa fé no trono celeste e na honra divina.»'),
  (6, 'Catecismo da Igreja Católica', 'CIC 534 (grafia adaptada ao Brasil)', '«O reencontro de Jesus no templo é o único acontecimento que quebra o silêncio dos evangelhos sobre os anos ocultos de Jesus. Nele, Jesus deixa entrever o mistério da sua consagração total à missão decorrente da sua filiação divina: "Não sabíeis que Eu tenho de estar na casa do meu Pai?". Maria e José "não compreenderam" esta palavra, mas acolheram-na na fé, e Maria "guardava no coração todas estas recordações", ao longo dos anos em que Jesus permaneceu oculto no silêncio duma vida normal.»')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 5;

-- joyful-5 · Lc 2, 51-52
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E desceu com eles, e foi a Nazaré, e era-lhes submisso. E sua mãe conservava todas estas coisas no seu coração. E Jesus crescia em sabedoria, em idade e em graça diante de Deus e diante dos homens.', 'Lc 2, 51-52', 2
from public.mysteries m where m.type = 'joyful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Bernardo de Claraval', 'Homilia I super Missus est, 7-8 (Lc 2,51)', '«"E era submisso a eles." Quem, a quem? Deus, aos homens. … Deus … era submisso a Maria, e não somente a Maria, mas também a José, por causa de Maria. … Aprende, ó homem, a obedecer.»'),
  (1, 'Santo Agostinho', 'Sermão 51, 19 (tradução a partir da versão inglesa da série Nicene and Post-Nicene Fathers; texto abreviado)', '«Não disse: era submisso à mãe, mas: era-lhes submisso. … Era submisso a ambos os pais, pela mesma condescendência pela qual era Filho do homem. … O mundo estava sujeito a Cristo, e Cristo estava sujeito a seus pais.»'),
  (2, 'Santo Ambrósio', 'Exposição sobre S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 14 (tradução a partir do latim; texto abreviado)', '«E admiras-te de que preste deferência ao pai Aquele que se submete à mãe? Não é, de fato, sujeição de fraqueza, mas de piedade. … Prestava deferência à serva, prestava deferência ao que passava por seu pai.»'),
  (3, 'São Beda, o Venerável', 'Comentário a S. Lucas, citado na Catena Aurea de S. Tomás de Aquino, in Lc 2, lect. 14 (tradução a partir do latim)', '«A Virgem, quer o que entendia, quer o que ainda não podia entender, tudo igualmente guardava no seu coração, como para o ruminar e perscrutar com mais diligência.»'),
  (4, 'São Tomás de Aquino', 'Suma Teológica, III, q. 7, a. 12, ad 3 (tradução a partir do latim)', '«Na sabedoria e na graça pode alguém progredir de dois modos. De um modo, segundo os próprios hábitos da sabedoria e da graça, aumentados; e assim Cristo não progredia neles. De outro modo, segundo os efeitos, isto é, enquanto alguém faz obras mais sábias e mais virtuosas; e assim Cristo progredia em sabedoria e graça, como também em idade, porque, com o avançar da idade, fazia obras mais perfeitas, para se mostrar verdadeiro homem, tanto nas coisas que são de Deus como nas que são dos homens.»'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte III, cap. III «Dos mandamentos que se referem ao próximo», 6ª pergunta do capítulo. Tradução a partir do italiano.', '«— Deu-nos Deus o exemplo de uma família perfeita? — Deus nos deu o exemplo de uma família perfeita na Sagrada Família, na qual Jesus Cristo viveu sujeito a Maria Santíssima e a São José até os trinta anos, isto é, até quando começou a exercer a missão, confiada pelo Eterno Pai, de pregar o Evangelho.»'),
  (6, 'Leão XIII', 'Encíclica Laetitiae sanctae (1893), 7 (texto abreviado)', '«Eis diante do nosso olhar a Casa de Nazaré, onde toda santidade, a humana e a divina, colocou a sua morada. Que exemplo de vida comum! Que perfeito modelo de sociedade! … reina ali a maior serenidade de ânimo e alegria de espírito: duas coisas que sempre acompanham a consciência do dever cumprido.»'),
  (7, 'Catecismo da Igreja Católica', 'CIC 564 (grafia adaptada ao Brasil)', '«Pela sua submissão a Maria e a José, assim como pelo seu trabalho humilde em Nazaré durante longos anos, Jesus dá-nos o exemplo da santidade na vida quotidiana da família e do trabalho.»')
) as v(sort_order, author, source, text) on true
where m.type = 'joyful' and m.sort_order = 5;

-- luminous-1 · Mt 3, 13-15
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então foi Jesus da Galileia ao Jordão ter com João, para ser batizado por ele. Mas João opunha-se-lhe, dizendo: «Sou eu que devo ser batizado por ti, e tu vens a mim?» E, respondendo Jesus, disse-lhe: «Deixa por agora, pois convém que cumpramos assim toda a justiça.» Ele então deixou-o (aproximar-se).', 'Mt 3, 13-15', 0
from public.mysteries m where m.type = 'luminous' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 536 (grafia adaptada ao Brasil)', 'Da parte de Jesus, o seu batismo é a aceitação e a inauguração da sua missão de Servo sofredor. Deixa-se contar entre o número dos pecadores. É já «o Cordeiro de Deus que tira o pecado do mundo» (Jo 1, 29), e antecipa já o «batismo» da sua morte sangrenta. Vem, desde já, para «cumprir toda a justiça» (Mt 3, 15). … A esta aceitação responde a voz do Pai, que põe toda a sua complacência no Filho. … No batismo de Cristo, «abriram-se os céus» (Mt 3, 16) que o pecado de Adão tinha fechado, e as águas são santificadas pela descida de Jesus e do Espírito, prelúdio da nova criação.'),
  (1, 'São Gregório de Nazianzo', 'Sermão 39, *In sancta Lumina*, 14-15 (PG 36, 350-351); Liturgia das Horas, Ofício de Leituras da Festa do Batismo do Senhor (tradução brasileira; texto abreviado)', 'João batiza e Jesus se aproxima; talvez para santificar igualmente aquele que o batiza e, sem dúvida, para sepultar nas águas o velho Adão. Antes de nós, e por nossa causa, ele que é Espírito e carne santificou as águas do Jordão, para assim nos iniciar nos sacramentos mediante o Espírito e a água. João reluta, Jesus insiste. «Eu é que devo ser batizado por ti», diz a lâmpada ao Sol, a voz à Palavra, o amigo ao Esposo, diz o maior entre todos os nascidos de mulher ao Primogênito de toda criatura …'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 39, a. 1 (tradução portuguesa publicada; grafia adaptada ao Brasil)', 'Cristo devia ser batizado. Primeiro, porque, como diz Ambrósio, o Senhor foi batizado, não por querer purificar-se; mas para purificar as águas que, purificadas assim pelo corpo de Cristo, isento de pecado, pudessem servir para o batismo e a fim de deixar para o futuro as águas santificadas para os que devessem ser batizados, como ensina Crisóstomo. … Terceiro, Cristo quis ser batizado, porque, como diz Agostinho, quis fazer o que ordenou a todos fazerem … «Assim nos convém cumprir toda a justiça» (Mt 3, 15).'),
  (3, 'São Máximo de Turim', 'Sermão 100, *De sancta Epiphania*, 3 (CCL 23, 398-400); Liturgia das Horas, Ofício de Leituras da sexta-feira depois da Epifania (tradução brasileira; texto abreviado)', 'Talvez alguém diga: «Se ele era santo, por que quis ser batizado?» Escuta: Cristo foi batizado, não para ser santificado pelas águas, mas para santificá-las e para purificar as torrentes com o contato de seu corpo. A consagração de Cristo é sobretudo a consagração da água. … Cristo nos precede no batismo para que os povos cristãos sigam confiantemente o seu exemplo.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 537 (texto abreviado; o parágrafo prossegue com citações de S. Gregório de Nazianzo e S. Hilário; grafia adaptada ao Brasil)', 'Pelo Batismo, o cristão é sacramentalmente assimilado a Jesus que, no seu batismo, antecipa a sua morte e ressurreição. Deve entrar neste mistério de humilde abatimento e de penitência, descer à água com Jesus, para de lá subir com Ele, renascer da água e do Espírito para se tornar, no Filho, filho-amado do Pai e «viver numa vida nova» (Rm 6, 4) …'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. II «Do Batismo», 18ª e 19ª perguntas do capítulo. Tradução a partir do italiano.', '— Quem recebe o Batismo, a que fica obrigado? — Quem recebe o Batismo fica obrigado a professar sempre a fé e a observar a lei de Jesus Cristo e da sua Igreja. — A que se renuncia ao receber o santo Batismo? — Ao receber o santo Batismo, renuncia-se para sempre ao demônio, às suas obras e às suas pompas.'),
  (6, 'São Luís Maria Grignion de Montfort', '*Tratado da Verdadeira Devoção à Santíssima Virgem*, n. 126; Liturgia das Horas, Ofício de Leituras de São Luís Maria Grignion de Montfort, 28 de abril (tradução brasileira; texto abreviado)', 'Devemos considerar que todo o homem, quando é batizado, renuncia solenemente, pela sua própria boca ou pela do seu padrinho e madrinha, a Satanás e às suas tentações e obras, e toma Jesus Cristo como seu Mestre e soberano Senhor, a fim de depender dele na qualidade de escravo de amor. É o que realmente se faz nesta devoção: o cristão renuncia ao demônio, ao mundo, ao pecado e a si mesmo, e consagra-se totalmente a Jesus Cristo pelas mãos de Maria.'),
  (7, 'São Luís Maria Grignion de Montfort', '*Tratado da Verdadeira Devoção à Santíssima Virgem*, n. 127 (tradução a partir do original francês; texto abreviado)', 'Quem é que guarda este grande voto? Quem é que cumpre fielmente as promessas do santo batismo? Não faltam quase todos os cristãos à fidelidade que prometeram a Jesus Cristo no seu batismo? Donde pode vir este desregramento universal, senão do esquecimento em que se vive das promessas e compromissos do santo batismo, e de quase ninguém ratificar por si mesmo o contrato de aliança que fez com Deus por meio dos seus padrinhos e madrinhas? …')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 1;

-- luminous-1 · Mt 3, 16-17
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, depois que Jesus foi batizado, saiu logo da água; e eis que se lhe abriram os céus, e viu o Espírito de Deus descer como pomba, e vir sobre ele. E eis (que se ouviu) uma voz do céu, que dizia: «Este é meu filho, o amado, no qual pus as minhas complacências.»', 'Mt 3, 16-17', 1
from public.mysteries m where m.type = 'luminous' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Gregório de Nazianzo', 'Sermão 39, *In sancta Lumina*, 14-16 (PG 36, 350-351); Liturgia das Horas, Ofício de Leituras da Festa do Batismo do Senhor (tradução brasileira; texto abreviado)', 'Cristo é iluminado no batismo, recebemos com ele a luz; Cristo é batizado, desçamos com ele às águas para com ele subirmos. … Jesus sai das águas, elevando consigo o mundo que estava submerso, e vê abrirem-se os céus de par em par, que Adão tinha fechado para si e sua posteridade, assim como o paraíso lhe fora fechado por uma espada de fogo. O Espírito, acorrendo àquele que lhe é igual, dá testemunho da sua divindade. Vem do céu uma voz, pois também vinha do céu aquele de quem se dava testemunho.'),
  (1, 'São Máximo de Turim', 'Sermão 100, *De sancta Epiphania*, 1 (CCL 23, 398-400); Liturgia das Horas, Ofício de Leituras da sexta-feira depois da Epifania (tradução brasileira; texto abreviado)', 'No dia do Natal, Cristo nasceu entre os homens; hoje renasce pelos sinais sagrados; naquele dia, nasceu da Virgem; hoje é gerado pelos sinais do céu. No Natal, ao nascer o Senhor segundo a natureza humana, Maria, sua mãe, o acaricia em seu colo; agora, ao ser gerado entre os sinais celestes, Deus, seu Pai, o envolve com sua voz, dizendo: «Este é o meu filho amado, no qual eu pus todo o meu agrado.» … Sua mãe o traz nos braços com ternura, seu Pai lhe presta o testemunho de amor. A Mãe apresenta-o aos magos para que o adorem, o Pai apresenta-o às nações para que o reverenciem.'),
  (2, 'Santo Hilário de Poitiers', '*In Evangelium Matthaei*, 2, 6 (PL 9, 927); tradução portuguesa citada no CIC 537 (grafia adaptada ao Brasil)', 'Tudo o que se passou com Cristo dá-nos a conhecer que, depois do banho de água, o Espírito Santo desce sobre nós do alto dos céus e, adotados pela voz do Pai, tornamo-nos filhos de Deus.'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 39, a. 5 (tradução a partir do latim; texto abreviado)', 'Cristo quis ser batizado para consagrar com o seu Batismo o batismo com que nós havíamos de ser batizados; por isso, no Batismo de Cristo deviam manifestar-se as coisas que pertencem à eficácia do nosso. … Pela fé contemplamos as coisas celestes, que excedem os sentidos e a razão humana; e, para o significar, abriram-se os céus quando Cristo foi batizado. … Pelo Batismo de Cristo abre-se-nos especialmente a entrada do reino celeste, que pelo pecado fora fechada ao primeiro homem. Por isso, batizado Cristo, abriram-se os céus, para mostrar que aos batizados está patente o caminho do céu.'),
  (4, 'São Tomás de Aquino', 'Suma Teológica, III, q. 39, a. 6, ad 4 (tradução a partir do latim; texto abreviado)', 'O Espírito Santo apareceu em forma de pomba sobre Cristo batizado por quatro razões. Primeiro, pela disposição que se requer no batizado, a saber, que não se aproxime com fingimento, pois, como diz a Escritura, «o santo Espírito da disciplina fugirá do fingido» (Sb 1, 5). A pomba, com efeito, é animal simples, sem astúcia nem dolo; por isso se diz: «Sede simples como as pombas» (Mt 10, 16). … Terceiro, por causa do efeito próprio do Batismo, que é a remissão dos pecados e a reconciliação com Deus: pois a pomba é animal manso. … Quarto, para designar o efeito comum do Batismo, que é a edificação da unidade da Igreja; … por isso se diz da Igreja: «Uma só é a minha pomba» (Ct 6, 8).'),
  (5, 'São Tomás de Aquino', 'Suma Teológica, III, q. 39, a. 8 (tradução portuguesa publicada; grafia adaptada ao Brasil)', 'Como dissemos, pelo seu batismo, que foi o exemplar do nosso, Cristo devia mostrar o que no nosso batismo se realiza. Ora, o batismo que os fiéis recebem é consagrado pela invocação e pela virtude da Trindade, segundo o Evangelho: «Ide e ensinai a todas as gentes, batizando-as em nome do Padre e do Filho e do Espírito Santo» (Mt 28, 19). E assim, no batismo de Cristo, como diz Jerônimo, manifesta-se o mistério da Trindade; pois é o próprio Senhor, revestido da natureza humana, o batizado; o Espírito Santo desceu sob a forma de pomba; foi ouvida a palavra do Pai dando testemunho do seu Filho.'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. II «Do Batismo», 2ª pergunta do capítulo. Tradução a partir do italiano.', '— Quais são os efeitos do sacramento do Batismo? — O sacramento do Batismo confere a primeira graça santificante, pela qual se apaga o pecado original, e também o atual, se o houver; perdoa toda a pena por eles devida; imprime o caráter de cristãos; faz-nos filhos de Deus, membros da Igreja e herdeiros do paraíso; e torna-nos capazes de receber os outros sacramentos.'),
  (7, 'São João Paulo II', '*Rosarium Virginis Mariae*, n. 21 (texto abreviado; o n. 21 continua com os outros mistérios luminosos; grafia adaptada ao Brasil)', 'Primeiramente é mistério de luz o Batismo no Jordão. Aqui, enquanto Cristo desce à água do rio, como inocente que Se faz pecado por nós (cf. 2 Cor 5, 21), o céu abre-se e a voz do Pai proclama-O Filho dileto (cf. Mt 3, 17 par), ao mesmo tempo que o Espírito vem sobre Ele para investi-Lo na missão que O espera. …')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 1;

-- luminous-1 · Jo 1, 29-34
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'No dia seguinte João viu Jesus, que vinha ter com ele, e disse: «Eis o Cordeiro de Deus, eis o que tira o pecado do mundo. Este é aquele, de quem eu disse: Depois de mim vem um homem que me foi preferido, porque era antes de mim, e eu não o conhecia (pessoalmente), mas vim batizar em água, para ele ser reconhecido em Israel.» E João deu testemunho, dizendo: «Vi o Espírito descer do céu em forma de pomba, e repousou sobre ele. E não o conhecia (pessoalmente), mas o que me mandou batizar em água, disse-me: Aquele, sobre quem vires descer e repousar o Espírito, esse é o que batiza no Espírito Santo. Eu o vi; e dei testemunho de que ele é o Filho de Deus.»', 'Jo 1, 29-34', 2
from public.mysteries m where m.type = 'luminous' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Pedro Crisólogo', 'Sermão 160 (PL 52, 620-622); Liturgia das Horas, Ofício de Leituras da segunda-feira depois da Epifania (tradução brasileira; texto abreviado)', 'Hoje Cristo entrou nas águas do Jordão para lavar o pecado do mundo. E João dá testemunho de que foi para isso que veio, ao dizer: «Eis o Cordeiro de Deus que tira o pecado do mundo» (Jo 1, 29). Hoje o servo recebe o Senhor, o homem recebe Deus, João recebe Cristo; recebe-o para obter o perdão, não para conceder. … Hoje o Espírito Santo, em forma de pomba, paira sobre as águas: assim como uma pomba anunciou a Noé o fim do dilúvio, por sua presença os homens saberiam que havia terminado o ininterrupto naufrágio do mundo.'),
  (1, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 1, lição 14 (tradução a partir do latim; texto abreviado)', 'Poderia alguém crer que Cristo, da primeira vez que veio ao batismo, veio a João como quem precisava de ser purificado dos pecados. Para o excluir, Cristo veio a ele também depois do batismo. Por isso diz João expressamente: «Eis o que tira». Nenhum pecado cometeu, mas veio tirar o pecado. Veio também para dar exemplo de humildade. … E note-se que, assim como, estando Cristo já concebido, quando a Virgem Mãe subiu apressadamente às montanhas para visitar Isabel, João, ainda no seio materno e sem poder falar, exultou no seio, prestando a Cristo reverência e júbilo, assim também agora, vindo Cristo a ele por humildade, presta-lhe testemunho e reverência e rompe em voz, dizendo: «Eis o Cordeiro de Deus».'),
  (2, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 1, lição 14 (tradução a partir do latim; texto abreviado)', 'Cristo é chamado Cordeiro, primeiro, pela pureza: «Não fostes resgatados por coisas corruptíveis, ouro ou prata» (1 Pd 1, 18). Segundo, pela mansidão: «Como cordeiro diante do tosquiador, emudeceu» (Is 53, 7). Terceiro, pelo fruto: tanto quanto ao vestido, segundo aquilo: «Revesti-vos do Senhor Jesus Cristo» (Rm 13, 14), como quanto ao alimento: «A minha carne é para a vida do mundo» (Jo 6, 52). … «Que tira o pecado do mundo»: o que na Lei nem pelo cordeiro nem pelos outros sacrifícios podia ser tirado, este Sangue o tira. Ou «tira», isto é, toma sobre si os pecados de todo o mundo, pois «levou os nossos pecados em seu corpo» (1 Pd 2, 24).'),
  (3, 'Catecismo da Igreja Católica', 'CIC 608 (grafia adaptada ao Brasil)', 'Depois de ter aceitado dar-Lhe o batismo como aos pecadores, João Batista viu e mostrou em Jesus o «Cordeiro de Deus que tira o pecado do mundo». Manifestou deste modo que Jesus é, ao mesmo tempo, o Servo sofredor, que Se deixa levar ao matadouro sem abrir a boca, carregando os pecados das multidões, e o cordeiro pascal, símbolo da redenção de Israel na primeira Páscoa. Toda a vida de Cristo manifesta a sua missão: «servir e dar a vida como resgate pela multidão».'),
  (4, 'São Cirilo de Alexandria', 'Comentário sobre o Evangelho de São João, livro 5, cap. 2 (PG 73, 751-754); Liturgia das Horas, Ofício de Leituras da quinta-feira depois da Epifania (tradução brasileira; texto abreviado)', 'Novamente Deus Pai nos concedeu o seu Espírito, sendo Cristo o primeiro a recebê-lo como primícias da natureza renovada. João Batista o testemunhou dizendo: «Eu vi o Espírito descer do céu, e permanecer sobre ele» (Jo 1, 32). … O Unigênito de Deus não recebeu o Espírito Santo para si mesmo; com efeito, esse Espírito que é seu, nos é dado nele e por ele … Cristo não recebeu o Espírito Santo para si mesmo, mas para que o recebêssemos nele; pois é também por ele que recebemos todos os bens.')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 1;

-- luminous-2 · Jo 2, 1-5
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Três dias depois, celebraram-se umas bodas em Caná da Galileia, e encontrava-se lá a Mãe de Jesus. Foi também convidado Jesus com seus discípulos para as bodas. E faltando o vinho, a Mãe de Jesus disse-lhe: «Não têm vinho.» E Jesus disse-lhe: «Mulher, que nos importa a mim e a ti isso? Ainda não chegou a minha hora.» Disse sua Mãe aos que serviam: «Fazei tudo o que ele vos disser.»', 'Jo 2, 1-5', 0
from public.mysteries m where m.type = 'luminous' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 2, lect. 1 (tradução a partir do latim; texto abreviado)', 'Na Mãe que intercede, nota primeiro a piedade e a misericórdia. Pois é próprio da misericórdia considerar como sua a falta alheia … Como a Virgem bem-aventurada estava cheia de misericórdia, queria remediar a falta dos outros. Em segundo lugar, a sua reverência para com Cristo: pela reverência que temos a Deus, basta-nos expor-lhe as nossas necessidades, segundo aquilo do Salmo: «Senhor, diante de ti está todo o meu desejo». Como Deus nos há de socorrer, não nos compete inquirir … Por isso sua Mãe expôs simplesmente a falta dos outros, dizendo: «Não têm vinho».'),
  (1, 'São Bernardo de Claraval', 'Sermão para o 1.º domingo após a oitava da Epifania (sobre Jo 2,3-5) (texto abreviado)', '«Faltando o vinho, a mãe de Jesus disse-lhe: Não têm vinho.» Ela teve piedade deles em sua bondade e tomou parte em seu constrangimento. O que pode resultar da fonte da Bondade, senão a bondade? … Talvez a resposta do Senhor pareça um pouco dura e severa; mas Ele sabia bem com quem estava falando, assim como ela não ignorava quem lhe falava. … Ouvi o que ela disse aos que serviam: «Fazei o que Ele vos disser.»'),
  (2, 'São João Paulo II', 'Encíclica *Redemptoris Mater*, § 21 (texto abreviado)', 'Em Caná da Galileia torna-se patente só um aspecto concreto da indigência humana, pequeno aparentemente e de pouca importância («Não têm mais vinho»). Mas é algo que tem um valor simbólico: aquele ir ao encontro das necessidades do homem significa, ao mesmo tempo, introduzi-las no âmbito da missão messiânica e do poder salvífico de Cristo. Dá-se, portanto, uma mediação: Maria põe-se de permeio entre o seu Filho e os homens na realidade das suas privações, das suas indigências e dos seus sofrimentos. … Faz de mediadora, não como uma estranha, mas na sua posição de mãe, consciente de que como tal pode — ou antes, «tem o direito de» — fazer presente ao Filho as necessidades dos homens.'),
  (3, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 2, lect. 1 (tradução a partir do latim; texto abreviado)', 'Embora a Mãe tenha sido repelida, não desconfia da misericórdia do Filho; por isso adverte os serventes, dizendo: «Fazei tudo o que ele vos disser», no que consiste a perfeição de toda a justiça. Pois a justiça perfeita é obedecer a Cristo em todas as coisas … Esta palavra, «fazei tudo o que ele vos disser», não convém dizê-la senão de Deus somente, porque o homem às vezes pode errar … Mas a Deus, que não erra nem pode enganar-se, devemos obedecer em tudo.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. III «Da Ave-Maria», 12ª e 13ª perguntas do capítulo. Tradução a partir do italiano.', '«— Por que, depois do Pai-Nosso, dizemos de preferência a Ave-Maria a qualquer outra oração? — Porque a Santíssima Virgem é a Advogada mais poderosa junto de Jesus Cristo; e por isso, depois de termos dito a oração que Jesus Cristo nos ensinou, rogamos à Santíssima Virgem que nos alcance as graças que pedimos. — Por que motivo é a Virgem Santíssima tão poderosa? — A Virgem Santíssima é tão poderosa porque é Mãe de Deus, e é impossível que não seja por Ele atendida.»'),
  (5, 'São João Paulo II', 'Carta apostólica *Rosarium Virginis Mariae*, § 21 (texto abreviado)', 'Mistério de luz é o início dos sinais em Caná (cf. Jo 2, 1-12), quando Cristo, transformando a água em vinho, abre à fé o coração dos discípulos graças à intervenção de Maria, a primeira entre os crentes. … A função que desempenha em Caná acompanha, de algum modo, todo o caminho de Cristo. … Torna-se a grande advertência materna que Ela dirige à Igreja de todos os tempos: «Fazei o que Ele vos disser» (Jo 2, 5). Advertência esta que … constitui o fundo mariano de todos os «mistérios da luz».'),
  (6, 'Catecismo da Igreja Católica', 'CIC 2618', '«O Evangelho revela-nos como é que Maria ora e intercede na fé: em Caná, a Mãe de Jesus roga a seu Filho pelas necessidades dum banquete de bodas, sinal dum outro banquete, o das bodas do Cordeiro que dá o seu corpo e o seu sangue a pedido da Igreja, sua esposa. E é na hora da Nova Aliança, ao pé da cruz, que Maria é atendida como a Mulher, a nova Eva, a verdadeira «mãe dos vivos».»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 2;

-- luminous-2 · Jo 2, 6-10
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Ora estavam ali seis talhas de pedra, preparadas para a purificação judaica, que levavam cada uma duas ou três metretas. Disse-lhes Jesus: «Enchei as talhas de água.» E encheram-nas até cima. Então disse-lhes Jesus: «Tirai agora, e levai ao arquitriclino.» E eles levaram. E o arquitriclino, logo que provou a água convertida em vinho, como não sabia donde lhe viera (este vinho), ainda que o sabiam os serventes, porque tinham tirado a água, o arquitriclino chamou o esposo, e disse-lhe: «Todo o homem põe primeiro o bom vinho, e, quando já (os convidados) têm bebido bem, então lhes apresenta o inferior; tu, ao contrário, tiveste o bom vinho guardado até agora.»', 'Jo 2, 6-10', 1
from public.mysteries m where m.type = 'luminous' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Santo Agostinho', '*Tractatus in Ioannem*, 8 (texto abreviado)', 'O milagre de nosso Senhor Jesus Cristo, pelo qual fez vinho da água, não é admirável para os que sabem que Deus o fez. Pois ele mesmo fez o vinho naquele dia, nas núpcias, naquelas seis talhas … ele que todos os anos faz isto nas videiras. … Também nós éramos água, e ele nos fez vinho, fez-nos sábios; pois temos gosto pela fé nele, nós que antes éramos insensatos.'),
  (1, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 2, lect. 1 (tradução a partir do latim; texto abreviado)', 'Cristo converteu a água do temor no vinho da caridade, quando deu o espírito de adoção de filhos, no qual clamamos: «Abba, Pai» … Não quis fazer o vinho do nada, mas da água, para mostrar que não fundava uma doutrina inteiramente nova, reprovando a antiga, mas que a vinha cumprir … pois o que a antiga lei figurava e prometia, Cristo o mostrou e o descobriu.'),
  (2, 'São João Crisóstomo', '*Homiliae in Ioannem*, hom. 22 (Jo 2,4-10) (texto abreviado)', 'Não é sem razão que o Evangelista diz: «Segundo o rito da purificação dos judeus», … para mostrar que aqueles vasos nunca foram receptáculos de vinho. … Mas agora, para mostrar que é Ele quem transforma a água nas videiras, e converte a chuva em vinho … Ele efetuou naquele momento, nas bodas, o que na planta leva muito tempo. … Que era vinho então, e o melhor dos vinhos, … tinha os servos por testemunhas; … o mestre-sala e o noivo.'),
  (3, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 2, lect. 1 (tradução a partir do latim; texto abreviado)', 'Cristo, porém, não põe primeiro o bom vinho, porque a princípio propõe coisas amargas e duras: «Estreito é o caminho que conduz à vida». Mas quanto mais o homem progride na sua fé e doutrina, tanto mais se adoça e maior suavidade sente … Do mesmo modo, neste mundo padecem amarguras e tribulações todos os que querem viver piamente em Cristo … mas no futuro receberão delícias e alegrias.')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 2;

-- luminous-2 · Jo 2, 11
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Por este modo deu Jesus princípio aos (seus) milagres em Caná da Galileia, e manifestou a sua glória, e os seus discípulos creram nele.', 'Jo 2, 11', 2
from public.mysteries m where m.type = 'luminous' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Tomás de Aquino', '*Super Evangelium S. Ioannis lectura*, cap. 2, lect. 1 (tradução a partir do latim; texto abreviado)', '«E manifestou a sua glória», isto é, o poder pelo qual é glorioso … «E os seus discípulos creram nele.» Mas como creram, se já eram discípulos e antes já tinham crido? … Antes creram nele como num homem bom, que pregava coisas justas e retas; agora, porém, creram nele como em Deus.'),
  (1, 'São João Paulo II', 'Encíclica *Redemptoris Mater*, § 21', 'Em Caná, graças à intercessão de Maria e à obediência dos servos, Jesus dá início à «sua hora». Em Caná, Maria aparece como quem acredita em Jesus: a sua fé provoca da parte dele o primeiro «milagre» e contribui para suscitar a fé dos discípulos.'),
  (2, 'Catecismo da Igreja Católica', 'CIC 1613 (grafia adaptada ao Brasil)', '«No umbral da sua vida pública, Jesus realiza o seu primeiro sinal –a pedido da sua Mãe – por ocasião duma festa de casamento (118). A Igreja atribui uma grande importância à presença de Jesus nas bodas de Caná. Ela vê nesse fato a confirmação da bondade do matrimônio e o anúncio de que, doravante, o matrimônio seria um sinal eficaz da presença de Cristo.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 2;

-- luminous-3 · Mc 1, 14-15
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Depois que João foi preso, foi Jesus para a Galileia, pregando o Evangelho do reino de Deus, e dizendo: «Está completo o tempo, e aproxima-se o reino de Deus; fazei penitência, e crede no Evangelho.»', 'Mc 1, 14-15', 0
from public.mysteries m where m.type = 'luminous' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São João Paulo II', '*Rosarium Virginis Mariae*, 21 (texto abreviado)', 'Mistério de luz é a pregação com a qual Jesus anuncia o advento do Reino de Deus e convida à conversão (cf. Mc 1, 15), perdoando os pecados de quem a Ele se dirige com humilde confiança … início do ministério de misericórdia que Ele prosseguirá exercendo até ao fim do mundo, especialmente através do sacramento da Reconciliação confiado à sua Igreja (cf. Jo 20, 22-23).'),
  (1, 'São Jerônimo (atribuído)', 'Comentário a Marcos atribuído a S. Jerônimo, segundo a Catena Aurea de S. Tomás de Aquino sobre Mc 1, lição 6 (texto abreviado). Tradução a partir do latim do Corpus Thomisticum; não é edição portuguesa publicada. A obra é hoje tida por pseudo-jeronimiana.', 'Faz penitência quem quer aderir ao bem eterno, isto é, ao reino de Deus. Quem deseja o miolo, quebra a noz. A doçura do fruto compensa o amargor da raiz; a esperança do lucro torna agradável o perigo do mar; a esperança da saúde suaviza a dor do remédio. … Fazei, pois, penitência e crede, isto é, renunciai às obras mortas … Não é, contudo, o mérito das boas obras que conduz à fé, mas a fé começa para que as boas obras se sigam.'),
  (2, 'Catecismo da Igreja Católica', 'CIC 545 (grafia adaptada ao Brasil)', 'Jesus convida os pecadores para a mesa do Reino: «Eu não vim chamar os justos, mas os pecadores» (Mc 2, 17). Convida-os à conversão sem a qual não se pode entrar no Reino, mas por palavras e atos, mostra-lhes a misericórdia sem limites do Seu Pai para com eles e a imensa «alegria que haverá no céu, por um só pecador que se arrependa» (Lc 15, 7). A prova suprema deste amor será o sacrifício da sua própria vida, «pela remissão dos pecados» (Mt 26, 28).'),
  (3, 'Catecismo da Igreja Católica', 'CIC 1431 (grafia adaptada ao Brasil)', 'A penitência interior é uma reorientação radical de toda a vida, um regresso, uma conversão a Deus de todo o nosso coração, uma rotura com o pecado, uma aversão ao mal, com repugnância pelas más ações que cometemos. Ao mesmo tempo, implica o desejo e o propósito de mudar de vida, com a esperança da misericórdia divina e a confiança na ajuda da sua graça. Esta conversão do coração é acompanhada por uma dor e uma tristeza salutares, a que os Santos Padres chamaram animi cruciatus (aflição do espírito), compunctio cordis (compunção do coração).'),
  (4, 'Catecismo da Igreja Católica', 'CIC 1432', 'O coração do homem é pesado e endurecido. É necessário que Deus dê ao homem um coração novo. A conversão é, antes de mais, obra da graça de Deus, a qual faz com que os nossos corações se voltem para Ele: «Convertei-nos, Senhor, e seremos convertidos» (Lm 5, 21). Deus é quem nos dá a coragem de começar de novo. É ao descobrir a grandeza do amor de Deus que o nosso coração é abalado pelo horror e pelo peso do pecado, e começa a ter receio de ofender a Deus pelo pecado e de estar separado d''Ele. O coração humano converte-se, ao olhar para Aquele a quem os nossos pecados trespassaram.'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV (Dos Sacramentos), cap. VI «Da Penitência», 12ª e 13ª perguntas do capítulo. Tradução a partir do italiano.', '«— Que quer dizer esta palavra contrição? — A palavra contrição quer dizer rompimento ou despedaçamento, como quando uma pedra é pisada e reduzida a pó. — Por que se dá o nome de contrição à dor dos pecados? — Dá-se o nome de contrição à dor dos pecados para significar que o coração duro do pecador de certo modo se despedaça pela dor de ter ofendido a Deus.»'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV (Dos Sacramentos), cap. VI «Da Penitência», 45ª pergunta do capítulo. Tradução a partir do italiano.', '«— Por que deve a dor ser interna? — A dor deve ser interna, porque a vontade, que se afastou de Deus pelo pecado, deve voltar a Deus detestando o pecado cometido.»'),
  (7, 'Pio XI', 'Encíclica *Quas Primas*, 15 (1925); tradução a partir do latim (vatican.va), não é tradução portuguesa publicada', 'Este reino é apresentado nos Evangelhos de tal modo que os homens se preparam para nele entrar fazendo penitência, e não podem entrar nele senão pela fé e pelo batismo, o qual, embora seja um rito externo, significa e opera a regeneração interior; opõe-se unicamente ao reino de Satanás e ao poder das trevas, e exige dos seus seguidores não só que, com o ânimo desprendido das riquezas e das coisas terrenas, mostrem mansidão de costumes e tenham fome e sede de justiça, mas também que se neguem a si mesmos e tomem a sua cruz.')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 3;

-- luminous-3 · Mc 4, 26-29
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Dizia também: «O reino de Deus é como um homem que lança a semente à terra, e que dorme e se levanta noite e dia, e a semente brota e cresce sem ele saber como. Porque a terra por si mesma produz, primeiramente, a erva, depois a espiga, e por último o trigo grado na espiga. E, quando o fruto está maduro, mete logo a foice, porque está chegado o tempo da ceifa.»', 'Mc 4, 26-29', 1
from public.mysteries m where m.type = 'luminous' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 543', 'Todos os homens são chamados a entrar no Reino. Anunciado primeiro aos filhos de Israel, este Reino messiânico é destinado a acolher os homens de todas as nações. Para ter acesso a ele, é preciso acolher a Palavra de Jesus: «A Palavra do Senhor compara-se à semente lançada ao campo: aqueles que a ouvem com fé e entram a fazer parte do pequeno rebanho de Cristo, já receberam o Reino; depois, por força própria, a semente germina e cresce até ao tempo da messe».'),
  (1, 'São Gregório Magno', 'Catena Aurea de S. Tomás de Aquino sobre Mc 4, lição 3 (trecho atribuído a S. Gregório, «Moralium»). Tradução a partir do latim do Corpus Thomisticum; não é edição portuguesa publicada. Não se conferiu na obra original de S. Gregório.', 'O homem lança a semente à terra quando insere no seu coração uma boa intenção; dorme aquele que já repousa na esperança da boa obra; levanta-se de noite e de dia, porque progride entre as adversidades e as prosperidades, sem que ele saiba, pois ainda não é capaz de medir os seus progressos, e contudo a virtude concebida é levada à perfeição. Quando, pois, concebemos bons desejos, lançamos a semente à terra; quando começamos a obrar retamente, somos erva; quando crescemos no progresso da boa obra, chegamos à espiga; quando nos firmamos na perfeição dessa mesma obra, produzimos já o trigo cheio na espiga.'),
  (2, 'São Jerônimo (atribuído)', 'Comentário a Marcos atribuído a S. Jerônimo, segundo a Catena Aurea de S. Tomás de Aquino sobre Mc 4, lição 3 (texto abreviado). Tradução a partir do latim do Corpus Thomisticum; não é edição portuguesa publicada. A obra é hoje tida por pseudo-jeronimiana.', 'A semente é a palavra da vida; a terra, os corações humanos … Primeiro a erva, isto é, o temor: pois o princípio da sabedoria é o temor do Senhor. Depois a espiga, isto é, a penitência banhada em lágrimas; depois o fruto pleno na espiga, isto é, a caridade: pois a plenitude da lei é a caridade.'),
  (3, 'Bento XVI', 'Angelus, 17 de junho de 2012 (texto abreviado)', 'Ele é o Senhor do Reino, o homem é o seu colaborador humilde, que contempla e rejubila com a obra criadora divina e dela espera pacientemente os frutos. … O tempo presente é época de sementeira, e o crescimento da semente é garantida pelo Senhor. … não obstante exija a nossa colaboração, o Reino de Deus é antes de tudo dom do Senhor, graça que precede o homem e as suas obras.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II (Da Oração), cap. II «Da Oração Dominical», 15ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que entendemos nós por reino de Deus? — Por reino de Deus entendemos um tríplice reino espiritual, a saber: o reino de Deus em nós, ou seja, o reino da graça; o reino de Deus na terra, isto é, a santa Igreja Católica; e o reino de Deus nos céus, ou seja, o paraíso.»'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II (Da Oração), cap. II «Da Oração Dominical», 16ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que pedimos com as palavras "venha a nós o vosso reino", com relação à graça? — Com relação à graça, pedimos que Deus reine em nós com a sua graça santificante, pela qual se compraz em residir em nós como um rei no seu palácio, e que nos conserve unidos a Si com as virtudes da fé, da esperança e da caridade, pelas quais reina sobre o nosso entendimento, sobre o nosso coração e sobre a nossa vontade.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 3;

-- luminous-3 · Lc 15, 11-24
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Um homem tinha dois filhos, e o mais novo deles disse a seu pai: «Pai, dá-me a parte dos bens que me toca.» E ele repartiu entre eles os bens. E, passados poucos dias, juntando tudo (o que era seu), o filho mais novo partiu para uma terra distante, e lá dissipou os seus bens, vivendo dissolutamente. … Mas, tendo entrado em si, disse: «Quantos jornaleiros há em casa de meu pai, que têm pão em abundância, e eu aqui morro de fome! Levantar-me-ei, e irei ter com meu pai, e lhe direi: Pai, pequei contra o céu e contra ti; já não sou digno de ser chamado teu filho; trata-me como um dos teus jornaleiros.» E, levantando-se, foi para seu pai. E, quando ele estava ainda longe, seu pai viu-o, e ficou movido de compaixão, e, correndo, lançou-lhe os braços ao pescoço, e beijou-o. O filho disse-lhe: «Pai, pequei contra o céu e contra ti; já não sou digno de ser chamado teu filho.» Porém o pai disse aos seus servos: «Tirai depressa o vestido mais precioso, e vesti-lho, e metei-lhe um anel no dedo e os sapatos nos pés; trazei também um vitelo gordo, e matai-o, e comamos e banqueteemo-nos, porque este meu filho estava morto, e reviveu; tinha-se perdido, e foi encontrado.»', 'Lc 15, 11-24', 2
from public.mysteries m where m.type = 'luminous' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 1439', 'O dinamismo da conversão e da penitência foi maravilhosamente descrito por Jesus na parábola do «filho pródigo», cujo centro é «o pai misericordioso»: o deslumbramento duma liberdade ilusória e o abandono da casa paterna: a miséria extrema em que o filho se encontra depois de delapidada a fortuna: a humilhação profunda de se ver obrigado a guardar porcos e, pior ainda, de desejar alimentar-se das bolotas que os porcos comiam: a reflexão sobre os bens perdidos: o arrependimento e a decisão de se declarar culpado diante do pai: o caminho do regresso: o acolhimento generoso por parte do pai: a alegria do pai: eis alguns dos aspectos próprios do processo de conversão. O fato novo, o anel e o banquete festivo são símbolos desta vida nova, pura, digna, cheia de alegria, que é a vida do homem que volta para Deus e para o seio da família que é a Igreja. Só o coração de Cristo, que conhece a profundidade do amor do seu Pai, pôde revelar-nos o abismo da sua misericórdia, de um modo tão cheio de simplicidade e beleza.'),
  (1, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro VII, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 15, lição 3 e 4 (dois trechos unidos; texto abreviado). Tradução a partir do latim do Corpus Thomisticum (corpusthomisticum.org); não é edição portuguesa publicada.', 'Que há de mais longínquo do que afastar-se de si mesmo, e separar-se não pelas regiões, mas pelos costumes? … Bem volta a si, porque de si se afastara: pois quem regressa a Deus é restituído a si mesmo, e quem se afasta de Cristo renega-se a si mesmo.'),
  (2, 'Santo Agostinho', 'Quaestiones Evangeliorum, livro II, q. 33, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 15, lição 4. Tradução a partir do latim do Corpus Thomisticum (corpusthomisticum.org); não é edição portuguesa publicada.', '«Levantar-me-ei», porque jazia; «e irei», porque estava longe; «ter com meu pai», porque estava sob o príncipe dos porcos.'),
  (3, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro VII, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 15, lição 4 (texto abreviado). Tradução a partir do latim do Corpus Thomisticum (corpusthomisticum.org); não é edição portuguesa publicada.', 'Quão misericordioso é aquele que foi ofendido! Não desdenha ouvir o nome de pai. «Pequei»: esta é a primeira confissão diante do autor da natureza, do senhor da misericórdia, do juiz da culpa. Mas, ainda que Deus saiba tudo, espera a voz da tua confissão … Confessa antes, para que interceda por ti Cristo, rogue por ti a Igreja, chore por ti o povo; e não temas não alcançar o perdão.'),
  (4, 'Santo Ambrósio', 'Expositio Evangelii secundum Lucam, livro VII, segundo a Catena Aurea de S. Tomás de Aquino sobre Lc 15, lição 4. Tradução a partir do latim do Corpus Thomisticum (corpusthomisticum.org); não é edição portuguesa publicada.', 'Corre, pois, ao teu encontro, porque te ouve a deliberar no segredo da mente; e, estando tu ainda longe, corre ao teu encontro, para que ninguém te impeça; e também te abraça: no encontro está a presciência, no abraço a clemência; e, como num afeto de amor paterno, lança-se-te ao pescoço, para levantar o que jazia e voltar para o céu aquele que, carregado de pecados, se inclinava para a terra. Prefiro, pois, ser filho a ser ovelha: a ovelha é achada pelo pastor, o filho é honrado pelo pai.'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV (Dos Sacramentos), cap. VI «Da Penitência», 22ª pergunta do capítulo. Tradução a partir do italiano.', '«— O sacramento da Penitência tem a virtude de perdoar todos os pecados, por muitos e grandes que sejam? — O sacramento da Penitência tem a virtude de perdoar todos os pecados, por muitos e grandes que sejam, contanto que seja recebido com as devidas disposições.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 3;

-- luminous-4 · Mt 17, 1-8
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Seis dias depois, tomou Jesus consigo Pedro e Tiago e João, seu irmão, e levou-os à parte a um alto monte, e transfigurou-se diante deles. E o seu rosto ficou refulgente como o Sol, e as suas vestiduras tornaram-se brancas como a neve. E eis que lhes apareceram Moisés e Elias falando com ele. … Estando ele ainda a falar, eis que uma nuvem resplandecente os envolveu; e eis que (saiu) da nuvem uma voz que dizia: «Este é o meu Filho dileto em quem pus toda a minha complacência; ouvi-o.» … Eles então, levantando os olhos, não viram ninguém exceto só Jesus.', 'Mt 17, 1-8', 0
from public.mysteries m where m.type = 'luminous' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São João Paulo II', 'Rosarium Virginis Mariae, n. 9 (16 de outubro de 2002)', '«Transfigurou-Se diante deles: o seu rosto resplandeceu como o sol» (Mt 17, 2). A cena evangélica da transfiguração de Cristo… pode ser tomada como ícone da contemplação cristã. Fixar os olhos no rosto de Cristo… até perceber o brilho divino definitivamente manifestado no Ressuscitado glorificado à direita do Pai, é a tarefa de cada discípulo de Cristo…'),
  (1, 'São Leão Magno', 'Sermão 51 (Tractatus 51), sobre a Transfiguração, n. 3 (tradução a partir do latim; texto abreviado)', '«Nesta transfiguração tratava-se principalmente de tirar do coração dos discípulos o escândalo da cruz, para que a humildade da paixão voluntária não perturbasse a fé daqueles a quem fora revelada a excelência da dignidade escondida. Mas com não menor providência se fundava a esperança da santa Igreja, para que todo o corpo de Cristo conhecesse com que transformação havia de ser enriquecido, e os membros se prometessem a participação daquela honra que já resplandecera na Cabeça. Disto mesmo falara o Senhor: «Então os justos resplandecerão como o sol no reino de seu Pai» (Mt 13, 43).»'),
  (2, 'Santo Agostinho', 'Sermão 78, 2 (PL 38, 490; tradução a partir do latim)', '«O próprio Jesus resplandeceu como o sol, significando que Ele é a luz que ilumina todo o homem que vem a este mundo. O que este sol é para os olhos da carne, isso é Ele para os olhos do coração; e o que este sol é para a carne, isso é Ele para os corações.»'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 45, a. 1, c. (tradução a partir do latim; texto abreviado)', '«O Senhor, depois de anunciar a sua paixão, tinha convidado os discípulos a segui-lo nela. Ora, para que alguém caminhe direito pela estrada, é preciso que conheça de algum modo o fim, assim como o arqueiro não lança bem a seta se primeiro não avistar o alvo. … E isto é sobretudo necessário quando o caminho é difícil e áspero e a jornada trabalhosa, mas o fim jucundo. … Por isso foi conveniente que mostrasse aos seus discípulos a glória da sua claridade (que é propriamente transfigurar-se), à qual há de configurar os seus. Donde diz Beda: «Por piedosa providência sucedeu que, saboreando por breve tempo a contemplação do gozo que permanece para sempre, suportassem com mais fortaleza as adversidades.»»'),
  (4, 'São Leão Magno', 'Sermão 51 (Tractatus 51), sobre a Transfiguração, n. 7-8 (tradução a partir do latim; texto abreviado)', '«Ouvi-O, pois, sem hesitar, a Ele em quem em tudo me comprazo, por cuja pregação sou manifestado, por cuja humildade sou glorificado; porque Ele é a verdade e a vida, Ele é o meu poder e a minha sabedoria. … Ouvi-O, a Ele que abre o caminho do céu e, pelo suplício da cruz, vos prepara os degraus da subida ao reino. … Quer para cumprir os mandamentos, quer para suportar as adversidades, deve ressoar sempre aos nossos ouvidos a voz do Pai, que diz: «Este é o meu Filho dileto, em quem pus toda a minha complacência; ouvi-O».»'),
  (5, 'Santo Agostinho', 'Sermão 78, 5 (tradução a partir do latim; texto abreviado)', '«Não viram ninguém, senão só Jesus. Que significa isto? … Quando o Senhor os levantou, significou a ressurreição. Depois da ressurreição, para que te serve a Lei? para que a Profecia? Por isso não aparece Elias, não aparece Moisés. Resta-te Aquele que «no princípio era o Verbo, e o Verbo estava em Deus, e o Verbo era Deus». Resta-te Ele, para que Deus seja tudo em todos. … Grande dom, grande promessa! Deus não te reserva como prêmio alguma coisa sua, mas a Si mesmo. … Pareces a ti mesmo rico: se não tens a Deus, que tens? Outro é pobre: se tem a Deus, que não tem?»'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. III «Do segundo artigo», 13ª pergunta do capítulo. Tradução a partir do italiano.', '«— Donde sabemos nós que Jesus Cristo é verdadeiro Deus? — Sabemos que Jesus Cristo é verdadeiro Deus: 1.º pelo testemunho do Pai, quando disse: Este é o meu Filho dileto, no qual me comprazi; ouvi-o; 2.º pela afirmação do próprio Jesus Cristo, confirmada com os mais estupendos milagres; 3.º pela doutrina dos Apóstolos; 4.º pela tradição constante da Igreja católica.»'),
  (7, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. XII «Do undécimo artigo», 6ª pergunta do capítulo. Tradução a partir do italiano. Texto abreviado.', '«— Quais são esses dotes que adornarão os corpos dos eleitos? — Os dotes que adornarão os corpos gloriosos dos eleitos são: 1.º a impassibilidade, pela qual não poderão mais estar sujeitos a males nem a dores de espécie alguma …; 2.º a claridade, pela qual resplandecerão à maneira do sol e de outras tantas estrelas; 3.º a agilidade, pela qual poderão passar num momento e sem fadiga de um lugar a outro e da terra ao céu; 4.º a sutileza, pela qual poderão penetrar sem obstáculo qualquer corpo, como fez Jesus Cristo ressuscitado.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 4;

-- luminous-4 · Lc 9, 28-31
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E aconteceu que, cerca de oito dias depois destas palavras, tomou consigo Pedro, Tiago e João, e subiu a um monte para orar. E, enquanto orava, tornou-se todo outro o seu rosto; e o seu vestido tornou-se branco e resplandecente. E eis que dois homens falavam com ele. E estes eram Moisés e Elias, os quais apareceram cheios de majestade, e falavam da sua saída (deste mundo), que ele estava para cumprir em Jerusalém.', 'Lc 9, 28-31', 1
from public.mysteries m where m.type = 'luminous' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Bento XVI', 'Angelus, 4 de março de 2007 (texto abreviado) (grafia adaptada ao Brasil)', 'Para os três Apóstolos subir ao monte significou ser incluídos na oração de Jesus, que se retirava com frequência em oração, especialmente ao alvorecer e depois do pôr do sol, e por vezes durante toda a noite. Mas só daquela vez, no monte, Ele quis manifestar aos seus amigos a luz interior com que era cumulado quando rezava… Cristo entra mais profundamente nesta missão, aderindo completamente à vontade do Pai, e mostra-nos que a verdadeira oração consiste precisamente em unir a nossa vontade à de Deus.'),
  (1, 'São Tomás de Aquino', 'Suma Teológica, III, q. 45, a. 3, c. (tradução a partir do latim; texto abreviado)', '«Cristo quis transfigurar-se para mostrar aos homens a sua glória e para os provocar a desejá-la. Ora, à glória da eterna bem-aventurança são conduzidos por Cristo não só os que vieram depois d’Ele, mas também os que O precederam. … Por isso foi conveniente que estivessem presentes como testemunhas, dentre os que O precederam, Moisés e Elias; e, dentre os que O seguiram, Pedro, Tiago e João; para que pela boca de duas ou três testemunhas se firmasse esta palavra.»'),
  (2, 'São João Paulo II', 'Rosarium Virginis Mariae, n. 21 (16 de outubro de 2002)', 'Mistério de luz por excelência é a Transfiguração que, segundo a tradição, se deu no Monte Tabor. A glória da Divindade reluz no rosto de Cristo, enquanto o Pai O acredita aos Apóstolos extasiados para que O «escutem» (cf. Lc 9, 35 par) e se disponham a viver com Ele o momento doloroso da Paixão, a fim de chegarem com Ele à glória da Ressurreição e a uma vida transfigurada pelo Espírito Santo.'),
  (3, 'Catecismo da Igreja Católica', 'CIC 555', 'Por um momento, Jesus mostra a sua glória divina, confirmando assim a confissão de Pedro. Mostra também que, para «entrar na sua glória» (Lc 24, 26), tem de passar pela cruz em Jerusalém. Moisés e Elias tinham visto a glória de Deus sobre a montanha; a Lei e os Profetas tinham anunciado os sofrimentos do Messias (314). A paixão de Jesus é da vontade do Pai: o Filho age como Servo de Deus (315). A nuvem indica a presença do Espírito Santo: «Tota Trinitas apparuit: Pater in voce; Filius in homine; Spiritus in nube clara – Apareceu toda a Trindade: o Pai na voz; o Filho na humanidade; o Espírito Santo na nuvem luminosa» (316).'),
  (4, 'Liturgia bizantina', 'Kontakion na Festa da Transfiguração (Menaion; cf. CIC 555, nota 317)', '«Transfiguraste-Te sobre a montanha e, na medida em que disso eram capazes, os teus discípulos contemplaram a tua glória, ó Cristo Deus; para que, quando Te vissem crucificado, compreendessem que a tua paixão era voluntária, e anunciassem ao mundo que Tu és verdadeiramente a irradiação do Pai»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 4;

-- luminous-4 · Lc 9, 32-33
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Entretanto Pedro e os que estavam com ele tinham-se deixado oprimir de sono. E, despertando, viram a majestade de Jesus, e os dois varões que estavam com ele. E aconteceu que, enquanto estes se separavam dele, Pedro disse a Jesus: «Mestre, é bom para nós estar aqui; façamos três tendas, uma para ti, uma para Moisés, e uma para Elias», não sabendo o que dizia.', 'Lc 9, 32-33', 2
from public.mysteries m where m.type = 'luminous' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Leão Magno', 'Sermão 51 (Tractatus 51), sobre a Transfiguração, n. 5 (tradução a partir do latim; texto abreviado)', '«Excitado por estas revelações dos mistérios, o apóstolo Pedro, desprezando as coisas do mundo e enfastiado das terrenas, era arrebatado como num êxtase da mente ao desejo das eternas; e, cheio de gozo por toda a visão, desejava habitar com Jesus ali onde se alegrava com a manifestação da sua glória. … Mas a esta sugestão o Senhor não respondeu, significando que o que ele desejava não era mau, mas fora de ordem; pois o mundo não podia ser salvo senão pela morte de Cristo … para entendermos que, entre as tentações desta vida, devemos pedir primeiro a paciência que a glória, porque a felicidade de reinar não pode preceder o tempo de padecer.»'),
  (1, 'Santo Agostinho', 'Sermão 78, 6 (tradução a partir do latim; texto abreviado)', '«Desce, Pedro: desejavas repousar no monte; desce, prega a palavra, insiste oportuna e importunamente, repreende, exorta, admoesta com toda a paciência e doutrina. Trabalha, sua, padece alguns tormentos, para que possuas, pela candura e beleza da reta ação na caridade, o que se entende nas vestes brancas do Senhor. … Desceu a Vida, para ser morta; desceu o Pão, para ter fome; desceu o Caminho, para se cansar no caminho; desceu a Fonte, para ter sede: e tu recusas trabalhar? Não busques o que é teu. Tem caridade, prega a verdade: então chegarás à eternidade, onde encontrarás a segurança.»'),
  (2, 'Bento XVI', 'Angelus, 12 de março de 2006 (texto abreviado)', 'Quando se tem a graça de fazer uma forte experiência de Deus, é como se se vivesse algo de análogo àquilo que aconteceu com os discípulos, durante a Transfiguração: por um momento, saboreia-se algo daquilo que constituirá a bem-aventurança do Paraíso. Em geral, trata-se de experiências breves, que por vezes Deus concede, de maneira especial em vista de árduas provações. Porém, a ninguém é dado viver «no Tabor» enquanto estiver nesta terra. Com efeito, a existência humana é um caminho de fé…'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. XIII «Do duodécimo artigo», 2ª e 3ª perguntas do capítulo. Tradução a partir do italiano.', '«— Podemos nós compreender a felicidade do paraíso? — Não, nós não podemos compreender a felicidade do paraíso, porque ela supera os conhecimentos da nossa mente limitada, e porque os bens do céu não podem comparar-se com os bens deste mundo. — Em que consiste a felicidade dos eleitos? — A felicidade dos eleitos consiste em ver, amar e possuir para sempre a Deus, fonte de todo o bem.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 4;

-- luminous-5 · Mt 26, 26-29
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, enquanto ceavam, Jesus tomou o pão, e o benzeu, e o partiu, e deu-o a seus discípulos, e disse: Tomai e comei; isto é o meu corpo. E, tomando o cálice, deu graças, e deu-lho, dizendo: Bebei dele todos, Porque isto é o meu sangue (que será o selo) do novo testamento, o qual será derramado por muitos para remissão dos pecados. E digo-vos: desta hora em diante não beberei mais deste fruto da videira até àquele dia, em que o beberei novo convosco no reino de meu Pai.', 'Mt 26, 26-29', 0
from public.mysteries m where m.type = 'luminous' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São João Paulo II', 'Rosarium Virginis Mariae, § 21 (texto abreviado)', '«Mistério de luz é, enfim, a instituição da Eucaristia, na qual Cristo Se faz alimento com o seu Corpo e o seu Sangue sob os sinais do pão e do vinho, testemunhando «até ao extremo» o seu amor pela humanidade (Jo 13, 1), por cuja salvação Se oferecerá em sacrifício.»'),
  (1, 'São Tomás de Aquino', 'Suma Teológica, III, q. 73, a. 5, resp. (texto abreviado; tradução a partir do latim)', '«… Quando o próprio Cristo estava para se apartar dos discípulos na sua figura própria, deixou-se-lhes a Si mesmo sob a figura sacramental, como na ausência do imperador se expõe à veneração a sua imagem. … O que se diz por último, sobretudo pelos amigos que partem, mais se grava na memória, porque então mais se inflama o afeto para com os amigos; e aquilo que mais nos toca mais profundamente se imprime na alma. … Por isso, para que fosse tido em maior veneração, o Senhor instituiu este sacramento na sua última despedida dos discípulos.»'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. IV «Da Eucaristia», § 1, 1ª e 3ª perguntas do capítulo. Tradução a partir do italiano. Texto abreviado.', '«— Que é o sacramento da Eucaristia? — A Eucaristia é um sacramento no qual, pela admirável conversão de toda a substância do pão no Corpo de Jesus Cristo e da do vinho no seu precioso Sangue, se contém verdadeira, real e substancialmente o Corpo, o Sangue, a Alma e a Divindade do mesmo Jesus Cristo Nosso Senhor, sob as espécies do pão e do vinho, para ser nosso alimento espiritual. … — Por que credes que no sacramento da Eucaristia está verdadeiramente Jesus Cristo? — Creio que no sacramento da Eucaristia está verdadeiramente presente Jesus Cristo, porque Ele mesmo o disse, e mo ensina a santa Igreja.»'),
  (3, 'São João Crisóstomo', 'Homilia sobre a traição de Judas, 1, 6 (citado no CIC 1375)', '«Não é o homem que faz com que as coisas oferecidas se tornem corpo e sangue de Cristo, mas o próprio Cristo, que foi crucificado por nós. O sacerdote, figura de Cristo, pronuncia estas palavras, mas a sua eficácia e a graça são de Deus. Isto é o Meu corpo, diz ele. Esta palavra transforma as coisas oferecidas.»'),
  (4, 'Catecismo da Igreja Católica', 'CIC 1376 (Concílio de Trento, sess. XIII, cap. 4)', 'O Concílio de Trento resume a fé católica, ao declarar: «Porque Cristo, nosso Redentor, disse que aquilo que oferecia sob a espécie do pão era verdadeiramente o seu corpo, sempre na Igreja se teve esta convicção, que o sagrado Concílio de novo declara: pela consagração do pão e do vinho opera-se a conversão de toda a substância do pão na substância do corpo de Cristo nosso Senhor e de toda a substância do vinho na substância do seu sangue; esta conversão, de modo conveniente e apropriado, foi chamada pela santa Igreja católica transubstanciação».'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. IV «Da Eucaristia», § 1, 11ª e 12ª perguntas do capítulo. Tradução a partir do italiano.', '«— Que é a consagração? — A consagração é a renovação, por meio do sacerdote, do milagre operado por Jesus Cristo na última ceia, de mudar o pão e o vinho no seu Corpo e no seu Sangue adorável, dizendo: isto é o meu corpo, isto é o meu sangue. — Como é chamada pela Igreja a milagrosa conversão do pão e do vinho no Corpo e no Sangue de Jesus Cristo? — A milagrosa conversão, que todos os dias se opera sobre os nossos altares, é chamada pela Igreja transubstanciação.»'),
  (6, 'São Tomás de Aquino', 'Sequência «Lauda Sion», da Missa do Corpo de Deus (texto abreviado; tradução a partir do latim)', '«É dogma dado aos cristãos / que o pão se muda em carne / e o vinho em sangue. / O que não compreendes, o que não vês, / afirma-o a fé animosa, / acima da ordem das coisas. / Sob espécies diversas, / sinais somente e não realidades, / ocultam-se coisas sublimes. / A carne é comida, o sangue é bebida; / mas Cristo permanece todo inteiro / sob uma e outra espécie.»'),
  (7, 'São Tomás de Aquino', 'Suma Teológica, III, q. 75, a. 1, e hino «Adoro te devote», citados no CIC 1381 (texto abreviado) (grafia adaptada ao Brasil)', 'A presença do verdadeiro corpo e do verdadeiro sangue de Cristo neste sacramento «não a apreendemos pelos sentidos … mas só pela fé, que se apoia na autoridade de Deus». … «Adoro-te com devoção, ó Deus que te escondes, / que sob estas figuras de verdade te ocultas: / a ti meu coração se submete inteiramente, / porque, ao contemplar-te, desfalece por completo. / Visão, tato e paladar em ti falham, / apenas ouvindo se crê com segurança: / creio em tudo o que disse o Filho de Deus: / nada mais verdadeiro que esta palavra da Verdade.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 5;

-- luminous-5 · 1 Co 11, 23-26
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Porque eu recebi do Senhor o que também vos ensinei a vós, que o Senhor Jesus, na noite em que foi entregue, tomou o pão, e, dando graças, o partiu, e disse: Tomai e comei; isto é o meu corpo, que será entregue por vós; fazei isto em memória de mim. Igualmente também, depois de ter ceado, (tomou) o cálice, dizendo: Este cálice é o novo testamento no meu sangue; fazei isto em memória de mim todas as vezes que o beberdes. Porque todas as vezes que comerdes este pão e beberdes este cálice, anunciareis a morte do Senhor, até que ele venha.', '1 Co 11, 23-26', 1
from public.mysteries m where m.type = 'luminous' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 1337', 'Tendo amado os seus, o Senhor amou-os até ao fim. Sabendo que era chegada a hora de partir deste mundo para regressar ao Pai, no decorrer duma refeição, lavou-lhes os pés e deu-lhes o mandamento do amor. Para lhes deixar uma garantia deste amor, para jamais se afastar dos seus e para os tornar participantes da sua Páscoa, instituiu a Eucaristia como memorial da sua morte e da sua ressurreição, e ordenou aos seus Apóstolos que a celebrassem até ao seu regresso, «constituindo-os, então, sacerdotes do Novo Testamento».'),
  (1, 'Catecismo da Igreja Católica', 'CIC 1366 (Concílio de Trento, sess. XXII, cap. 1) (texto abreviado)', 'A Eucaristia é, pois, um sacrifício, porque representa (torna presente) o sacrifício da cruz, porque é dele o memorial e porque aplica o seu fruto: Cristo «nosso Deus e Senhor […] ofereceu-Se a Si mesmo a Deus Pai uma vez por todas, morrendo como intercessor sobre o altar da cruz […]. No entanto, porque após a sua morte não se devia extinguir o seu sacerdócio, na última ceia, “na noite em que foi entregue” (1 Cor 11, 23) […] Ele [quis deixar] à Igreja, sua esposa bem-amada, um sacrifício visível […], em que fosse representado o sacrifício cruento que ia realizar uma vez por todas na cruz, perpetuando a sua memória até ao fim dos séculos e aplicando a sua eficácia salvífica à remissão dos pecados que nós cometemos cada dia».'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. V «Do santo sacrifício da Missa», § 1, 5ª e 11ª perguntas do capítulo. Tradução a partir do italiano. Texto abreviado.', '«— O sacrifício da Missa é o mesmo da Cruz? — O sacrifício da Missa é substancialmente o mesmo da Cruz, enquanto o mesmo Jesus Cristo, que se ofereceu sobre a Cruz, é o que se oferece, pelas mãos dos sacerdotes, seus ministros, sobre os nossos altares; mas, quanto ao modo com que é oferecido, o sacrifício da Missa difere do sacrifício da Cruz, conservando todavia com ele a mais íntima e essencial relação. … — Quem instituiu o sacrifício da santa Missa? — Instituiu-o o próprio Jesus Cristo quando instituiu o sacramento da Eucaristia; e disse que se fizesse em memória da sua Paixão.»'),
  (3, 'São Tomás de Aquino', 'Ofício do Corpo de Deus («Sacerdos»), Matinas, 1.º noturno, 2.ª lição (texto abreviado; tradução a partir do latim)', '«Ninguém é capaz de exprimir a suavidade deste sacramento, pelo qual se saboreia na sua própria fonte a doçura espiritual e se recorda a memória daquela excelentíssima caridade que Cristo mostrou na sua paixão. Por isso, para que a imensidade desta caridade se gravasse mais profundamente nos corações dos fiéis, na última ceia, quando, celebrada a Páscoa com os discípulos, estava para passar deste mundo ao Pai, instituiu este sacramento, como memorial perene da sua paixão, cumprimento das figuras antigas, o maior dos milagres por Ele operados e singular consolação para os que a sua ausência entristecia.»'),
  (4, 'São Tomás de Aquino', 'Ofício do Corpo de Deus, antífona «O sacrum convivium» do Magnificat das II Vésperas (tradução a partir do latim)', '«Ó sagrado banquete, em que Cristo é recebido, se recorda a memória da sua paixão, a alma se enche de graça e nos é dado o penhor da glória futura.»'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. IV «Da Eucaristia», § 1, 25ª e 26ª perguntas do capítulo. Tradução a partir do italiano.', '«— Por que motivo se conserva nas igrejas a santíssima Eucaristia? — A santíssima Eucaristia conserva-se nas igrejas para que seja adorada pelos fiéis e levada aos enfermos segundo a necessidade. — Deve-se adorar a Eucaristia? — A Eucaristia deve ser adorada por todos, porque contém verdadeira, real e substancialmente o mesmo Nosso Senhor Jesus Cristo.»'),
  (6, 'São João Paulo II', 'Ecclesia de Eucharistia, § 56 (texto abreviado)', '«Impossível imaginar os sentimentos de Maria, ao ouvir dos lábios de Pedro, João, Tiago e restantes apóstolos as palavras da Última Ceia: “Isto é o meu corpo que vai ser entregue por vós” (Lc 22, 19). Aquele corpo, entregue em sacrifício e presente agora nas espécies sacramentais, era o mesmo corpo concebido no seu ventre! Receber a Eucaristia devia significar para Maria quase acolher de novo no seu ventre aquele coração que batera em uníssono com o d''Ela …»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 5;

-- luminous-5 · Jo 6, 51-58
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Eu sou o pão vivo, que desci do céu. Quem comer deste pão, viverá eternamente; e o pão que eu darei, é a minha carne (que será sacrificada) para a salvação do mundo. Disputavam, pois, entre si os Judeus, dizendo: Como pode este dar-nos a comer a sua carne? E Jesus disse-lhes: Em verdade, em verdade vos digo: Se não comerdes a carne do Filho do homem, e não beberdes o seu sangue, não tereis a vida em vós. O que come a minha carne, e bebe o meu sangue, tem a vida eterna; e eu o ressuscitarei no último dia. Porque a minha carne é verdadeiramente comida, e o meu sangue é verdadeiramente bebida. O que come a minha carne, e bebe o meu sangue, fica em mim e eu nele. Assim como me enviou o Pai que vive, e eu vivo pelo Pai, assim o que me comer a mim, esse mesmo também viverá por mim (e da minha própria vida).', 'Jo 6, 51-58', 2
from public.mysteries m where m.type = 'luminous' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Santo Agostinho', 'Comentário ao Salmo 98, 9, citado por Paulo VI, Mysterium Fidei, § 57 (texto abreviado)', '«A mesma carne, com que andou (o Senhor) na terra, essa mesma nos deu a comer para nossa salvação; ninguém come aquela Carne sem primeiro a adorar … não só não pecamos adorando-a, mas pecaríamos se a não adorássemos.»'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte IV, cap. IV «Da Eucaristia», § 2, 4ª e 5ª perguntas do capítulo. Tradução a partir do italiano. Texto abreviado.', '«— Que efeitos produz em nós a santíssima Eucaristia? — Os efeitos principais que a santíssima Eucaristia produz em quem a recebe dignamente são estes: 1.º conserva e aumenta a vida da alma, que é a graça, como o alimento material sustenta e aumenta a vida do corpo; 2.º perdoa os pecados veniais e preserva dos mortais; 3.º produz consolação espiritual. — A santíssima Eucaristia não produz em nós outros efeitos? — Sim … 3.º dá-nos um penhor da glória futura e da própria ressurreição do nosso corpo.»'),
  (2, 'Catecismo da Igreja Católica', 'CIC 1391 (texto abreviado) (grafia adaptada ao Brasil)', 'A Comunhão aumenta a nossa união com Cristo. Receber a Eucaristia na comunhão traz consigo, como fruto principal, a união íntima com Cristo Jesus. De fato, o Senhor diz: «Quem come a minha carne e bebe o meu sangue permanece em Mim e Eu nele» (Jo 6, 56). A vida em Cristo tem o seu fundamento no banquete eucarístico: «Assim como o Pai, que vive, Me enviou, e Eu vivo pelo Pai, também o que Me come viverá por Mim» (Jo 6, 57).'),
  (3, 'São Cirilo de Jerusalém', 'Catequeses Mistagógicas, IV, 6 (citado por São João Paulo II, Ecclesia de Eucharistia, § 15) (grafia adaptada ao Brasil)', '«Não hás de ver o pão e o vinho [consagrados] simplesmente como elementos naturais, porque o Senhor disse expressamente que são o seu corpo e o seu sangue: a fé to assegura, ainda que os sentidos possam sugerir-te outra coisa.»'),
  (4, 'Santo Agostinho', 'Confissões, VII, 10, 16 (citado por Bento XVI, Sacramentum Caritatis, § 70)', '«Sou o pão dos fortes; cresce e comer-Me-ás. Não Me transformarás em ti como ao alimento da tua carne, mas mudar-te-ás em Mim.»')
) as v(sort_order, author, source, text) on true
where m.type = 'luminous' and m.sort_order = 5;

-- sorrowful-1 · Mt 26, 36-39
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então foi Jesus com eles a uma granja, chamada Getsemani, e disse-lhes: «Sentai-vos aqui, enquanto eu vou acolá, e faço oração.» E, tendo tomado consigo Pedro e os dois filhos de Zebedeu (Tiago e João), começou a entristecer-se e angustiar-se. Disse-lhes então: «A minha alma está numa tristeza mortal; ficai aqui e vigiai comigo.» E, adiantando-se um pouco, prostrou-se com o rosto em terra, orando e dizendo: «Meu Pai, se é possível, passe de mim este cálice; todavia não (se faça) como eu quero, mas sim como tu queres.»', 'Mt 26, 36-39', 0
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Tomás de Aquino', 'Suma Teológica, III, q. 46, a. 6, corpo do artigo (texto abreviado; tradução a partir do latim)', '… A causa da dor interior de Cristo foi, primeiro, todos os pecados do gênero humano, pelos quais satisfazia padecendo; por isso os atribui a si como seus, dizendo no Salmo: «as palavras dos meus delitos». Segundo, especialmente a queda dos judeus e dos outros que pecaram na sua morte, e sobretudo dos discípulos, que se escandalizaram na paixão de Cristo. Terceiro, a perda da vida corporal, que é naturalmente horrível à natureza humana. … A sua alma apreendia com toda a eficácia todas as causas de tristeza. … E por isso assumiu tão grande quantidade de dor quanta fosse proporcionada à grandeza do fruto que dela havia de seguir-se.'),
  (1, 'Dom Columba Marmion', '*Le Christ dans ses mystères* (Cristo nos seus mistérios), conferência «Le Christ a aimé l''Église et s''est livré pour elle», § II (ed. Desclée, 1922; texto abreviado; tradução a partir do original francês)', 'O Cristo, que nada exagera, revela aos seus apóstolos que a sua alma inocente está oprimida por uma tristeza tão pungente e tão amarga que é capaz de O fazer morrer. … Que abismo! Um Deus, a Potência e a Beatitude infinitas, «se encontra acabrunhado pela tristeza, pelo medo e pelo tédio». … Na divindade a que estava unida, a sua alma via claramente todos os pecados dos homens, todos os ultrajes feitos à santidade e ao amor infinito de Deus. Tomara sobre si todas essas iniquidades, como que se revestira delas. … Previa que para muitos homens o seu sangue seria derramado inutilmente, e essa vista levava ao cúmulo a amargura da sua santa alma.'),
  (2, 'Santo Agostinho', '*Enarrationes in Psalmos*, Sl 63 (n. 16 na tradução inglesa da série *Nicene and Post-Nicene Fathers*; texto abreviado; tradução a partir dessa versão inglesa)', '… Não carregava Ele a tua fraqueza quando dizia: «A minha alma está triste até à morte»? Não te figurava em Si mesmo quando dizia: «Pai, se é possível, passe de mim este cálice»? Pois não eram dois e diferentes os corações do Pai e do Filho; mas, na forma de servo, trouxe consigo o teu coração, para o ensinar com o seu exemplo. … Deus não consente com o teu coração: consente tu com o coração de Deus.'),
  (3, 'São Jerônimo', '*Comentário sobre São Mateus*, IV (Mt 26, 37-38), citado por S. Tomás de Aquino na *Catena Aurea*, in Mt 26, lect. 10 (texto abreviado; tradução a partir do latim)', 'Entristecia-se, pois, o Senhor, não por temor de padecer, Ele que viera precisamente para padecer, … mas por causa do infelicíssimo Judas, do escândalo de todos os apóstolos, da rejeição e reprovação do povo judeu e da ruína da desventurada Jerusalém. … E não se diz que se entristeceu por causa da morte, mas «até à morte», até que pela sua paixão libertasse os apóstolos.'),
  (4, 'São João Crisóstomo', '*Homilias sobre São Mateus*, homilia 83, 1 (texto abreviado; tradução a partir da versão inglesa da série *Nicene and Post-Nicene Fathers*)', 'Costumava orar afastado deles; e isto fazia para nos ensinar a preparar, nas nossas orações, silêncio e grande recolhimento. … Ao dizer: «Se é possível, passe de mim», mostrou a sua humanidade; mas ao dizer: «Todavia, não como eu quero, mas como tu queres», mostrou a sua virtude e o domínio de si, ensinando-nos a seguir a Deus mesmo quando a natureza nos puxa para trás.'),
  (5, 'Catecismo da Igreja Católica', 'CIC 612 (texto abreviado; grafia adaptada ao Brasil)', 'O cálice da Nova Aliança, que Jesus antecipou na Ceia, oferecendo-Se a Si mesmo, é aceite seguidamente por Jesus das mãos do Pai, na agonia no Getsêmani, fazendo-Se «obediente até à morte» (Fl 2, 8). Na sua oração, Jesus diz: «Meu Pai, se é possível, que se afaste de Mim este cálice [...]» (Mt 26, 39). Exprime desse modo o horror que a morte representa para a sua natureza humana. … Aceitando, com a sua vontade humana, que se faça a vontade do Pai, aceita a sua morte enquanto redentora, para «suportar os nossos pecados no seu corpo, no madeiro da cruz» (1 Pe 2, 24).'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. I «Da oração em geral», 22ª e 23ª perguntas do capítulo. Tradução a partir do italiano.', '«— Que quer dizer orar com resignação? — Quer dizer que nos devemos conformar à vontade de Deus, o qual conhece melhor do que nós o que é necessário à nossa salvação eterna, ainda mesmo no caso em que as nossas orações não fossem atendidas. — Deus atende sempre as orações bem feitas? — Sim, Deus atende sempre as orações bem feitas, mas da maneira que Ele sabe ser mais útil para a nossa salvação eterna, e nem sempre segundo a nossa vontade.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 1;

-- sorrowful-1 · Lc 22, 41-44
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E afastou-se deles a distância de um tiro de pedra; e, posto de joelhos, orava, dizendo: «Pai, se é do teu agrado, afasta de mim este cálice; não se faça, contudo, a minha vontade, mas a tua.» Então apareceu-lhe um anjo do céu, que o confortava. E, posto em agonia, orava mais instantemente. E o seu suor tornou-se como de gotas de sangue, que corria até à terra.', 'Lc 22, 41-44', 1
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Santo Ambrósio', '*Exposição do Evangelho segundo São Lucas*, livro X (sobre Lc 22, 43-44), citado por S. Tomás de Aquino na *Catena Aurea*, in Lc 22, lect. 12 (texto abreviado; tradução a partir do latim)', '… Em nenhum outro lugar admiro mais a sua bondade e a sua majestade; pois menos me teria dado, se não tivesse assumido o meu sentimento. Tomou, pois, a minha tristeza, para me dar a sua alegria. Com confiança falo de tristeza, porque prego a cruz. … Quis, portanto, ensinar-nos como venceríamos a morte e, o que é mais, a tristeza da morte que há de vir.'),
  (1, 'Dom Columba Marmion', '*Le Christ dans ses mystères* (Cristo nos seus mistérios), conferência «Le Christ a aimé l''Église et s''est livré pour elle», § I (ed. Desclée, 1922; texto abreviado; tradução a partir do original francês)', 'Vede o Cristo Jesus durante a sua agonia. … O tédio, a tristeza, o temor, as angústias precipitam-se sobre a sua alma como uma torrente, e a invadem a ponto de o sangue escapar de suas veias sagradas. … E que diz Jesus a seu Pai? «Pai, se é possível, afaste-se de mim este cálice.» … Esta oração é o grito da sensibilidade da pobre natureza humana esmagada pelo desgosto e pelo sofrimento. … Mas escutai o que acrescenta logo: «Todavia, ó Pai, faça-se a vossa vontade, e não a minha». Aqui está o triunfo do amor. Porque ama a seu Pai, põe a vontade do Pai acima de tudo, e aceita sofrer tudo.'),
  (2, 'Santo Agostinho', '*Enarrationes in Psalmos*, Sl 140 (n. 2 na tradução inglesa da série *Nicene and Post-Nicene Fathers*; texto abreviado; tradução a partir dessa versão inglesa)', '… Também Ele, quando estava aqui e trazia a nossa carne, orou; e, quando orava, gotas de sangue corriam de todo o seu corpo. Assim está escrito no Evangelho: «Jesus orava mais instantemente, e o seu suor tornou-se como gotas de sangue». Que significa este suor que corre de todo o seu corpo, senão o sofrimento dos mártires de toda a Igreja?'),
  (3, 'São Beda, o Venerável', '*Exposição sobre o Evangelho de São Lucas*, VI (Lc 22, 43-44), citado por S. Tomás de Aquino na *Catena Aurea*, in Lc 22, lect. 12 (texto abreviado; tradução a partir do latim)', 'O Criador não precisava do socorro da sua criatura; mas, feito homem, assim como por nós está triste, assim por nós é confortado. … Ninguém atribua este suor à fraqueza, pois é contra a natureza suar sangue; entenda antes que por ele nos foi declarado que obtinha já o efeito da sua prece: purificar com o seu sangue a fé dos discípulos, que a fragilidade terrena ainda acusava.'),
  (4, 'Imitação de Cristo', 'Livro III, cap. 15, 1-3 (texto abreviado; tradução a partir do latim)', 'Filho, dize assim em todas as coisas: «Senhor, se for do teu agrado, faça-se isto assim.» … «Senhor, tu sabes o que me é melhor, isto ou aquilo; dá-me o que queres, quanto queres e quando queres. … Eis aqui o teu servo, pronto para tudo.» … Seja a tua vontade a minha, e a minha vontade siga sempre a tua e com ela concorde perfeitamente.'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. I «Da oração em geral», 21ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que quer dizer orar com perseverança? — Quer dizer que não nos devemos cansar de orar, se Deus não nos atende logo, mas que devemos antes continuar a orar com mais fervor.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 1;

-- sorrowful-1 · Mt 26, 40-44
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Depois foi ter com seus discípulos, e encontrou-os dormindo, e disse a Pedro: «Visto isso não pudeste vigiar uma hora comigo? Vigiai e orai, para que não entreis em tentação. O espírito na verdade está pronto, mas a carne é fraca.» E retirou-se de novo pela segunda vez, e orou, dizendo: «Meu Pai, se este cálice não pode passar sem que eu o beba, faça-se a tua vontade.» E foi novamente, e encontrou-os dormindo; porque os seus olhos estavam pesados (por causa do sono). E, deixando-os, foi de novo, e orou terceira vez, dizendo as mesmas palavras.', 'Mt 26, 40-44', 2
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São João Crisóstomo', '*Homilias sobre São Mateus*, homilia 83, 1 (texto abreviado; tradução a partir da versão inglesa da série *Nicene and Post-Nicene Fathers*)', 'Os que desejavam morrer com Ele não foram capazes, naquela hora, nem sequer de se entristecer com Ele em vigília: o sono os venceu. … «Vigiai e orai, para que não entreis em tentação.» Vede como de novo os instrui a não confiarem em si mesmos, mas a serem contritos de espírito e humildes, e a referirem tudo a Deus. … E orou de novo do mesmo modo, dizendo: «Meu Pai, se este cálice não pode passar sem que eu o beba, faça-se a tua vontade», mostrando aqui que está plenamente de acordo com a vontade de Deus, e que devemos sempre segui-la e buscá-la.'),
  (1, 'São Jerônimo', '*Comentário sobre São Mateus*, IV (Mt 26, 41), citado por S. Tomás de Aquino na *Catena Aurea*, in Mt 26, lect. 11 (texto abreviado; tradução a partir do latim)', 'É impossível que a alma humana não seja tentada. Por isso não diz: «Vigiai e orai para não serdes tentados», mas: «para que não entreis em tentação», isto é, para que a tentação não vos vença. … Isto vai contra os temerários, que pensam poder alcançar tudo aquilo em que creem. Quanto mais confiamos no ardor do espírito, tanto mais temamos a fragilidade da carne.'),
  (2, 'São Leão Magno', 'Sermão 58 (Sobre a Paixão do Senhor, VII), 5, citado por S. Tomás de Aquino na *Catena Aurea*, in Mt 26, lect. 11 (tradução a partir do latim)', 'Esta voz da Cabeça é a salvação de todo o Corpo; esta voz instrui todos os fiéis, inflama todos os confessores, coroou todos os mártires. Pois quem poderia vencer os ódios do mundo, os turbilhões das tentações, os terrores dos perseguidores, se Cristo, em todos e por todos, não tivesse dito ao Pai: «Faça-se a tua vontade»? Aprendam, pois, esta voz todos os filhos da Igreja, para que, quando pesar sobre eles a adversidade de alguma tentação violenta, vencido o temor, aceitem a paciência no sofrimento.'),
  (3, 'Rabano Mauro', '*Comentário sobre São Mateus*, VIII (Mt 26, 44), citado por S. Tomás de Aquino na *Catena Aurea*, in Mt 26, lect. 11 (texto abreviado; tradução a partir do latim)', 'O Senhor orou três vezes para que peçamos perdão dos pecados passados, proteção nos males presentes e cautela nos perigos futuros; … e para que se conservem íntegros o nosso espírito, a alma e o corpo.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. II «Da oração dominical», § 4 «Da terceira petição», 1ª pergunta do parágrafo. Tradução a partir do italiano.', '«— Que pedimos na terceira petição: Seja feita a vossa vontade, assim na terra como no céu? — Na terceira petição pedimos a graça de fazer em todas as coisas a vontade de Deus, obedecendo aos seus santos mandamentos tão prontamente como os anjos e os santos Lhe obedecem no céu. Pedimos ainda a graça de corresponder às inspirações divinas e de viver resignados à vontade de Deus quando Ele nos manda tribulações.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 1;

-- sorrowful-2 · Mt 27, 26
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então soltou-lhes Barrabás; e, depois de fazer flagelar Jesus, entregou-lho para ser crucificado.', 'Mt 27, 26', 0
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Jerônimo', 'Comentário ao Evangelho de São Mateus, livro IV (sobre Mt 27, 26), no texto recolhido por S. Tomás na Catena Aurea in Mt 27, lição 4; tradução a partir do latim (texto abreviado)', '«Saiba-se que Pilatos se serviu das leis romanas, pelas quais estava determinado que quem fosse crucificado fosse antes açoitado. Jesus é, pois, entregue aos soldados para ser açoitado, e aquele santíssimo corpo, aquele peito que encerrava a Deus, foi retalhado pelos flagelos. … Isto, porém, se fez para que, estando escrito: “Muitos são os flagelos dos pecadores”, fôssemos nós, por aquele flagelo, livrados dos açoites.»'),
  (1, 'Santo Agostinho (atribuído)', 'Sermão sobre a Paixão (atribuído a Santo Agostinho), citado por S. Tomás na Catena Aurea in Mt 27, lição 4; tradução a partir do latim', '«Eis que o Senhor é preparado para os açoites, eis que já é ferido: a violência dos flagelos rompeu a sua santa pele; os golpes cruéis, repetidos sem cessar, dilaceram-lhe as costas. Ó dor! Deus jaz estendido diante do homem, e sofre o suplício de réu Aquele em quem não se pôde encontrar vestígio algum de pecado.»'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 46, a. 5 (texto abreviado; tradução a partir do latim)', '«[Cristo padeceu] no corpo, pelas chagas e pelos flagelos. … Na cabeça padeceu a coroa de espinhos pungentes; nas mãos e nos pés, a cravação dos pregos; no rosto, as bofetadas e os escarros; e em todo o corpo, os flagelos. Padeceu também segundo todos os sentidos do corpo: no tato, sendo flagelado e cravado com pregos; no gosto, sendo-lhe dado a beber fel e vinagre; no olfato, sendo suspenso no patíbulo num lugar fétido de cadáveres, chamado Calvário; no ouvido, sendo provocado pelas vozes dos que blasfemavam e escarneciam; na vista, vendo chorar a sua Mãe e o discípulo que amava.»'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 5ª pergunta do capítulo. Tradução a partir do italiano.', '«— Quem foi que condenou Jesus Cristo a ser crucificado? — Quem condenou Jesus Cristo a ser crucificado foi Pôncio Pilatos, governador da Judeia, o qual tinha reconhecido a inocência dele; mas cedeu covardemente à ameaçadora insistência do povo de Jerusalém.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 2;

-- sorrowful-2 · Jo 19, 1
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Pilatos, pois, tomou então Jesus e mandou-o flagelar.', 'Jo 19, 1', 1
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Tomás de Aquino', 'Comentário ao Evangelho de São João, cap. 19, lição 1, nn. 2372–2373', 'Pilatos tomou Jesus e o flagelou por meio dos soldados, esperando que os judeus, saciados com aquelas injúrias, deixassem de exigir a morte. … Estes, porém, moviam-se contra Cristo por ódio, e por isso a flagelação não bastava. … Será que esta intenção desculpa Pilatos? Não: afligir um inocente, e sobretudo o Filho de Deus, é sumamente mau por si; nenhuma intenção o desculpa.'),
  (1, 'Santo Agostinho', 'Tratados sobre o Evangelho de João, Tratado 116, §1', 'Então Pilatos tomou a Jesus e açoitou-o… para que os judeus, saciados com as injúrias, cessassem de se enfurecer até à morte dele. … O reino que não era deste mundo vencia o soberbo mundo não pela atrocidade de pelejar, mas pela humildade de padecer; aquele grão, que se havia de multiplicar, era semeado em horrível ultraje, para brotar em admirável glória.'),
  (2, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São João, homilia 84, 1 (sobre Jo 19, 1-3), na versão latina recolhida por S. Tomás na Catena Aurea in Jo 19, lição 1; tradução a partir do latim', '«Ele, enquanto se faziam tantas e tais coisas, permanecia calado. Tu, porém, ao ouvires isto, guarda-o continuamente na mente; e, vendo o Rei de toda a terra e Senhor dos Anjos padecer a afronta e suportar tudo em silêncio, imita-o.»'),
  (3, 'Leão XIII', 'Encíclica Laetitiae sanctae (8 de setembro de 1893), nn. 10–11 (texto abreviado)', '«Através destes mistérios vemos que Jesus … começou a fazer e a ensinar, a fim de que víssemos n''Ele próprio o exemplo prático dos ensinamentos que Ele daria à nossa humanidade, acerca da tolerância da dor e dos trabalhos; e o exemplo de Jesus chegou a tal ponto, que, voluntariamente e de grande coração, Ele mesmo abraçou tudo o que há de mais duro de suportar. … Vemo-lo flagelado, coroado de espinhos, crucificado… Todo aquele que se não contentar com olhar, porém meditar amiúde exemplos de tão excelsa virtude, oh! como se sentirá impelido a imitá-los!»'),
  (4, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 12 («Da estrada real da santa cruz»), nn. 7–8 (texto abreviado; tradução a partir do latim)', '«Toda a vida de Cristo foi cruz e martírio, e tu buscas para ti descanso e alegria? Enganas-te, enganas-te, se buscas outra coisa que não seja padecer tribulações. … E quanto mais a carne é abatida pela tribulação, tanto mais o espírito é fortalecido pela consolação interior.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 2;

-- sorrowful-2 · Is 50, 6
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Eu entreguei o meu corpo aos que me feriam, e a minha face aos que me arrancavam a barba; não desviei a minha face dos que me injuriavam e cuspiam.', 'Is 50, 6', 2
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Cirilo de Jerusalém', 'Catequeses, XIII, 13 (texto abreviado; tradução a partir da versão inglesa da Nicene and Post-Nicene Fathers)', '«O Espírito Santo escreveu de antemão, na pessoa de Cristo: “Entreguei as minhas costas aos flagelos” — pois Pilatos, depois de O açoitar, entregou-O para ser crucificado — … como se dissesse: “Sabendo de antemão que me feririam, nem sequer desviei a face; pois como teria eu fortalecido os meus discípulos contra a morte pela verdade, se eu mesmo a tivesse temido?” … Sendo Ele mesmo Deus, suportou padecer estas coisas da parte dos homens, para que depois nós, homens, quando padecermos tais coisas por amor d''Ele, não nos envergonhemos.»'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 6ª pergunta do capítulo. Tradução a partir do italiano.', '«— Não teria podido Jesus Cristo livrar-se das mãos dos judeus e de Pilatos? — Sim, Jesus Cristo teria podido livrar-se das mãos dos judeus e de Pilatos; mas, sabendo que a vontade do seu Eterno Pai era que Ele padecesse e morresse para a nossa salvação, submeteu-se voluntariamente; antes, Ele mesmo foi ao encontro dos seus inimigos, e deixou-se espontaneamente prender e conduzir à morte.»'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 46, a. 6 (texto abreviado; tradução a partir do latim)', '«Segundo o corpo, [Cristo] era de compleição perfeitíssima, pois o seu corpo fora formado milagrosamente por obra do Espírito Santo … e por isso nele era vivíssimo o sentido do tato, de cuja percepção se segue a dor. … Aquela paixão e aquela dor foram assumidas por Cristo voluntariamente, em vista da libertação dos homens do pecado; e por isso assumiu tanta dor quanta fosse proporcionada à grandeza do fruto que dela se havia de seguir.»'),
  (3, 'Catecismo da Igreja Católica', 'CIC 609', 'Ao partilhar, no seu coração humano, o amor do Pai para com os homens, Jesus «amou-os até ao fim» (Jo 13, 1), «pois não há maior amor do que dar a vida por aqueles que se ama» (Jo 15, 13). Assim, no sofrimento e na morte, a sua humanidade tornou-se instrumento livre e perfeito do seu amor divino, que quer a salvação dos homens. Com efeito, Ele aceitou livremente a sua paixão e morte por amor do Pai e dos homens a quem o Pai quer salvar: «Ninguém Me tira a vida. Sou Eu que a dou espontaneamente» (Jo 10, 18).')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 2;

-- sorrowful-2 · Is 53, 5
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Mas foi ferido por causa das nossas iniquidades, foi despedaçado por causa dos nossos crimes; o castigo que nos devia trazer a paz, caiu sobre ele, e nós fomos sarados com as suas pisaduras.', 'Is 53, 5', 3
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'Santo Afonso Maria de Ligório', '*Meditações para todos os dias e festas do ano*, Segunda Meditação para a Segunda-feira Santa («Jesus preso à coluna e flagelado»)', 'Contemplemos como os algozes começam a bater por toda a parte em nosso divino Redentor. Seu corpo virginal primeiro torna-se roxo; depois corre o sangue com tanta abundância… Pelo que o Senhor ficou transfigurado como um leproso, coberto de chagas desde a cabeça até aos pés. … Declara-O inocente, e depois manda-O castigar!'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 12ª e 13ª perguntas do capítulo. Tradução a partir do italiano.', '«— Era necessário que Jesus padecesse tanto? — Não, não era absolutamente necessário que Jesus padecesse tanto, porque o menor dos seus padecimentos teria bastado para a nossa redenção, sendo cada ato seu de valor infinito. — Por que, então, quis Jesus padecer tanto? — Jesus quis padecer tanto para satisfazer mais abundantemente à divina justiça, para nos mostrar mais o seu amor e para nos inspirar o maior horror ao pecado.»'),
  (2, 'São Jerônimo', 'Comentário ao Evangelho de São Mateus, livro IV (sobre Mt 27, 31), no texto recolhido por S. Tomás na Catena Aurea in Mt 27, lição 5; tradução a partir do latim (texto abreviado)', '«Note-se que, quando Jesus é flagelado e coberto de escarros, não tem as suas próprias vestes, mas as que assumira por causa dos nossos pecados.»'),
  (3, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 1 («Da conversação interior»), nn. 4–5 (texto abreviado; tradução a partir do latim)', '«Se não sabes contemplar as coisas altas e celestes, descansa na paixão de Cristo e habita de boa vontade nas suas sagradas chagas. Porque, se te refugiares devotamente nas chagas e nos formosos estigmas de Jesus, sentirás grande consolação na tribulação. … O Senhor Jesus quis padecer e ser desprezado, e tu ousas queixar-te de alguma coisa?»'),
  (4, 'Catecismo da Igreja Católica', 'CIC 1851', 'É precisamente na paixão, em que a misericórdia de Cristo o vai vencer, que o pecado manifesta melhor a sua violência e a sua multiplicidade: incredulidade, ódio assassino, rejeição e escárnio por parte dos chefes e do povo, cobardia de Pilatos e crueldade dos soldados, traição de Judas tão dura para Jesus, negação de Pedro e abandono dos discípulos. No entanto, mesmo na hora das trevas e do príncipe deste mundo, o sacrifício de Cristo torna-se secretamente a fonte de onde brotará, inesgotável, o perdão dos nossos pecados.')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 2;

-- sorrowful-3 · Mt 27, 27-31
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então os soldados do governador, conduzindo Jesus ao Pretório, juntaram em volta dele toda a coorte; e, despindo-o, lançaram sobre ele um manto carmesim. E, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e na mão direita uma cana. E, dobrando o joelho diante dele, o escarneciam, dizendo: «Deus te salve, rei dos Judeus.» E, cuspindo-lhe, tomavam a cana, e batiam-lhe (com ela) na cabeça. E, depois que o escarneceram, tiraram-lhe o manto, e revestiram-no com os seus vestidos, e levaram-no para o crucificarem.', 'Mt 27, 27-31', 0
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São Mateus, homilia 87, 1 (sobre Mt 27, 27-29), na versão latina recolhida por S. Tomás na Catena Aurea in Mt 27, lição 5; tradução a partir do latim', '«Que caso faremos daqui em diante das afrontas que padecermos dos outros, depois que Cristo padeceu isto? Pois o que se fazia contra Cristo era o último limite da afronta; e não uma só parte, mas o corpo inteiro padecia injúrias: a cabeça, pela coroa, pela cana e pelos socos; o rosto, porque era cuspido; as faces, porque eram feridas com bofetadas; o corpo todo, pelos flagelos, por ter sido despido e envolto no manto e pela fingida adoração; a mão, pela cana que lhe deram por cetro; como se temessem deixar de fora alguma coisa da mais grave insolência.»'),
  (1, 'São Jerônimo', 'Comentário ao Evangelho de São Mateus, livro IV (sobre Mt 27, 27-29), no texto recolhido por S. Tomás na Catena Aurea in Mt 27, lição 5; tradução a partir do latim (texto abreviado)', '«Nós, porém, entendamos tudo isto misticamente. Assim como Caifás disse: “Convém que um só homem morra por todos”, sem saber o que dizia, assim também estes, tudo quanto fizeram, ainda que com outra intenção o fizessem, a nós que cremos ofereciam mistérios: no manto escarlate, [Cristo] carrega as obras sangrentas dos gentios; na coroa de espinhos, desata a antiga maldição; na cana, mata os animais venenosos. …»'),
  (2, 'Santo Hilário de Poitiers', 'Comentário ao Evangelho de São Mateus (sobre Mt 27, 28-30), no texto recolhido por S. Tomás na Catena Aurea in Mt 27, lição 5; tradução a partir do latim (texto abreviado)', '«Tendo o Senhor assumido todas as enfermidades do nosso corpo, é depois banhado na cor escarlate pelo sangue de todos os mártires, aos quais era devido o reino com Ele; é coroado também de espinhos, isto é, dos pecados das nações, que outrora pungiam: pois há aguilhão nos espinhos, e deles se tece para Cristo a coroa da vitória. …»'),
  (3, 'Orígenes', 'Comentário ao Evangelho de São Mateus (sobre Mt 27, 31), no texto recolhido por S. Tomás na Catena Aurea in Mt 27, lição 6; tradução a partir do latim', '«Do manto, está escrito que de novo o despojaram; mas, da coroa de espinhos de Deus, nada semelhante escreveram os Evangelistas: para que já não existam os nossos antigos espinhos, depois que Jesus, uma vez, os tirou de nós sobre a sua venerável cabeça.»'),
  (4, 'São Tomás de Aquino', 'Exposição do Símbolo dos Apóstolos (Collationes in Symbolum), art. 4; tradução a partir do latim', '«Se procuras exemplo de desprezo das coisas terrenas, segue Aquele que é Rei dos reis e Senhor dos senhores, em quem estão os tesouros da sabedoria; e, contudo, na cruz, despido, escarnecido, cuspido, ferido, coroado de espinhos, dessedentado com fel e vinagre, e morto. Não te apegues, pois, às vestes e às riquezas, porque “repartiram entre si as minhas vestes” (Sl 21, 19); nem às honras, porque eu experimentei os escárnios e os açoites; nem às dignidades, porque “tecendo uma coroa de espinhos, a puseram sobre a minha cabeça”; nem aos deleites, porque “na minha sede me deram a beber vinagre” (Sl 68, 22). Diz Santo Agostinho: “O homem Cristo Jesus desprezou todos os bens terrenos, para mostrar que devem ser desprezados.”»'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte V, cap. VIII «Dos exercícios devotos que se aconselham ao cristão para cada dia», 18ª e 19ª perguntas do capítulo. Tradução a partir do italiano.', '«— Além das orações jaculatórias, em que outra coisa deveria exercitar-se frequentemente o cristão? — Além das orações jaculatórias, o cristão deveria exercitar-se na mortificação cristã. — Que quer dizer mortificar-se? — Mortificar-se quer dizer deixar, por amor de Deus, aquilo que agrada, e aceitar aquilo que desagrada segundo os sentidos ou o amor-próprio.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 3;

-- sorrowful-3 · Jo 19, 2-5
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e revestiram-no com um manto de púrpura. Depois, aproximavam-se dele, e diziam-lhe: «Deus te salve, rei dos Judeus»; e davam-lhe bofetadas. Saiu Pilatos ainda outra vez fora, e disse-lhes: «Eis que vo-lo trago fora, para que conheçais que não encontro nele crime algum.» Saiu, pois, Jesus trazendo a coroa de espinhos e o manto de púrpura. E (Pilatos) disse-lhes: «Eis aqui o homem.»', 'Jo 19, 2-5', 1
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Bernardo de Claraval', 'Sermão 2, Solenidade de Todos os Santos (Liturgia das Horas, v. IV; PL 183) (texto abreviado)', 'Enquanto isto não sucede, a nossa Cabeça não como é, mas como se fez por nós, se nos apresenta: não coroada de glória, mas com os espinhos dos nossos pecados. É uma vergonha fazer-se membro delicado sob uma cabeça coroada de espinhos. Por enquanto a púrpura não lhe é sinal de honra, mas de zombaria; será sinal de honra quando Cristo vier …'),
  (1, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 116, 2 (sobre Jo 19, 4-6), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lições 1-2; tradução a partir do latim', '«Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura: não ilustre pelo poder, mas cheio de opróbrio. E diz-lhes: “Eis aqui o homem”; como se dissesse: Se invejais o rei, poupai-o já, porque o vedes abatido; ferve a ignomínia, arrefeça a inveja. … Mas a inveja dos judeus não arrefece com a ignomínia de Cristo; antes se inflama e cresce.»'),
  (2, 'São Tomás de Aquino', 'Comentário ao Evangelho de São João, cap. 19, lição 1 (sobre Jo 19, 2); tradução a partir do latim (texto abreviado)', '«Escarnecem-no quanto à coroa, porque os reis costumam ser coroados de ouro. … Mas os soldados, tecendo uma coroa de espinhos, puseram-na sobre a cabeça daquele que é, para os seus, coroa de glória: “Naquele dia o Senhor dos exércitos será coroa de glória … para o resto do seu povo” (Is 28, 5). E convenientemente de espinhos: porque por eles tirou os espinhos dos pecados, que pungem com o remorso da consciência, … e os espinhos das penas, que afligem: “Ela te produzirá espinhos e abrolhos” (Gn 3, 18).»'),
  (3, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 1 («Da conversação interior»), nn. 5–6 (texto abreviado; tradução a partir do latim)', '«Cristo teve adversários e detratores, e tu queres ter a todos por amigos e benfeitores? Onde será coroada a tua paciência, se nada te acontecer de adverso? … Sofre com Cristo e por Cristo, se queres reinar com Cristo. Se uma vez entrasses perfeitamente no íntimo de Jesus e saboreasses um pouco do seu ardente amor, então não te importarias nada com o teu próprio cômodo ou incômodo, mas antes te alegrarias com o opróbrio que te fizessem, porque o amor de Jesus faz o homem desprezar-se a si mesmo.»'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte V, cap. III «Das Bem-aventuranças evangélicas», 2ª e 3ª perguntas do capítulo. Tradução a partir do italiano.', '«— Quem são aqueles que o mundo chama bem-aventurados? — O mundo chama bem-aventurados aqueles que abundam em riquezas e honras, que vivem alegremente e que não têm ocasião alguma de padecer. — Por que nos propôs Jesus Cristo as Bem-aventuranças? — Jesus Cristo propôs-nos as Bem-aventuranças para nos fazer detestar as máximas do mundo e para nos convidar a amar e praticar as máximas do seu Evangelho.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 3;

-- sorrowful-4 · Jo 19, 16-17
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Então entregou-lho, para que fosse crucificado. Então eles tomaram Jesus, e conduziram-no para fora. E, levando a sua cruz, saiu para o lugar que se chama Calvário, e em hebraico Gólgota …', 'Jo 19, 16-17', 0
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 117, 3 (sobre Jo 19, 17), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 5; tradução a partir do latim', 'Grande espetáculo! Mas, se o contempla a impiedade, grande ludíbrio; se a piedade, grande mistério. A impiedade vê um rei que, em lugar do cetro do seu reino, carrega o lenho do seu suplício; a piedade vê o Rei que carrega o lenho em que Ele mesmo havia de ser pregado, e que havia de fixar até na fronte dos reis: desprezado pelos olhos dos ímpios, nele haveriam de gloriar-se os corações dos santos. Levando ao ombro a sua própria cruz, recomendava-a; e carregava o candelabro para a lâmpada que havia de arder e não devia ser posta debaixo do alqueire.'),
  (1, 'São Tomás de Aquino', 'Comentário ao Evangelho de São João, cap. 19, lição 3, n. 2415 (sobre Jo 19, 17); tradução a partir do latim (texto abreviado)', 'O lugar da Paixão estava fora da cidade: «saiu para o lugar que se chama Calvário», isto é, fora dos muros da cidade … E isto por duas razões. Primeiro, para mostrar que a virtude da sua Paixão não devia ficar encerrada nos limites do povo judeu; segundo, para mostrar que todos os que querem alcançar o fruto da Paixão devem sair do mundo, ao menos pelo afeto. Por isso o Apóstolo acrescenta logo: «Saiamos, pois, a Ele, fora do acampamento» (Hb 13, 13).'),
  (2, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São João, homilia 85, 1 (sobre Jo 19, 17), na versão latina recolhida por S. Tomás na Catena Aurea in Jo 19, lição 5; tradução a partir do latim (texto abreviado)', 'Como tinham o lenho por profano, e o evitavam, e nem sequer suportavam tocá-lo, puseram a cruz sobre Jesus, como sobre um condenado … Assim também aconteceu na figura: Isaac levou a lenha; mas então a coisa só chegou até ao beneplácito do pai, ao passo que agora se cumpriu de fato, porque era a verdade … E, como fazem os vencedores, também Ele levava aos ombros o sinal da vitória.'),
  (3, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 12 («Da estrada real da santa cruz»), n. 2 (texto abreviado; tradução a partir do latim)', 'Por que temes, pois, tomar a cruz, pela qual se vai ao Reino? Na cruz está a salvação, na cruz a vida, na cruz a proteção contra os inimigos … Toma, pois, a tua cruz e segue a Jesus, e irás para a vida eterna. Ele foi adiante, levando a sua cruz, e morreu por ti na cruz, para que também tu leves a tua cruz e desejes morrer na cruz. Porque, se com Ele morreres, com Ele igualmente viverás; e, se fores companheiro na pena, sê-lo-ás também na glória.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. II «Da oração dominical», § 8 «Da sétima petição», 42ª pergunta do capítulo. Tradução a partir do italiano.', '— Para que nos servem as tribulações que Deus nos envia? — As tribulações servem-nos para fazer penitência das nossas culpas, para exercitar as virtudes e, sobretudo, para imitar Jesus Cristo, nossa cabeça, ao qual é justo que nos conformemos nos padecimentos, se queremos ter parte na sua glória.')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 4;

-- sorrowful-4 · Lc 23, 26-31
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, quando o iam conduzindo, agarraram um certo (homem chamado) Simão Cireneu, que voltava do campo; e puseram a cruz sobre ele, para que a levasse após de Jesus. E seguia-o uma grande multidão de povo e de mulheres, as quais batiam no peito, e o lamentavam. Porém Jesus, voltando-se para elas, disse: Filhas de Jerusalém, não choreis sobre mim, mas chorai sobre vós mesmas e sobre vossos filhos. … Porque, se isto se faz no lenho verde, que se fará no seco?', 'Lc 23, 26-31', 1
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Santo Ambrósio', 'Exposição do Evangelho segundo Lucas, livro X (sobre Lc 23, 26), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 4; tradução a partir do latim (texto abreviado)', 'Cristo, carregando a cruz, já levava como vencedor o seu troféu … Seja Simão, seja Ele mesmo quem a levou, Cristo a levou no homem, e o homem a levou em Cristo. Nem discordam as narrações dos Evangelistas, quando concorda o mistério. E é boa a ordem do nosso progresso: que primeiro Ele mesmo erguesse os troféus da sua cruz, e depois os entregasse aos mártires para que os erguessem. Não é um judeu quem leva a cruz, mas um estrangeiro e peregrino; e não vai à frente, mas segue atrás, conforme está escrito: «Tome a sua cruz e siga-me».'),
  (1, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 12 («Da estrada real da santa cruz»), n. 5 (tradução a partir do latim)', 'Se levas a cruz de boa vontade, ela te levará e te conduzirá ao fim desejado, onde, a saber, o sofrer terá fim. Se a levas de má vontade, fazes dela um fardo para ti e mais te sobrecarregas a ti mesmo; e, contudo, é preciso que a suportes. Se rejeitas uma cruz, sem dúvida acharás outra, e talvez mais pesada.'),
  (2, 'São Beda, o Venerável', 'Exposição do Evangelho de São Lucas, livro VI (sobre Lc 23, 26), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 4; tradução a partir do latim', 'Simão interpreta-se «obediente», e Cirene, «herdeiro»; por ele são designados os povos gentios, que, outrora peregrinos e estranhos às alianças, agora, obedecendo, se tornaram herdeiros de Deus. Saindo do campo, Simão leva a cruz após Jesus, quando, deixados os ritos pagãos, abraça obedientemente os passos da Paixão do Senhor.'),
  (3, 'São Beda, o Venerável', 'Exposição do Evangelho de São Lucas, livro VI (sobre Lc 23, 27), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 4; tradução a partir do latim', 'Uma grande multidão seguia a cruz do Senhor, mas não com um só e mesmo ânimo: o povo, que tinha pedido a sua morte, seguia-o para o ver morrer com alegria; as mulheres, para chorar aquele que ia morrer.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte V, cap. III «Das Bem-aventuranças evangélicas», 6ª pergunta do capítulo. Tradução a partir do italiano.', '— Quem são os que choram e, contudo, são chamados bem-aventurados? — Os que choram e, contudo, são chamados bem-aventurados são os que sofrem com resignação as tribulações e se afligem pelos pecados cometidos, pelos males e pelos escândalos que se veem no mundo, pela distância do paraíso e pelo perigo de perdê-lo.'),
  (5, 'São Beda, o Venerável', 'Exposição do Evangelho de São Lucas, livro VI (sobre Lc 23, 31), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 4; tradução a partir do latim', 'Ou, como se dissesse a todos: Se eu, que não cometi pecado e sou chamado árvore da vida, não saio do mundo sem o fogo da Paixão, que tormento pensas que espera aqueles que estão vazios de frutos?')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 4;

-- sorrowful-4 · Lc 9, 23
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E dizia a todos: Se alguém quer vir após de mim, negue-se a si mesmo, e tome a sua cruz todos os dias, e siga-me.', 'Lc 9, 23', 2
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 618 (grafia adaptada ao Brasil)', 'A cruz é o único sacrifício de Cristo, mediador único entre Deus e os homens. Mas porque, na sua pessoa divina encarnada, «Ele Se uniu, de certo modo, a cada homem», «a todos dá a possibilidade de se associarem a este mistério pascal, por um modo só de Deus conhecido». Convida os discípulos a tomarem a sua cruz e a segui-Lo porque sofreu por nós, deixando-nos o exemplo, para que sigamos os seus passos. De fato, quer associar ao seu sacrifício redentor aqueles mesmos que são os primeiros beneficiários. Isto realiza-se, em sumo grau, em sua Mãe, associada, mais intimamente do que ninguém, ao mistério do seu sofrimento redentor: «Há uma só escada verdadeira fora do paraíso; fora da cruz, não há outra escada por onde se suba ao céu».'),
  (1, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São Mateus (sobre Mt 16, 24), na versão latina recolhida por S. Tomás na Catena Aurea in Lc 9, lição 5; tradução a partir do latim', 'Sendo o Salvador piedoso e benigno, não quer ter nenhum servo forçado ou constrangido, mas servos espontâneos, que lhe agradeçam o serviço; por isso, sem forçar ninguém nem impor necessidade, mas persuadindo e fazendo o bem, atrai todos os que querem, dizendo: «Se alguém quer».'),
  (2, 'São Gregório Magno', 'Homilias sobre os Evangelhos, no texto recolhido por S. Tomás na Catena Aurea in Lc 9, lição 5; tradução a partir do latim', 'De dois modos se toma a cruz: quando o corpo é afligido pela abstinência, ou quando o ânimo é tocado pela compaixão.'),
  (3, 'Santo Ambrósio', 'Exposição do Evangelho segundo Lucas (sobre Lc 9, 23-27), no texto recolhido por S. Tomás na Catena Aurea in Lc 9, lição 5; tradução a partir do latim (texto abreviado)', 'É árduo tomar a cruz, e oferecer a alma aos perigos e o corpo à morte; negar o que és, quando quererias ser o que não és … Por isso o bom Mestre, para que ninguém se quebre pelo desespero ou pelo tédio, promete logo mostrar-se aos fiéis.'),
  (4, 'São Tomás de Aquino', 'Suma Teológica, II-II, q. 136, a. 3 (texto abreviado; tradução a partir do latim)', 'Como diz Agostinho no livro Da paciência, «a força dos desejos faz suportar os trabalhos e as dores, e ninguém assume espontaneamente carregar o que o crucia, senão por aquilo que o deleita» … Ora, que alguém prefira o bem da graça a todos os bens naturais, de cuja perda pode nascer a dor, pertence à caridade, que ama a Deus sobre todas as coisas. Donde é manifesto que a paciência, enquanto virtude, é causada pela caridade, segundo aquilo: «A caridade é paciente» (1 Cor 13, 4) … Donde se vê que a paciência não pode ter-se sem o auxílio da graça.'),
  (5, 'Imitação de Cristo', 'Imitação de Cristo, livro II, cap. 12 («Da estrada real da santa cruz»), n. 15 (tradução a partir do latim)', 'Se houvesse alguma coisa melhor e mais útil à salvação dos homens do que o padecer, Cristo certamente o teria mostrado por palavra e exemplo. Pois aos discípulos que o seguiam, e a todos os que desejam segui-lo, exorta claramente a levar a cruz, dizendo: «Se alguém quer vir após mim, negue-se a si mesmo, tome a sua cruz e siga-me». Lidas, pois, e examinadas todas as coisas, seja esta a conclusão final: por muitas tribulações nos é necessário entrar no reino de Deus.'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. II «Da oração dominical», § 4 «Da terceira petição», 22ª pergunta do capítulo. Tradução a partir do italiano.', '— Devemos sempre reconhecer a vontade de Deus nas coisas prósperas ou adversas da vida? — Nas coisas, tanto prósperas como adversas, da vida presente devemos sempre reconhecer também a vontade de Deus, o qual tudo dispõe ou permite para o nosso bem.')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 4;

-- sorrowful-5 · Lc 23, 33-46
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Quando chegaram ao lugar que se chama Calvário, ali o crucificaram a ele e aos ladrões, um à direita e outro à esquerda. E Jesus dizia: Pai, perdoa-lhes, porque não sabem o que fazem. E, dividindo os seus vestidos, sortearam-nos. … E um daqueles ladrões que estavam pendurados blasfemava contra ele, dizendo: Se tu és o Cristo, salva-te a ti mesmo e a nós. O outro, porém, tomando a palavra, repreendia-o, dizendo: Nem tu temes a Deus, estando no mesmo suplício? E nós estamos na verdade justamente, porque recebemos o (castigo) que merecem as nossas ações, mas este não fez nenhum mal. E dizia a Jesus: Senhor, lembra-te de mim, quando entrares no teu reino. E Jesus disse-lhe: Em verdade te digo: Hoje estarás comigo no paraíso. … E Jesus, exclamando em alta voz, disse: Pai, nas tuas mãos encomendo o meu espírito. E, dizendo isto, expirou.', 'Lc 23, 33-46', 0
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Gregório Magno', 'Moralia in Iob (sobre o bom ladrão), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 7; tradução a partir do latim (texto abreviado)', 'Os cravos tinham-lhe pregado na cruz as mãos e os pés, e nada nele ficara livre dos tormentos senão o coração e a língua. Por inspiração de Deus, ofereceu-Lhe tudo o que em si achou de livre, para que, como está escrito, com o coração cresse para a justiça e com a boca confessasse para a salvação. … Fé teve, pois creu que havia de reinar Aquele a quem via morrer juntamente consigo; esperança teve, pois pediu a entrada no seu Reino; e conservou viva a caridade na própria morte, pois repreendeu da sua iniquidade o irmão e companheiro de latrocínio, que morria pelo mesmo crime.'),
  (1, 'Santo Ambrósio', 'Exposição do Evangelho segundo Lucas, livro X (sobre Lc 23, 42-43), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 7; tradução a partir do latim (texto abreviado)', 'Dá-se aqui um belíssimo exemplo da conversão que devemos desejar: tão depressa é concedido o perdão ao ladrão. Depressa perdoa o Senhor, porque depressa ele se converte; e a graça é mais abundante que a súplica, pois o Senhor sempre dá mais do que se Lhe pede. Ele pedia que se lembrasse dele … A vida, com efeito, é estar com Cristo; e onde está Cristo, aí está o Reino.'),
  (2, 'São João Crisóstomo (atribuído)', 'Texto citado sob o seu nome por S. Tomás na Catena Aurea in Lc 23, lição 6 (sobre Lc 23, 34); tradução a partir do latim (texto abreviado)', 'Porque o Senhor dissera: Orai pelos que vos perseguem, também isto fez ao subir à cruz, dizendo: Pai, perdoa-lhes; não porque não pudesse Ele mesmo perdoar, mas para nos ensinar a orar pelos que nos perseguem, não só com a palavra, mas também com a obra.'),
  (3, 'São Beda, o Venerável', 'Exposição do Evangelho de São Lucas, livro VI (sobre Lc 23, 34), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 6; tradução a partir do latim', 'Nem se há de pensar que orou em vão; antes, alcançou o que pedia naqueles que creram depois da sua paixão.'),
  (4, 'Pio XII', 'Encíclica Haurietis aquas (15 de maio de 1956), n. 38 (texto abreviado)', '… O amor de Jesus Cristo, Filho de Deus, revela no sacrifício do Gólgota, de modo o mais eloquente, o amor do próprio Deus … Certamente, o divino Redentor foi crucificado mais pela força do amor do que pela violência dos algozes, e o seu holocausto voluntário é dom supremo feito a cada um dos homens, segundo a incisiva expressão do Apóstolo: «Amou-me e entregou-se por mim» (Gl 2, 20).'),
  (5, 'Santo Agostinho', 'Sermão 218, De passione Domini (texto abreviado)', 'A Paixão de nosso Senhor e Salvador Jesus Cristo é para nós penhor de glória e exemplo de paciência. … Portanto, de modo algum devemos envergonhar-nos da morte de nosso Deus e Senhor; pelo contrário, nela devemos confiar e gloriar-nos acima de tudo. … Reconheçamos corajosamente, irmãos, e proclamemos bem alto que Cristo foi crucificado por amor de nós … não com vergonha, mas com santo orgulho. … Quanto a mim, que eu me glorie somente na cruz do Senhor nosso, Jesus Cristo (Gl 6, 14).'),
  (6, 'Santo Ambrósio', 'Exposição do Evangelho segundo Lucas, livro X (sobre Lc 23, 46), no texto recolhido por S. Tomás na Catena Aurea in Lc 23, lição 8; tradução a partir do latim', 'Entregou o espírito, porque não o perdeu contra a vontade: o que se entrega é voluntário; o que se perde é forçoso.')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 5;

-- sorrowful-5 · Jo 19, 25-27
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Entretanto estavam de pé junto à cruz de Jesus sua Mãe, e a irmã de sua Mãe, Maria, mulher de Cleofas, e Maria Madalena. Jesus, pois, tendo visto sua Mãe e o discípulo que ele amava, o qual estava presente, disse a sua Mãe: Mulher, eis aí o teu filho. Depois disse ao discípulo: Eis aí a tua Mãe. E, desta hora por diante, a levou o discípulo para sua casa.', 'Jo 19, 25-27', 1
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Leão XIII', 'Encíclica Iucunda semper expectatione, sobre o Rosário (8 de setembro de 1894), n. 6 (texto abreviado)', '… Na sua própria presença e sob seus olhos devia consumar-se aquele divino sacrifício para o qual, com o próprio leite, ela generosamente criara a vítima. Isto se contempla no último e mais comovente destes mistérios. «Estava junto à Cruz de Jesus Maria sua Mãe», a qual, movida por um imenso amor a nós, para nos ter como seus filhos ofereceu, ela mesma, seu Filho à justiça divina, e com Ele morreu no seu coração, traspassada pela espada da dor.'),
  (1, 'Santo Ambrósio', 'Texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 8 (sobre Jo 19, 25); tradução a partir do latim (texto abreviado)', 'Maria, Mãe do Senhor, estava de pé diante da cruz do Filho. Ninguém mo ensinou senão São João Evangelista. … Nem Maria era menos do que convinha à Mãe de Cristo: fugindo os apóstolos, estava de pé diante da cruz e contemplava com olhos piedosos as chagas do Filho, porque olhava não para a morte do seu Filho querido, mas para a salvação do mundo.'),
  (2, 'São Bernardo de Claraval', 'Sermo in dom. infra oct. Assumptionis, 14-15 (texto abreviado)', 'Verdadeiramente, ó bem-aventurada Mãe, uma espada traspassou o teu coração. Pois só passando pelo teu coração a espada podia entrar na carne do teu Filho. … Assim a violência da dor traspassou o teu coração, e com razão te chamamos mais que mártir, pois o efeito da compaixão em ti ultrapassou a resistência ao sofrimento corporal. … Quem és tu … para te espantares mais com a compaixão de Maria do que com a paixão do Filho de Maria?'),
  (3, 'Pio XII', 'Encíclica Mystici Corporis Christi (29 de junho de 1943), n. 106 (texto abreviado)', 'Foi ela, a Imaculada, isenta de toda a mancha original ou atual, e sempre intimamente unida com seu Filho, que, como outra Eva, juntamente com o holocausto dos seus direitos maternos e do seu materno amor, o ofereceu no Gólgota ao Eterno Pai por todos os filhos de Adão, manchados pela sua queda miseranda; de modo que a que era fisicamente Mãe da nossa divina cabeça foi, com novo título de dor e de glória, feita espiritualmente mãe de todos os seus membros. … Ela finalmente, suportando com ânimo forte e confiante imensas dores, verdadeira Rainha dos mártires, mais que todos os fiéis, «completou o que falta à paixão de Cristo… pelo seu corpo que é a Igreja» (Cl 1, 24).'),
  (4, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 119, 1-2 (sobre Jo 19, 25-27), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 8; tradução a partir do latim (texto abreviado)', 'Esta era, sem dúvida, aquela hora de que Jesus, quando ia converter a água em vinho, dissera à Mãe: Mulher, que nos importa a mim e a ti isso? Ainda não chegou a minha hora. Então, prestes a fazer obras divinas, afastava como desconhecida a mãe, não da divindade, mas da humanidade e da fraqueza; agora, já padecendo as coisas humanas, recomendava com afeto humano aquela de quem se fizera homem. … O bom Mestre ensina com o seu exemplo, como se aquele madeiro, onde estavam pregados os membros do Moribundo, fosse também a cátedra do Mestre que ensina.'),
  (5, 'Catecismo da Igreja Católica', 'CIC 964 (grafia adaptada ao Brasil)', 'O papel de Maria em relação à Igreja é inseparável da sua união com Cristo e decorre dela diretamente. … É particularmente manifesta na hora da sua paixão: «A Bem-aventurada Virgem avançou na peregrinação de fé, e manteve fielmente a sua união com o seu Filho até à Cruz, junto da qual esteve de pé, não sem um desígnio divino; padeceu acerbamente com o seu Filho único e associou-se com coração de mãe ao seu sacrifício, consentindo amorosamente na imolação da vítima que d''Ela nascera; e, por fim, foi dada por mãe ao discípulo …: "Mulher, eis aí o teu filho" (Jo 19, 26-27)».'),
  (6, 'São João Paulo II', 'Carta apostólica Salvifici doloris (11 de fevereiro de 1984), n. 25 (texto abreviado)', '… Foi no Calvário que o sofrimento de Maria Santíssima, conjunto ao de Jesus, atingiu um ponto culminante dificilmente imaginável na sua sublimidade para o entendimento humano; mas, misterioso, por certo sobrenaturalmente fecundo para os fins da salvação universal. A sua subida ao Calvário e aquele seu «estar» aos pés da Cruz com o discípulo amado foram uma participação muito especial na morte redentora do Filho …'),
  (7, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 8ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que fez Jesus Cristo sobre a cruz? — Jesus Cristo sobre a cruz rezou pelos seus inimigos; deu por mãe ao discípulo São João e, na pessoa dele, a todos nós, a sua própria Mãe, Maria Santíssima; ofereceu a sua morte em sacrifício e satisfez à justiça de Deus pelos pecados dos homens.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 5;

-- sorrowful-5 · Jo 19, 28-30
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Depois, sabendo Jesus que tudo estava consumado, para se cumprir a Escritura, disse: Tenho sede. Tinha sido ali posto um vaso cheio de vinagre. Então (os soldados), ensopando no vinagre uma esponja, e atando-a a um hissopo, chegaram-lha à boca. E Jesus, tendo tomado o vinagre, disse: Tudo está consumado. E, inclinando a cabeça, rendeu o espírito.', 'Jo 19, 28-30', 2
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 119, 6 (sobre Jo 19, 30), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 9; tradução a partir do latim (texto abreviado)', 'Depois, como nada restava que fosse preciso fazer antes de morrer, inclinando a cabeça, rendeu o espírito, cumpridas todas as coisas por cujo cumprimento esperava, como quem tinha o poder de dar a sua vida e de novo retomá-la. … Quem dorme quando quer, como Jesus morreu quando quis? Quanto se há de esperar ou temer o poder do que há de julgar, se tão grande se mostrou o poder do que morria?'),
  (1, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 119, 4 (sobre Jo 19, 28-29), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 9; tradução a partir do latim (texto abreviado)', 'Padecia tudo isto Aquele que aparecia homem, e dispunha tudo isto Ele mesmo, que se ocultava Deus. … O hissopo, em volta do qual puseram a esponja cheia de vinagre, por ser erva humilde e que purifica o peito, entendemo-lo com razão como a humildade de Cristo: … pela humildade de Cristo somos purificados.'),
  (2, 'São Tomás de Aquino', 'Comentário ao Evangelho de São João, cap. 19, lição 5, n. 2451 (sobre Jo 19, 30); tradução a partir do latim', 'Põe-se a consumação final quando diz: Tendo tomado o vinagre, disse: Tudo está consumado. O que se pode referir à consumação da morte — «convinha que o autor da salvação deles fosse consumado pela paixão» (Hb 2, 10) —; ou à consumação da santificação, que se realiza pela sua paixão e cruz — «com uma só oblação tornou perfeitos para sempre os que são santificados» (Hb 10, 14) —; ou à consumação das Escrituras — «será consumado tudo o que foi escrito pelos profetas acerca do Filho do homem» (Lc 18, 31).'),
  (3, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São João, homilia 85 (sobre Jo 19, 30), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 9; tradução a partir do latim', 'Não inclinou a cabeça porque expirou; mas, porque inclinou a cabeça, então expirou. Por tudo isto mostrou o Evangelista que Ele mesmo era o Senhor de todas as coisas.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 607', 'Este desejo de fazer seu o plano do amor de redenção do seu Pai, anima toda a vida de Jesus. A sua paixão redentora é a razão de ser da Encarnação: «Pai, salva-Me desta hora! Mas por causa disto, é que Eu cheguei a esta hora» (Jo 12, 27). «O cálice que o Pai Me deu, não havia de bebê-lo?» (Jo 18, 11). E ainda na cruz, antes de «tudo estar consumado» (Jo 19, 30), diz: «Tenho sede» (Jo 19, 28).'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 16ª pergunta do capítulo. Tradução a partir do italiano.', '«— Na morte de Jesus Cristo a divindade separou-se do corpo e da alma? — Na morte de Jesus Cristo a divindade não se separou nem do corpo nem da alma, mas somente a alma se separou do corpo.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 5;

-- sorrowful-5 · Jo 19, 33-34
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Mas, quando chegaram a Jesus, tendo visto que já estava morto, não lhe quebraram as pernas; mas um dos soldados abriu-lhe um lado com uma lança, e imediatamente saiu sangue e água.', 'Jo 19, 33-34', 3
from public.mysteries m where m.type = 'sorrowful' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, tratado 120, 2 (sobre Jo 19, 34), no texto recolhido por S. Tomás na Catena Aurea in Jo 19, lição 10; tradução a partir do latim (texto abreviado)', 'Com palavra vigilante usou o Evangelista: não disse «feriu-lhe o lado» ou «chagou-o», mas «abriu», para que ali, de certo modo, se franqueasse a porta da vida, donde manaram os sacramentos da Igreja, sem os quais não se entra na vida que é verdadeiramente vida. Aquele sangue foi derramado para remissão dos pecados; aquela água tempera o cálice da salvação: dá o banho e a bebida. … Este segundo Adão, inclinada a cabeça, adormeceu na cruz, para que dali Lhe fosse formada a esposa, por aquilo que manou do lado do que dormia. Ó morte, pela qual os mortos revivem! Que há mais puro que este sangue? Que há mais salutar que esta ferida?'),
  (1, 'São João Crisóstomo', 'Homilias sobre o Evangelho de São João, hom. 85 (Jo 19, 34) (texto abreviado)', 'Eis que saíram água e sangue. Não por acaso brotaram estas fontes, mas porque por estes dois juntos consiste a Igreja. … regenerados pela água e nutridos pelo Sangue e pela Carne. Daí têm origem os Mistérios; para que, quando te aproximares daquele cálice, te aproximes como bebendo do próprio lado.'),
  (2, 'Pio XII', 'Encíclica Haurietis aquas (15 de maio de 1956), n. 39 (texto abreviado)', '… Do coração ferido do Redentor nasceu a Igreja, verdadeira administradora do sangue da redenção, e do mesmo coração flui abundantemente a graça dos sacramentos, na qual os filhos da Igreja bebem a vida sobrenatural … O que aqui se afirma do lado de Cristo, ferido e aberto pelo soldado, cumpre aplicá-lo ao seu coração … Por isso, durante o curso dos séculos, a ferida do coração sacratíssimo de Jesus … tem sido a imagem viva daquele amor espontâneo com que Deus entregou seu Unigênito pela redenção dos homens, e com o qual Cristo nos amou a todos tão ardentemente que a si mesmo se imolou como hóstia cruenta no Calvário.'),
  (3, 'São Tomás de Aquino', 'Comentário ao Evangelho de São João, cap. 19, lição 5, n. 2459 (sobre Jo 19, 34); tradução a partir do latim (texto abreviado)', 'Isto se fez também para mostrar que pela paixão de Cristo alcançamos plena purificação, a saber, dos pecados e das manchas. Dos pecados, pelo sangue, que é o preço da nossa redenção … das manchas, pela água, que é o banho da nossa regeneração … E por isso estas duas coisas pertencem especialmente a dois sacramentos: a água, ao sacramento do Batismo; o sangue, à Eucaristia.'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. V «Do quarto artigo», 19ª pergunta do capítulo. Tradução a partir do italiano.', '«— Para sermos salvos basta que Jesus Cristo tenha morrido por nós? — Para sermos salvos não basta que Jesus Cristo tenha morrido por nós, mas é necessário que sejam aplicados a cada um de nós o fruto e os méritos da sua paixão e morte, o que se faz sobretudo por meio dos sacramentos instituídos para este fim pelo mesmo Jesus Cristo; e, como muitos ou não recebem os sacramentos ou não os recebem bem, por isso tornam inútil para si mesmos a morte de Jesus Cristo.»')
) as v(sort_order, author, source, text) on true
where m.type = 'sorrowful' and m.sort_order = 5;

-- glorious-1 · Mt 28, 5-8
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Mas o anjo, tomando a palavra, disse às mulheres: «Vós não temais, porque sei que procurais a Jesus, que foi crucificado; ele já aqui não está, porque ressuscitou, como tinha dito; vinde e vede o lugar, onde o Senhor estava depositado. Ide já dizer aos seus discípulos que ele ressuscitou; e eis que vai adiante de vós para a Galileia; lá o vereis; eis que eu vo-lo disse antes.» Saíram logo do sepulcro com medo e grande gáudio, e foram correndo dar a nova aos discípulos.', 'Mt 28, 5-8', 0
from public.mysteries m where m.type = 'glorious' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'São Gregório Magno', 'Homilias sobre os Evangelhos, livro II, homilia 21 (dia de Páscoa, sobre Mc 16, 1-7), n. 3 (texto abreviado). Tradução a partir do latim (ed. maurina, PL 76); Gregório comenta o «Não vos assusteis» de Marcos, paralelo do «Vós não temais» de Mateus', '«Não vos assusteis.» Como se dissesse claramente: Temam aqueles que não amam a vinda dos cidadãos do céu; tenham pavor os que, oprimidos pelos desejos carnais, desesperam de poder chegar à sua companhia. Vós, porém, por que temeis, vós que vedes os vossos concidadãos? … Porque Deus onipotente é terrível para os pecadores e suave para os justos, com razão o anjo, testemunha da sua ressurreição, se mostra com o rosto como relâmpago e com a veste branca como a neve, para que pelo seu próprio aspecto aterrasse os réprobos e acariciasse os piedosos.'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. VI «Do quinto artigo», 5ª pergunta do capítulo. Tradução a partir do italiano.', '«— A ressurreição de Jesus Cristo foi semelhante à ressurreição dos outros homens ressuscitados? — Não; a ressurreição de Jesus Cristo não foi semelhante à ressurreição dos outros homens ressuscitados, porque Jesus Cristo ressuscitou por virtude própria, e os outros foram ressuscitados por virtude de Deus.»'),
  (2, 'Catecismo Romano', 'Catecismo Romano (do Concílio de Trento), I parte, cap. VI (Quinto artigo), n. 10 (texto abreviado). Trad. Frei Leopoldo Pires Martins, OFM, Vozes, Petrópolis, 1951', 'Para dar prova de Sua Divindade, não quis retardar a ressurreição até o fim do mundo. De outro lado, para crermos que era homem de verdade, e que realmente tinha morrido, não ressuscitou logo depois da morte, mas [esperou até] ao terceiro dia. Este intervalo [Lhe] pareceu suficiente para demonstrar a realidade de Sua Morte.'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 53, a. 1 (texto abreviado). Tradução a partir do latim (ed. Leonina)', 'Foi necessário que Cristo ressuscitasse por cinco razões. Primeiro, para recomendação da justiça divina, à qual pertence exaltar os que se humilham por Deus … Porque, pois, Cristo, por caridade e obediência a Deus, se humilhou até a morte de cruz, era preciso que fosse exaltado por Deus até a ressurreição gloriosa. … Terceiro, para levantar a nossa esperança: porque, vendo ressurgir Cristo, que é a nossa cabeça, esperamos que também nós ressurgiremos. … Quinto, para completar a nossa salvação: porque, assim como suportou males morrendo para nos livrar dos males, assim foi glorificado ressurgindo para nos promover aos bens.'),
  (4, 'São Gregório Magno', 'Homilias sobre os Evangelhos, livro II, homilia 21 (dia de Páscoa, sobre Mc 16, 1-7), n. 7 (texto abreviado). Tradução a partir do latim (ed. maurina, PL 76)', 'Se então descesse da cruz, cedendo aos que o insultavam, não nos mostraria a virtude da paciência. Mas esperou um pouco, tolerou os opróbrios, suportou as zombarias, guardou a paciência, adiou a admiração; e aquele que não quis descer da cruz ressurgiu do sepulcro. Mais foi, pois, ressurgir do sepulcro do que descer da cruz; mais foi destruir a morte ressuscitando do que conservar a vida descendo.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 1;

-- glorious-1 · Mt 28, 9-10
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E eis que Jesus lhes saiu ao encontro, dizendo: «Deus vos salve.» E elas aproximaram-se dele e abraçaram os seus pés, e o adoraram. Então disse-lhes Jesus: «Não temais; ide, avisai meus irmãos, para que vão à Galileia, lá me verão.»', 'Mt 28, 9-10', 1
from public.mysteries m where m.type = 'glorious' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte I, cap. VIII «Da Páscoa da Ressurreição», 6ª e 7ª perguntas do capítulo. Tradução a partir do italiano.', '«— Que devemos fazer para celebrar dignamente a festa da Páscoa? — Para celebrar dignamente a festa da Páscoa devemos fazer duas coisas: 1.º adorar com santa alegria e viva gratidão a Jesus Cristo ressuscitado; 2.º ressuscitar espiritualmente com ele. — Que quer dizer ressuscitar espiritualmente com Jesus Cristo? — Quer dizer que, assim como Jesus Cristo, por meio da sua ressurreição, começou uma vida nova, imortal e celeste, assim também nós devemos começar uma vida nova segundo o espírito, renunciando inteiramente e para sempre ao pecado e a tudo o que nos leva ao pecado; amando só a Deus, e tudo o que nos leva a Deus.»'),
  (1, 'São Tomás de Aquino', 'Suma Teológica, III, q. 55, a. 1, ad 3 (texto abreviado). Tradução a partir do latim (ed. Leonina)', 'Apareceu primeiro às mulheres para que a mulher, que primeiro levara ao homem o princípio da morte, também primeiro anunciasse os princípios da ressurreição de Cristo na glória. … Mostra-se também por isso que, quanto ao estado de glória, o sexo feminino não sofrerá detrimento algum; antes, se as mulheres arderem em maior caridade, alcançarão também maior glória na visão divina: porque as mulheres que amaram mais estreitamente o Senhor, a ponto de não se afastarem do seu sepulcro mesmo quando os discípulos se afastavam, foram as primeiras a ver o Senhor ressurgindo na glória.'),
  (2, 'Santo Afonso Maria de Ligório', 'Meditações para todos os dias e festas do ano, t. II, Semana da Páscoa, Domingo («A ressurreição de Jesus Cristo e a esperança do cristão»), ponto I (texto abreviado). Trad. port. publicada (Herder)', 'Façamos um ato de fé viva na sua ressurreição, e cheguemo-nos a Ele para beijarmos em espírito os sinais de suas cinco chagas glorificadas. Alegremo-nos com Ele, por ter saído do sepulcro, vencedor da morte e do inferno, e digamos com todos os santos: “O Cordeiro que foi imolado por nós, é digno de receber o poder, a divindade, a sabedoria, a fortaleza, a honra, a glória e a bênção.”'),
  (3, 'Santo Afonso Maria de Ligório', 'Meditações para todos os dias e festas do ano, t. II, Semana da Páscoa, Sábado («Aparição de Jesus ressuscitado a sua Mãe Maria Santíssima»), ponto I (texto abreviado). Trad. port. publicada (Herder). O próprio autor nota que os Evangelistas não a referem: é piedosa tradição', 'Era de inteira justiça que o divino Redentor glorificado fosse, antes de mais ninguém, visitar a Santíssima Virgem; a fim de que, antes dos outros e mais do que estes, participasse da alegria da ressurreição quem mais do que os outros participara da paixão. … Avizinhemo-nos, em espírito, de Nossa Senhora, que é também nossa Mãe, e roguemos-lhe que nos permita beijar as chagas glorificadas de Jesus Cristo.'),
  (4, 'São João Paulo II', 'Rosarium Virginis Mariae, § 23 (texto abreviado)', '«A contemplação do rosto de Cristo não pode deter-se na imagem do crucificado. Ele é o Ressuscitado!» O Rosário sempre expressou esta certeza da fé, convidando o crente a ultrapassar as trevas da Paixão, para fixar o olhar na glória de Cristo … Contemplando o Ressuscitado, o cristão descobre novamente as razões da própria fé (cf. 1 Cor 15, 14), e revive não só a alegria daqueles a quem Cristo Se manifestou – os Apóstolos, a Madalena, os discípulos de Emaús –, mas também a alegria de Maria, que deverá ter tido uma experiência não menos intensa da nova existência do Filho glorificado.'),
  (5, 'São Gregório Magno', 'Homilias sobre os Evangelhos, livro II, homilia 21 (dia de Páscoa, sobre Mc 16, 1-7), n. 5 (texto abreviado). Tradução a partir do latim (ed. maurina, PL 76); comenta «irá adiante de vós para a Galileia; lá o vereis» (Mc 16, 7; cf. Mt 28, 7.10)', 'Galileia, com efeito, interpreta-se «passagem realizada». O nosso Redentor já tinha passado da paixão à ressurreição, da morte à vida, da pena à glória, da corrupção à incorrupção. E depois da ressurreição é visto primeiro pelos discípulos na Galileia, porque a glória da sua ressurreição só a veremos depois, cheios de alegria, se agora passarmos dos vícios às alturas das virtudes.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 1;

-- glorious-1 · 1 Co 15, 14-22
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, se Cristo não ressuscitou, é pois vã a nossa pregação, é também vã a vossa fé; … Mas Cristo ressuscitou dos mortos, sendo ele as primícias dos que dormem; porque, assim como a morte (veio) por um homem, também por um homem (veio) a ressurreição dos mortos. E, assim como todos morreram em Adão, assim também todos serão vivificados em Cristo.', '1 Co 15, 14-22', 2
from public.mysteries m where m.type = 'glorious' and m.sort_order = 1;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 651', '«Se Cristo não ressuscitou, então a nossa pregação é vã e também é vã a vossa fé» (1 Cor 15, 14). A ressurreição constitui, antes de mais, a confirmação de tudo quanto Cristo em pessoa fez e ensinou. Todas as verdades, mesmo as mais inacessíveis ao espírito humano, encontram a sua justificação se, ressuscitando, Cristo deu a prova definitiva, que tinha prometido, da sua autoridade divina.'),
  (1, 'Catecismo Romano', 'Catecismo Romano (do Concílio de Trento), I parte, cap. VI (Quinto artigo), n. 11 (texto abreviado). Trad. Frei Leopoldo Pires Martins, OFM, Vozes, Petrópolis, 1951, que cita S. Agostinho, Enarrationes in Psalmos, 120 (grafia atualizada: «creem»)', 'Cheio de admiração pela verdade deste Artigo, Santo Agostinho escreveu: «Que muito crermos que Cristo morreu? Também os pagãos, os judeus, e todos os maus o acreditam. Todos creem que morreu. A fé [característica] dos cristãos é a Ressurreição de Cristo. O que muito importa é crermos que ressuscitou».'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte I, cap. VIII «Da Páscoa da Ressurreição», 4ª pergunta do capítulo. Tradução a partir do italiano.', '«— Por que se diz que a Ressurreição de Cristo é o fundamento da nossa religião? — A Ressurreição de Cristo diz-se o fundamento da nossa religião, porque nos foi dada pelo próprio Jesus Cristo como prova principal da sua divindade e da verdade da nossa fé.»'),
  (3, 'São Gregório Magno', 'Homilias sobre os Evangelhos, livro II, homilia 21 (dia de Páscoa, sobre Mc 16, 1-7), n. 6 (texto abreviado). Tradução a partir do latim (ed. maurina, PL 76)', 'Havia duas vidas: uma conhecíamos, a outra ignorávamos. Uma é mortal, a outra imortal; uma de corrupção, a outra de incorrupção; uma de morte, a outra de ressurreição. Mas veio o Mediador entre Deus e os homens, o homem Cristo Jesus: assumiu uma e mostrou a outra. Suportou uma morrendo, e mostrou a outra ressuscitando. … Se, pois, somos membros do nosso Redentor, esperemos confiadamente em nós o que sabemos realizado na Cabeça.'),
  (4, 'São Tomás de Aquino', 'Suma Teológica, III, q. 56, a. 1 (texto abreviado). Tradução a partir do latim (ed. Leonina)', 'O que é primeiro em qualquer gênero é causa de tudo o que vem depois. Ora, o primeiro no gênero da nossa ressurreição foi a ressurreição de Cristo … Por isso é necessário que a ressurreição de Cristo seja causa da nossa ressurreição. … O princípio da vivificação humana é o Verbo de Deus, de quem se diz no Salmo: «Em ti está a fonte da vida». … Ora, toda causa opera primeiro naquilo que lhe está mais próximo e, por meio disso, nas coisas mais remotas, como o fogo aquece primeiro o ar próximo, por meio do qual aquece os corpos distantes. … Por isso o Verbo de Deus dá primeiro a vida imortal ao corpo que lhe está naturalmente unido, e por meio dele opera a ressurreição em todos os outros.'),
  (5, 'Catecismo da Igreja Católica', 'CIC 655 (texto abreviado)', 'Finalmente, a ressurreição de Cristo – e o próprio Cristo Ressuscitado – é princípio e fonte da nossa ressurreição futura: «Cristo ressuscitou dos mortos como primícias dos que morreram [...]. Do mesmo modo que em Adão todos morreram, assim também em Cristo serão todos restituídos à vida» (1 Cor 15, 20-22). … «para que os vivos deixem de viver para si próprios, mas vivam para Aquele que morreu e ressuscitou por eles» (2 Cor 5, 15).'),
  (6, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. XII «Do undécimo artigo», 5ª pergunta do capítulo. Tradução a partir do italiano.', '«— Os homens ressuscitarão todos da mesma maneira? — Não; haverá grandíssima diferença entre os corpos dos eleitos e os corpos dos condenados, porque só os corpos dos eleitos terão, à semelhança de Jesus Cristo ressuscitado, os dotes dos corpos gloriosos.»'),
  (7, 'Santo Afonso Maria de Ligório', 'Meditações para todos os dias e festas do ano, t. II, Semana da Páscoa, Domingo («A ressurreição de Jesus Cristo e a esperança do cristão»), ponto II (texto abreviado). Trad. port. publicada (Herder)', 'Regozijemo-nos com Jesus Cristo; mas regozijemo-nos também por nós mesmos, porquanto a sua ressurreição é o penhor e a norma da nossa … Ó doce esperança! «Virá a hora em que os mortos ouvirão a voz do Filho de Deus»; e então pelo poder divino retomaremos o mesmo corpo que agora temos, mas formoso e resplandecente como o sol. Nós também ressuscitaremos!')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 1;

-- glorious-2 · At 1, 9-11
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, tendo dito isto, elevou-se à vista deles; e uma nuvem o ocultou aos seus olhos. E, como estivessem olhando para o céu, quando ele ia subindo, eis que se apresentaram junto deles dois personagens vestidos de branco, os quais lhes disseram: Homens da Galileia, por que estais (aí parados) olhando para o céu? Esse Jesus que, separando-se de vós, foi arrebatado ao céu, virá do mesmo modo que o vistes ir para o céu.', 'At 1, 9-11', 0
from public.mysteries m where m.type = 'glorious' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Santo Agostinho', 'Sermão 263 (Sobre a Ascensão do Senhor, III), 2, PL 38 (texto abreviado; tradução a partir do latim)', 'Hoje, como ouvistes, irmãos, Nosso Senhor Jesus Cristo subiu ao céu: suba com Ele também o nosso coração. … Assim como Ele subiu e não se afastou de nós, assim também nós já estamos lá com Ele, embora ainda não se tenha realizado em nosso corpo o que nos é prometido. … Aquele que desceu do céu não nos tem inveja do céu, mas de certo modo clama: «Sede meus membros, se quereis subir ao céu». … Meditemos na terra aquilo em que somos contados no céu. … Facilmente o corpo será levado às alturas dos céus, se o fardo dos pecados não oprimir o espírito.'),
  (1, 'São Gregório Magno', 'Homilias sobre os Evangelhos, II, hom. 29, 9 (texto abreviado; tradução a partir do latim)', 'Por que, ao nascer o Senhor, apareceram anjos, e não se lê que tenham aparecido em vestes brancas, mas, ao subir o Senhor, os anjos enviados aparecem em vestes brancas? … Nas vestes brancas manifesta-se o gozo e a solenidade da alma. … Ao nascer o Senhor, parecia humilhada a divindade; ao subir o Senhor, foi exaltada a humanidade. … Aquele que no seu nascimento apareceu como Deus humilde, na sua Ascensão mostrou-se homem sublime.'),
  (2, 'São Leão Magno', 'Sermão 74 (Sobre a Ascensão do Senhor, II), 2 (texto abreviado; tradução a partir do latim)', 'Nosso Senhor Jesus Cristo, no quadragésimo dia depois da ressurreição, elevado ao céu diante dos discípulos, pôs termo à sua presença corporal, para permanecer à direita do Pai até que se completem os tempos divinamente estabelecidos para multiplicar os filhos da Igreja. … Assim, o que era visível do nosso Redentor passou para os sacramentos; e, para que a fé fosse mais excelente e mais firme, à visão sucedeu a doutrina, cuja autoridade seguissem os corações dos fiéis, iluminados pelos raios do alto.'),
  (3, 'São Leão Magno', 'Sermão 74 (Sobre a Ascensão do Senhor, II), 4 (texto abreviado; tradução a partir do latim)', 'Enquanto os olhos dos discípulos, com atenta admiração, seguiam o Senhor que subia aos céus, apresentaram-se diante deles dois anjos, resplandecentes pela admirável alvura das vestes. … Por estas palavras, todos os filhos da Igreja eram ensinados a crer que Jesus Cristo há de vir, visível, na mesma carne com que subiu. … Assim como o anjo anunciou à bem-aventurada Virgem que Cristo seria concebido do Espírito Santo, … assim também o ministério dos anjos anunciou que Ele há de vir na mesma carne para julgar o mundo.'),
  (4, 'São João Crisóstomo', 'Homilias sobre os Atos dos Apóstolos, hom. 2 (texto abreviado; tradução a partir da versão inglesa da coleção Nicene and Post-Nicene Fathers, I, 11)', 'Por que uma nuvem o recebeu? Também isto era sinal certo de que subia ao céu. Não fogo, como no caso de Elias, nem carro de fogo, mas uma nuvem o recebeu, que era símbolo do céu. … Pois, assim como um rei se dá a conhecer pelo carro real, assim foi enviado para Ele o carro real. … Oh, que espetáculo lhes foi concedido!'),
  (5, 'Catecismo da Igreja Católica', 'CIC 661 (texto abreviado; grafia adaptada ao Brasil)', 'Esta última etapa continua intimamente unida à primeira, isto é, à descida do céu realizada na Encarnação. Só Aquele que «saiu do Pai» pode «voltar para o Pai»: Cristo. «Ninguém subiu ao céu senão Aquele que desceu do céu: o Filho do Homem» (Jo 3, 13). Abandonada às suas forças naturais, a humanidade não tem acesso à «Casa do Pai», à vida e à felicidade de Deus. Só Cristo pôde abrir ao homem este acesso: «subindo aos céus, como nossa cabeça e primogênito, deu-nos a esperança de irmos um dia ao seu encontro, como membros do seu corpo».'),
  (6, 'Santo Afonso Maria de Ligório', 'Glórias de Maria, Parte II, Discurso VII (Da Assunção de Maria), ponto II (texto abreviado; tradução a partir do italiano)', 'Depois da ascensão de Jesus Cristo, Maria ficou na terra para atender à propagação da fé. … De boa vontade se detinha ela na terra, entendendo ser esta a vontade de Deus para bem da Igreja; mas não podia deixar de sentir a pena de ver-se longe da presença e da vista do seu dileto Filho, que subira ao céu. «Onde está o vosso tesouro, ali estará também o vosso coração», disse o Redentor. … Se, pois, Maria não amava outro bem senão Jesus, estando Ele no céu, ao céu iam todos os seus desejos.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 2;

-- glorious-2 · Lc 24, 50-53
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Depois levou-os fora até (cerca de) Betânia; e levantando as suas mãos, os abençoou. E aconteceu que enquanto os abençoava, separou-se deles, e elevava-se ao céu. E eles, depois de o adorarem, voltaram para Jerusalém com grande júbilo; e estavam continuamente no templo, louvando e bendizendo a Deus. Amém.', 'Lc 24, 50-53', 1
from public.mysteries m where m.type = 'glorious' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Beda, o Venerável', 'Exposição sobre o Evangelho de São Lucas, VI, in Lc 24, 50 (citado por S. Tomás na Catena Aurea, in Lc 24, lição 7; texto abreviado; tradução a partir do latim)', 'Levou-os para fora, até Betânia: primeiro, por causa do nome da cidade, que significa «casa da obediência»; pois Aquele que desceu por causa da desobediência dos pervertidos, sobe por causa da obediência dos convertidos. Depois, por causa da situação dessa aldeia, que se diz estar na encosta do monte das Oliveiras: porque a casa da Igreja obediente assentou os fundamentos da sua fé, esperança e caridade na encosta do monte supremo, isto é, de Cristo. E abençoa aqueles a quem tinha confiado os preceitos do ensino.'),
  (1, 'São Leão Magno', 'Sermão 73 (Sobre a Ascensão do Senhor, I), 4 (texto abreviado; tradução a partir do latim)', 'Os bem-aventurados Apóstolos … ficaram tão fortalecidos pela evidência da verdade que, ao subir o Senhor às alturas dos céus, não só não foram tomados de nenhuma tristeza, mas até se encheram de grande alegria. E, na verdade, grande e inefável era a causa de alegrar-se, quando, à vista da santa multidão, a natureza humana subia acima da dignidade de todas as criaturas celestes … Porque a ascensão de Cristo é a nossa elevação, e para onde precedeu a glória da Cabeça, para lá é chamada também a esperança do Corpo.'),
  (2, 'São Beda, o Venerável', 'Exposição sobre o Evangelho de São Lucas, VI, in Lc 24, 52-53 (citado por S. Tomás na Catena Aurea, in Lc 24, lição 7; texto abreviado; tradução a partir do latim)', 'Subindo o Senhor ao céu, os discípulos, depois de adorá-lo no lugar onde por último pousaram os seus pés, voltam logo para Jerusalém, onde lhes fora mandado esperar a promessa do Pai. … Grandes alegrias experimentam, porque se alegram de que o seu Deus e Senhor, depois do triunfo da ressurreição, penetrou também os céus. … E [Lucas] concluiu o seu Evangelho com os Apóstolos, ministros do novo sacerdócio, não no sangue das vítimas, mas no louvor de Deus e na bênção, para que, no lugar da oração e entre as devoções do louvor, esperassem com corações preparados a vinda prometida do Espírito Santo.'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. VII «Do sexto artigo», 1ª pergunta do capítulo. Tradução a partir do italiano.', '— Que nos ensina o sexto artigo: Subiu aos céus, está sentado à direita de Deus Pai todo-poderoso? — O sexto artigo do Credo nos ensina que Jesus Cristo, quarenta dias depois da sua ressurreição, na presença de seus discípulos, subiu ao céu por si mesmo; e que, sendo, como Deus, igual ao Pai na glória, como homem foi elevado acima de todos os Anjos e de todos os Santos, e constituído Senhor de todas as coisas.'),
  (4, 'Catecismo Romano', 'Catecismo Romano (do Concílio de Trento), Parte I, cap. 7 (Sexto artigo do Símbolo), n. 5, trad. Frei Leopoldo Pires Martins, O.F.M., Vozes, 1951 (texto abreviado)', 'Pela Ascensão, Nosso Senhor queria que, subindo Ele aos céus, continuássemos nós a segui-Lo com saudosos pensamentos. … Pela Sua Ascensão também nos ensina e educa a erguermos nossa mente ao céu, enquanto vivemos ainda aqui na terra; a reconhecermos que, na terra, somos hóspedes e peregrinos à procura da [verdadeira] pátria, concidadãos dos Santos e membros da família de Deus, pois como diz o mesmo Apóstolo: «Nosso viver é no céu».'),
  (5, 'São Gregório Magno', 'Homilias sobre os Evangelhos, II, hom. 29, 11 (texto abreviado; tradução a partir do latim)', 'Por isso, irmãos caríssimos, convém que o sigamos com o coração para lá onde cremos que Ele subiu com o corpo. Fujamos dos desejos terrenos; nada nos deleite já nas coisas de baixo, a nós que temos um Pai nos céus. … Ainda que o ânimo flutue entre as perturbações das coisas, fixai já a âncora da vossa esperança na pátria eterna. … Eis que ouvimos que o Senhor subiu ao céu: guardemos, pois, na meditação o que cremos. E, se aqui ainda somos retidos pela fraqueza do corpo, sigamo-lo, todavia, com os passos do amor. Não abandona o nosso desejo Aquele mesmo que o deu.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 2;

-- glorious-2 · Mc 16, 19
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E o Senhor Jesus, depois que (assim) lhes falou, elevou-se ao céu, e está sentado à direita de Deus.', 'Mc 16, 19', 2
from public.mysteries m where m.type = 'glorious' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. VII «Do sexto artigo», 5ª pergunta do capítulo. Tradução a partir do italiano.', '— Explicai-me as palavras: está sentado à direita de Deus Pai todo-poderoso. — A palavra «está sentado» significa a pacífica posse que Jesus Cristo tem da sua glória; e as palavras «à direita de Deus Pai todo-poderoso» exprimem que Ele tem o lugar de honra acima de todas as criaturas.'),
  (1, 'São Gregório Magno', 'Homilias sobre os Evangelhos, II, hom. 29, 7 (texto abreviado; tradução a partir do latim)', 'Que significa que Marcos o descreve sentado, e Estêvão atesta tê-lo visto de pé? Sabeis, irmãos, que estar sentado é próprio de quem julga; estar de pé, de quem combate ou socorre. Porque o nosso Redentor, elevado ao céu, agora julga todas as coisas e no fim virá como Juiz de todos, Marcos o descreve sentado depois da sua assunção. … Estêvão, porém, posto no trabalho do combate, viu de pé Aquele que teve por auxiliador: porque, para que ele vencesse na terra a incredulidade dos perseguidores, por ele combateu do céu a graça de Cristo.'),
  (2, 'Santo Agostinho', 'Sermão sobre o Símbolo aos catecúmenos (De Symbolo ad catechumenos), n. 11 (texto abreviado; tradução a partir do latim)', 'Subiu ao céu: crede. Está sentado à direita do Pai: crede. Por «estar sentado» entendei habitar. … Crede, pois, que Cristo habita à direita de Deus Pai: lá está. E não vos diga o vosso coração: «Que faz Ele?». Não queirais buscar o que não é lícito achar: lá está; isto vos basta. É bem-aventurado, e «direita do Pai» é o nome dessa mesma bem-aventurança. … Ali tudo é direita, porque ali não há miséria alguma.'),
  (3, 'São Tomás de Aquino', 'Suma Teológica, III, q. 57, a. 6, resp. (texto abreviado; tradução a partir do latim)', 'Assim como o pontífice, no Antigo Testamento, entrava no santuário para assistir diante de Deus em favor do povo, assim também Cristo entrou no céu «para interceder por nós» (Hb 7, 25). Pois a própria apresentação de si mesmo na natureza humana que levou ao céu é uma intercessão por nós: para que, tendo Deus exaltado assim a natureza humana em Cristo, se compadeça também daqueles por quem o Filho de Deus assumiu a natureza humana. … E, estabelecido no trono dos céus como Deus e Senhor, de lá envia aos homens os dons divinos.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 662 (texto abreviado; grafia adaptada ao Brasil)', '«E Eu, uma vez elevado da terra, atrairei todos a Mim» (Jo 12, 32). A elevação na cruz significa e anuncia a elevação da ascensão aos céus. … Nos céus, Cristo exerce permanentemente o seu sacerdócio, «sempre vivo para interceder a favor daqueles que, por seu intermédio, se aproximam de Deus» (Hb 7, 25).'),
  (5, 'Catecismo Romano', 'Catecismo Romano (do Concílio de Trento), Parte I, cap. 7 (Sexto artigo do Símbolo), n. 6, trad. Frei Leopoldo Pires Martins, O.F.M., Vozes, 1951 (texto abreviado)', 'Pela doutrina do Apóstolo, [Cristo] também subiu aos céus «para Se apresentar agora ante a face de Deus em favor nosso», e exercer perante o Pai o ofício de advogado. … Nada pode inspirar aos fiéis maior alegria e felicidade do que verem a Jesus Cristo feito patrono de nossa causa e intercessor pela nossa salvação, Ele que goza junto ao Eterno Pai de suma influência e autoridade.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 2;

-- glorious-2 · Jo 14, 2-3
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Na casa de meu Pai há muitas moradas. Se assim não fosse, eu vo-lo teria dito. Vou preparar o lugar para vós. E, depois que eu tiver ido e vos tiver preparado o lugar, virei novamente (quando morrerdes), e tomar-vos-ei comigo, para que, onde eu estou, estejais vós também.', 'Jo 14, 2-3', 3
from public.mysteries m where m.type = 'glorious' and m.sort_order = 2;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'Santo Agostinho', 'Tratados sobre o Evangelho de São João, 68, 3 (texto abreviado; tradução a partir do latim)', 'Vá, pois, o Senhor e prepare o lugar; vá, para que não seja visto; oculte-se, para que seja crido. Pois o lugar se prepara quando se vive da fé. Seja desejado Aquele em quem se crê, para que, desejado, seja possuído: o desejo do amor é a preparação da morada. Assim, Senhor, prepara o que preparas: pois Tu nos preparas para Ti e Te preparas para nós, quando preparas o lugar, tanto para Ti em nós como para nós em Ti.'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte I, cap. VII «Do sexto artigo», 3ª pergunta do capítulo. Tradução a partir do italiano.', '— Por que Jesus Cristo subiu ao céu? — Jesus Cristo subiu ao céu: 1.º para tomar posse do seu reino, merecido com a sua morte; 2.º para preparar o nosso lugar na glória e para ser nosso Mediador e Advogado junto do Pai; 3.º para enviar o Espírito Santo aos seus Apóstolos.'),
  (2, 'São Tomás de Aquino', 'Suma Teológica, III, q. 57, a. 1, ad 3 (texto abreviado; tradução a partir do latim)', 'A ascensão de Cristo ao céu, pela qual nos subtraiu a sua presença corporal, foi-nos mais útil do que teria sido a presença corporal. … Em segundo lugar, para elevar a esperança; por isso Ele mesmo diz: «Se eu for e vos preparar o lugar, virei de novo e vos tomarei comigo, para que, onde eu estou, estejais vós também». Pois, colocando no céu a natureza humana que assumiu, Cristo nos deu a esperança de chegar até lá. … Em terceiro lugar, para erguer às coisas celestes o afeto da caridade; … porque, «onde está o teu tesouro, aí está também o teu coração».'),
  (3, 'Catecismo Romano', 'Catecismo Romano (do Concílio de Trento), Parte I, cap. 7 (Sexto artigo do Símbolo), n. 6-7, trad. Frei Leopoldo Pires Martins, O.F.M., Vozes, 1951 (texto abreviado)', 'Afinal, preparou-nos um lugar, conforme o havia prometido. Foi em nome de todos nós que Jesus Cristo, como nosso Chefe, entrou na posse da glória celeste. Com Sua ida para o céu, abriu as portas que se tinham fechado em consequência do pecado de Adão. … Crendo que Cristo subiu aos céus enquanto Homem, e colocou [Sua] natureza humana à direita de Deus Padre, grande é a nossa esperança de que também nós para lá havemos de subir, como membros Seus, e de unir-nos [a Ele] como nossa cabeça.'),
  (4, 'Dom Columba Marmion', 'Le Christ dans ses mystères (Cristo nos seus mistérios), cap. XVI (A Ascensão), IV (tradução a partir do francês)', '«Subo para meu Pai e vosso Pai, para meu Deus e vosso Deus.» Jesus não faz mais que preceder-nos: não se separa de nós, não nos separa de si. Se entra no seu reino glorioso, é «para nos preparar ali um lugar»; promete «voltar um dia para nos tomar» e fazer-nos sentar ali, a fim, diz Ele, de que «estejamos onde Ele está». Assim, já estamos, de direito, na glória e na felicidade de Cristo Jesus; um dia estaremos nela de fato. … Que poder nesta oração e que doçura nesta promessa!'),
  (5, 'Catecismo da Igreja Católica', 'CIC 666', 'Jesus Cristo, cabeça da Igreja, precede-nos no Reino glorioso do Pai, para que nós, membros do seu corpo, vivamos na esperança de estarmos um dia eternamente com Ele.')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 2;

-- glorious-3 · At 2, 1-4
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, quando se completaram os dias do Pentecoste, estavam todos juntos no mesmo lugar; e, de repente, veio do céu um estrondo, como de vento que soprava impetuoso, e encheu toda a casa onde estavam sentados. E apareceram-lhes repartidas umas como línguas de fogo, e pousou (uma) sobre cada um deles. E foram todos cheios do Espírito Santo, e começaram a falar várias línguas, conforme o Espírito Santo lhes concedia que falassem.', 'At 2, 1-4', 0
from public.mysteries m where m.type = 'glorious' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 731', 'No dia de Pentecostes (no termo das sete semanas pascais), a Páscoa de Cristo completou-se com a efusão do Espírito Santo que Se manifestou, Se deu e Se comunicou como Pessoa divina: da sua plenitude, Cristo Senhor derrama em profusão o Espírito (109).'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte Primeira, cap. XI «Da festa de Pentecostes», 5ª pergunta do capítulo. Tradução a partir do italiano.', '— De que maneira se cumpriu no Pentecostes dos cristãos o que era figurado no dos hebreus? — O que era figurado no Pentecostes dos hebreus cumpriu-se no dos cristãos, porque o Espírito Santo desceu sobre os Apóstolos e os outros discípulos de Jesus Cristo, reunidos com Maria Virgem num mesmo lugar, e imprimiu nos seus corações a nova lei por meio do seu divino amor.'),
  (2, 'São Leão Magno', 'Sermão 75 (Sobre o Pentecostes, I), 2 (texto abreviado). Tradução a partir do latim (Sermones ad Romanam Plebem, LXXV).', 'Ó quão veloz é a palavra da sabedoria, e, onde Deus é o mestre, quão depressa se aprende o que se ensina! Não foi preciso intérprete para ouvir, nem costume para usar, nem tempo para estudar; mas, soprando o Espírito da verdade onde quis, as línguas próprias de cada nação tornaram-se comuns na boca da Igreja. Desde este dia, pois, ressoou a trombeta da pregação evangélica; desde este dia, chuvas de carismas e rios de bênçãos regaram todo o deserto e toda a terra árida.'),
  (3, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte Primeira, cap. XI «Da festa de Pentecostes», 7ª pergunta do capítulo. Tradução a partir do italiano.', '— Que efeitos produziu nos Apóstolos a descida do Espírito Santo? — O Espírito Santo, descendo sobre os Apóstolos, encheu-os de sabedoria, de fortaleza, de caridade e da abundância de todos os seus dons.'),
  (4, 'Leão XIII', 'Carta encíclica Divinum illud munus (1897), n. 7 (numeração da versão espanhola do vatican.va) (texto abreviado). Tradução a partir do latim; a citação interna é de São João Crisóstomo.', 'A Igreja, que, já concebida, nascera do próprio lado do segundo Adão, como que adormecido na cruz, manifestou-se pela primeira vez, de modo insigne, à luz dos homens no celebérrimo dia de Pentecostes. … Então, na verdade, os Apóstolos desceram do monte, como escreve Crisóstomo, «não levando nas mãos tábuas de pedra, como Moisés, mas trazendo o Espírito na mente, e derramando como que um tesouro e uma fonte de dogmas e de carismas».'),
  (5, 'São Tomás de Aquino', 'Suma Teológica, I-II, q. 106, a. 1, respondeo (texto abreviado). Tradução a partir do latim (Corpus Thomisticum).', 'O que há de principal na lei do Novo Testamento, e em que consiste toda a sua força, é a graça do Espírito Santo, que é dada pela fé em Cristo. Por isso a lei nova é principalmente a própria graça do Espírito Santo, que é dada aos fiéis de Cristo. … Assim, diz também Agostinho, no livro Do espírito e da letra, que, como a lei das obras foi escrita em tábuas de pedra, assim a lei da fé está escrita nos corações dos fiéis.'),
  (6, 'São Tomás de Aquino', 'Suma Teológica, I, q. 43, a. 7 (texto abreviado)', 'A este, enquanto procede como Amor, compete ser o dom da santificação … Por isso foi necessária a missão visível do Espírito Santo a Cristo, aos Apóstolos e aos outros primitivos santos, nos quais, de algum modo, estava fundada a Igreja. … Sob a figura de línguas de fogo ainda, para significar o dever de ensinarem; por isso, foi dito (At 2, 4) que começaram a falar em várias línguas'),
  (7, 'Catecismo da Igreja Católica', 'CIC 696 (texto abreviado; grafia adaptada ao Brasil)', '… o fogo simboliza a energia transformadora dos atos do Espírito Santo. … É sob a forma de línguas, «uma espécie de línguas de fogo», que o Espírito Santo repousa sobre os discípulos na manhã de Pentecostes e os enche de Si (31). A tradição espiritual reterá este simbolismo do fogo como um dos mais expressivos da ação do Espírito Santo (32). «Não apagueis o Espírito!» (1 Ts 5, 19).')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 3;

-- glorious-3 · At 1, 13-14
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, tendo chegado, subiram ao cenáculo, onde permaneciam (habitualmente), Pedro e João, Tiago e André, Filipe e Tomé, Bartolomeu e Mateus, Tiago, filho de Alfeu, e Simão o Zelador, e Judas, irmão de Tiago. Todos estes perseveravam unanimemente em oração, com as (piedosas) mulheres, e com Maria Mãe de Jesus, e com os irmãos dele.', 'At 1, 13-14', 1
from public.mysteries m where m.type = 'glorious' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte Primeira, cap. IX «Do oitavo artigo», 9ª pergunta do capítulo. Tradução a partir do italiano.', '— Onde estavam os Apóstolos nos dez dias antes de Pentecostes? — Os Apóstolos estavam reunidos no cenáculo em companhia de Maria Virgem e dos outros discípulos, e perseveravam na oração, esperando o Espírito Santo, que Jesus Cristo lhes havia prometido.'),
  (1, 'Catecismo da Igreja Católica', 'CIC 965', 'Depois da Ascensão do seu Filho, Maria «assistiu com suas orações aos começos da Igreja» (529). E, reunida com os Apóstolos e algumas mulheres, vemos «Maria implorando com as suas orações o dom daquele Espírito, que já na Anunciação a cobrira com a Sua sombra» (530).'),
  (2, 'Leão XIII', 'Carta encíclica Divinum illud munus (1897), n. 17 (numeração da versão espanhola do vatican.va) (texto abreviado). Tradução a partir do latim.', 'Bem sabeis quão íntimas e admiráveis são as relações que existem entre Ela e o Espírito Santo, de modo que com razão é chamada sua Esposa imaculada. A súplica da Virgem valeu, sem dúvida, muitíssimo, tanto para o mistério da Encarnação como para a vinda do mesmo Paráclito sobre o colégio dos Apóstolos.'),
  (3, 'Catecismo da Igreja Católica', 'CIC 726', 'No termo desta missão do Espírito, Maria torna-se a «Mulher», a nova Eva «mãe dos vivos», Mãe do «Cristo total» (97). É como tal que Ela está presente com os Doze, «num só coração, assíduos na oração» (Act 1, 14), no alvorecer dos «últimos tempos», que o Espírito vai inaugurar na manhã do Pentecostes, com a manifestação da Igreja.'),
  (4, 'Catecismo da Igreja Católica', 'CIC 2617 (texto abreviado)', 'A oração de Maria é-nos revelada na aurora da plenitude dos tempos. Antes da encarnação do Filho de Deus e da efusão do Espírito Santo, a sua oração coopera de um modo único com o desígnio benevolente do Pai, aquando da Anunciação para a concepção de Cristo (87) e aquando do Pentecostes para a formação da Igreja, corpo de Cristo (88). Na fé da sua humilde serva, o Dom de Deus encontra o acolhimento que Ele esperava desde o princípio dos tempos.'),
  (5, 'São João Paulo II', 'Rosarium Virginis Mariae, § 23 (texto abreviado)', 'No terceiro mistério glorioso, o Pentecostes, que mostra o rosto da Igreja como família reunida com Maria, fortalecida pela poderosa efusão do Espírito, pronta para a missão evangelizadora. … O Pentecostes constitui o grande «ícone» da nova existência em Cristo')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 3;

-- glorious-3 · Jo 14, 15-26
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Se me amais, observai os meus mandamentos. E eu rogarei ao Pai, e ele vos dará um outro Paráclito, para que fique eternamente convosco, o Espírito de verdade, a quem o mundo não pode receber, porque não o vê, nem o conhece; mas vós o conhecereis, porque habitará convosco, e estará em vós. … Mas o Paráclito, o Espírito Santo, a quem o Pai enviará em meu nome, ele vos ensinará todas as coisas, e vos recordará tudo o que vos tenho dito.', 'Jo 14, 15-26', 2
from public.mysteries m where m.type = 'glorious' and m.sort_order = 3;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte Primeira, cap. IX «Do oitavo artigo», 12ª pergunta do capítulo. Tradução a partir do italiano.', '— Que opera o Espírito Santo na Igreja? — O Espírito Santo, como a alma no corpo, vivifica a Igreja com a sua graça e com os seus dons; nela estabelece o reino da verdade e do amor; e a assiste para que conduza com segurança os seus filhos pelo caminho do céu.'),
  (1, 'Santo Agostinho', 'Sermão 268, 2 (PL 38, 1232), na tradução do CIC 797', 'O que o nosso espírito, quer dizer, a nossa alma, é para os nossos membros, o Espírito Santo é-o para os membros de Cristo, para o Corpo de Cristo, que é a Igreja.'),
  (2, 'Santo Ireneu de Lião', 'Contra as heresias, III, 24, 1 (texto abreviado como no CIC 797, cuja tradução se segue; grafia adaptada ao Brasil)', 'De fato, foi à própria Igreja que o dom de Deus foi confiado [...]. Nela foi depositada a comunhão com Cristo, isto é, o Espírito Santo, arras da incorruptibilidade, confirmação da nossa fé e escada da nossa ascensão para Deus [...]. Porque onde está a Igreja, aí está também o Espírito de Deus; e onde está o Espírito de Deus, aí está a Igreja e toda a graça.'),
  (3, 'Catecismo da Igreja Católica', 'CIC 733', '«Deus é Amor» (1 Jo 4, 8.16) e o Amor é o primeiro dom, que contém todos os outros. Este amor «derramou-o Deus nos nossos corações, pelo Espírito Santo que nos foi dado» (Rm 5, 5).'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte Quinta, cap. II «Dos dons do Espírito Santo», 2ª pergunta do capítulo. Tradução a partir do italiano.', '— Para que servem os dons do Espírito Santo? — Os dons do Espírito Santo servem para nos firmar na Fé, na Esperança e na Caridade, e para nos tornar prontos para os atos das virtudes necessárias para alcançar a perfeição da vida cristã.'),
  (5, 'Catecismo da Igreja Católica', 'CIC 736 (texto abreviado; grafia adaptada ao Brasil)', 'É graças a esta força do Espírito que os filhos de Deus podem dar fruto. Aquele que nos enxertou na verdadeira Vide far-nos-á dar «os frutos do Espírito: caridade, alegria, paz, paciência, benignidade, bondade, fidelidade, mansidão, autodomínio» (Gl 5, 22-23). «O Espírito é a nossa vida»: quanto mais renunciarmos a nós próprios (113), mais «caminharemos segundo o Espírito» (114).'),
  (6, 'Catecismo da Igreja Católica', 'CIC 2671 (grafia adaptada ao Brasil)', 'A forma tradicional de pedir o Espírito é invocar o Pai, por Cristo, nosso Senhor, para que nos dê o Espírito Consolador (17). Jesus insiste nesta petição em seu nome no próprio momento em que promete o dom do Espírito de verdade (18). Mas também é tradicional a oração mais simples e mais direta: «Vinde, Espírito Santo». … «Vinde, Espírito Santo, enchei os corações dos Vossos fiéis e acendei neles o fogo do vosso amor» (19).')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 3;

-- glorious-4 · Lc 1, 48-50
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, '… porque lançou os olhos para a baixeza da sua serva; portanto, eis que, de hoje em diante, todas as gerações me chamarão bem-aventurada. Porque fez em mim grandes coisas aquele que é poderoso, e cujo nome é santo. E cuja misericórdia (se estende) de geração em geração sobre aqueles que o temem.', 'Lc 1, 48-50', 0
from public.mysteries m where m.type = 'glorious' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Pio XII', '*Munificentissimus Deus*, §44 (Definição solene do dogma)', '«… pronunciamos, declaramos e definimos ser dogma divinamente revelado que: a imaculada Mãe de Deus, a sempre virgem Maria, terminado o curso da vida terrestre, foi assunta em corpo e alma à glória celestial».'),
  (1, 'São João Damasceno', 'Homilia II sobre a Dormição, 14, citada por Pio XII em *Munificentissimus Deus*, §21 (trad. da Santa Sé)', '«Convinha que aquela que no parto manteve ilibada virgindade conservasse o corpo incorrupto mesmo depois da morte. Convinha que aquela que trouxe no seio o Criador encarnado, habitasse entre os divinos tabernáculos. Convinha que morasse no tálamo celestial aquela que o Eterno Pai desposara. Convinha que aquela que viu o seu Filho na cruz, com o coração traspassado por uma espada de dor de que tinha sido imune no parto, contemplasse assentada à direita do Pai. Convinha que a Mãe de Deus possuísse o que era do Filho, e que fosse venerada por todas as criaturas como Mãe e Serva do mesmo Deus».'),
  (2, 'São Francisco de Sales', 'Sermão autógrafo para a festa da Assunção, citado por Pio XII em *Munificentissimus Deus*, §35 (trad. da Santa Sé)', '«Que filho haveria, que, se pudesse, não ressuscitava a sua mãe e não a levava para o céu?»'),
  (3, 'Pio XII', '*Munificentissimus Deus*, §40', '… alcançou por fim, como suprema coroa dos seus privilégios, que fosse preservada da corrupção do sepulcro, e que, à semelhança do seu divino Filho, vencida a morte, fosse levada em corpo e alma ao céu, onde refulge como Rainha à direita do seu Filho, Rei imortal dos séculos (cf. 1Tm 1,17).'),
  (4, 'São Bernardo de Claraval', '1.º Sermão para a Assunção (trad. Pain de Cîteaux 32, p. 63 rev.; texto abreviado)', 'Hoje a Virgem Maria sobe, gloriosa, ao céu. … Sim, Ela precedeu-nos, a nossa Rainha, precedeu-nos e foi recebida com tanta glória que nós, seus humildes servos, podemos seguir a nossa Rainha com toda confiança gritando … «Arrasta-me atrás de ti. Corramos ao odor dos teus perfumes!» (Ct 1, 3-4) Viajantes sobre a terra, enviamos à frente a nossa advogada … a Mãe de misericórdia, para defender eficazmente a nossa salvação.'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte II, cap. V «Da Assunção de Maria Virgem», 5ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que devemos nós fazer na solenidade da Assunção de Maria Virgem? — Na solenidade da Assunção de Maria Virgem devemos: 1.º alegrar-nos com a sua gloriosa assunção e exaltação; 2.º venerá-la como nossa senhora e nossa advogada junto de seu divino Filho; 3.º pedir-lhe que nos obtenha de Deus a graça de levar uma vida santa e de nos prepararmos de tal maneira para a morte, que mereçamos ser por ela assistidos e protegidos, e ter parte na sua glória.»'),
  (6, 'Catecismo da Igreja Católica', 'CIC 975', '«Nós cremos que a santíssima Mãe de Deus, a nova Eva, a Mãe da Igreja, continua a desempenhar no céu o seu papel maternal para com os membros de Cristo».')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 4;

-- glorious-4 · Sl 131, 8
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Levanta-te, Senhor, entra no teu repouso, tu e a arca da tua santidade.', 'Sl 131, 8', 1
from public.mysteries m where m.type = 'glorious' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'Pio XII', '*Munificentissimus Deus*, §26 (texto abreviado)', '«… houve quem citasse a este propósito as palavras do Salmista: “Erguei-vos, Senhor, para o vosso repouso, vós e a Arca de vossa santificação” (Sl 131, 8); e na Arca da Aliança, feita de madeira incorruptível e colocada no templo de Deus, viam como que uma imagem do corpo puríssimo da virgem Maria, preservado da corrupção do sepulcro, e elevado a tamanha glória no céu.»'),
  (1, 'Santo Antônio de Pádua', 'Sermão na Assunção de Santa Maria Virgem, citado por Pio XII em *Munificentissimus Deus*, §29 (trad. da Santa Sé; texto abreviado)', '«Daqui, vê-se claramente que o corpo da santíssima Virgem foi assunto ao céu, pois era o lugar dos pés do Senhor.» … «Ressuscitou a Arca da sua santificação, quando neste dia a virgem Mãe foi assunta ao tálamo celestial.»'),
  (2, 'São Roberto Belarmino', 'Sermões pregados em Lovaina, sermão 40, «Da Assunção da B. Virgem Maria», citado por Pio XII em *Munificentissimus Deus*, §34 (trad. da Santa Sé)', '«Quem há, pergunto, que possa pensar que a arca da santidade, o domicílio do Verbo, o templo do Espírito Santo tenha caído em ruínas? Horroriza-se o espírito só com pensar que aquela carne que gerou, deu a luz, alimentou e transportou a Deus, se tivesse convertido em cinza ou fosse alimento dos vermes.»'),
  (3, 'Santo Afonso Maria de Ligório', '*Glórias de Maria*, parte II, discurso 1, citado por Pio XII em *Munificentissimus Deus*, §35 (trad. da Santa Sé)', '«Jesus não quis que o corpo de Maria se corrompesse depois da morte, pois redundaria em seu desdouro que se transformasse em podridão aquela carne virginal de que ele mesmo tomara a própria carne.»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 4;

-- glorious-4 · 1 Co 15, 20-23
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Mas Cristo ressuscitou dos mortos, sendo ele as primícias dos que dormem; porque, assim como a morte (veio) por um homem, também por um homem (veio) a ressurreição dos mortos. E, assim como todos morreram em Adão, assim também todos serão vivificados em Cristo. Mas cada um em sua ordem, como primícias Cristo, depois os que são de Cristo, que creram na sua vinda.', '1 Co 15, 20-23', 2
from public.mysteries m where m.type = 'glorious' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Catecismo da Igreja Católica', 'CIC 966 (texto abreviado) (grafia adaptada ao Brasil)', '«Finalmente, a Virgem Imaculada, preservada imune de toda a mancha da culpa original, terminado o curso da vida terrena, foi elevada ao céu em corpo e alma e exaltada pelo Senhor como rainha, para assim se conformar mais plenamente com o seu Filho, Senhor dos senhores e vencedor do pecado e da morte». A Assunção da santíssima Virgem é uma singular participação na ressurreição do seu Filho e uma antecipação da ressurreição dos outros cristãos: «No teu parto guardaste a virgindade e na tua dormição não abandonaste o mundo, ó Mãe de Deus…»'),
  (1, 'São João Damasceno', '1.ª Homilia sobre a Dormição, 11-14 (texto abreviado)', '… O teu corpo puríssimo, sem mácula, não foi abandonado à terra, antes foste elevada até à morada do Reino dos Céus, tu, a Rainha, a Soberana, a Senhora, a Mãe de Deus … Lança os teus olhos sobre nós, ó Rainha, Mãe do nosso bom Soberano; guia o nosso caminho até ao porto sem tempestades do desejo bom de Deus.'),
  (2, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte II, cap. V «Da Assunção de Maria Virgem», 1ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que celebra a Igreja na festa da Assunção da santíssima Virgem? — Na festa da Assunção da santíssima Virgem a Igreja celebra a morte preciosa e a gloriosa Assunção ao Céu de Maria Virgem.»'),
  (3, 'Pio XII', '*Munificentissimus Deus*, §42 (texto abreviado)', '«… é de esperar ainda que este luminoso e incomparável exemplo, posto diante dos olhos de todos, mostre com plena luz qual o fim a que se destinam a nossa alma e o nosso corpo. E, finalmente, esperamos que a fé na assunção corpórea de Maria ao céu torne mais firme e operativa a fé na nossa própria ressurreição.»'),
  (4, 'São João Paulo II', '*Rosarium Virginis Mariae*, §23 (texto abreviado)', '… A esta glória, onde com a Ascensão Cristo Se senta à direita do Pai, Ela mesma será elevada com a Assunção, chegando, por especialíssimo privilégio, a antecipar o destino reservado a todos os justos com a ressurreição da carne. Enfim, coroada de glória — como aparece no último mistério glorioso — Ela resplandece como Rainha dos Anjos e dos Santos…')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 4;

-- glorious-4 · 1 Co 15, 54-57
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'E, quando este (corpo) mortal se revestir da imortalidade, então se cumprirá a palavra que está escrita: Tragada foi a morte na vitória. Onde está, ó morte, a tua vitória? Onde está, ó morte, o teu aguilhão? Ora, o aguilhão da morte é o pecado, e a força do pecado é a lei. Porém, graças a Deus, que nos deu a vitória (contra a morte) por Nosso Senhor Jesus Cristo.', '1 Co 15, 54-57', 3
from public.mysteries m where m.type = 'glorious' and m.sort_order = 4;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'Pio XII', '*Munificentissimus Deus*, §39 (texto abreviado)', '«… os santos Padres apresentam a virgem Maria como nova Eva, sujeita sim, mas intimamente unida ao novo Adão na luta contra o inimigo infernal. … Assim como a ressurreição gloriosa de Cristo constituiu parte essencial e último troféu desta vitória, assim também a vitória de Maria santíssima, comum com a do seu Filho, devia terminar pela glorificação do seu corpo virginal».'),
  (1, 'Sacramentário Gregoriano', 'Oração da festa da Assunção (Sacramentário enviado por Adriano I a Carlos Magno), citada por Pio XII em *Munificentissimus Deus*, §17 (trad. da Santa Sé)', '«É digna de veneração, Senhor, a festividade deste dia, em que a santa Mãe de Deus sofreu a morte temporal; mas não poderia ficar presa com as algemas da morte aquela que gerou no seu seio o Verbo de Deus encarnado, vosso Filho, nosso Senhor».'),
  (2, 'São Germano de Constantinopla', '1.º Sermão sobre a Dormição da Santa Mãe de Deus, citado por Pio XII em *Munificentissimus Deus*, §22 (trad. da Santa Sé)', '«Vós, como está escrito, aparecestes “em beleza”; o vosso corpo virginal é totalmente santo, totalmente casto, totalmente domicílio de Deus de forma que até por este motivo foi isento de desfazer-se em pó; foi, sim, transformado, enquanto era humano, para viver a vida altíssima da incorruptibilidade; mas agora está vivo, gloriosíssimo, incólume e participante da vida perfeita».'),
  (3, 'Catecismo da Igreja Católica', 'CIC 1014 (texto abreviado; cita a *Imitação de Cristo*, I, 23; grafia adaptada ao Brasil)', '«A Igreja exorta-nos a prepararmo-nos para a hora da nossa morte … a pedirmos à Mãe de Deus que rogue por nós “na hora da nossa morte” (Oração da Ave-Maria) e a confiarmo-nos a S. José, padroeiro da boa morte: “… havias de te comportar como se devesses morrer hoje. Se tivesses boa consciência, não terias grande receio da morte. Mais vale acautelares-te do pecado do que fugir da morte. Se hoje não estás preparado, como o estarás amanhã?”»'),
  (4, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as Festas, Parte II, cap. V «Da Assunção de Maria Virgem», 7ª pergunta do capítulo. Tradução a partir do italiano.', '«— Devem também os pecadores confiar no patrocínio de Maria Virgem? — Também os pecadores devem confiar muitíssimo no patrocínio de Maria Virgem, porque ela é mãe de misericórdia e o refúgio dos pecadores, para lhes obter de Deus a graça da conversão.»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 4;

-- glorious-5 · Ap 12, 1
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Depois apareceu no céu um grande sinal: Uma mulher vestida de sol, e a lua debaixo de seus pés, e uma coroa de doze estrelas sobre a sua cabeça.', 'Ap 12, 1', 0
from public.mysteries m where m.type = 'glorious' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 0
join (values
  (0, 'Pio XII', 'Encíclica Ad caeli reginam, § 1 (texto abreviado)', '«Desde os primeiros séculos da Igreja católica, elevou o povo cristão orações e cânticos de louvor e de devoção à Rainha do céu … e nunca foi frustrada a esperança posta na Mãe do Rei divino, Jesus Cristo, nem se enfraqueceu a fé, que nos ensina reinar com materno coração no universo inteiro a Virgem Maria, Mãe de Deus, assim como está coroada de glória na bem-aventurança celeste.»'),
  (1, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. V «Da Assunção de Maria Virgem», 3ª e 4ª perguntas do capítulo. Tradução a partir do italiano.', '«— Qual é a glória à qual foi exaltada Maria Virgem no céu? — Maria Virgem foi exaltada acima de todos os coros dos Anjos e acima de todos os Santos do paraíso, como rainha do céu e da terra. — Por que a Virgem foi exaltada no céu acima de todas as criaturas? — A Virgem foi exaltada no céu acima de todas as criaturas porque é mãe de Deus e é, de todas as criaturas, a mais humilde e a mais santa.»'),
  (2, 'Santo Efrém', 'Hinos sobre a Bem-aventurada Virgem Maria, XIX, citado por Pio XII, Encíclica Ad caeli reginam, § 10', '«Erga-me o firmamento nos seus braços, porque eu estou mais honrada do que ele. O céu não foi tua mãe, e fizeste dele teu trono. Ora, quanto mais se deve honrar e venerar a mãe do Rei, do que o seu trono!»'),
  (3, 'Catecismo da Igreja Católica', 'CIC 972 (grafia adaptada ao Brasil)', '«Assim como, glorificada já em corpo e alma, a Mãe de Jesus é imagem e início da igreja que se há de consumar no século futuro, assim também, brilha na terra como sinal de esperança segura e de consolação, para o povo de Deus ainda peregrino.»'),
  (4, 'Pio XII', 'Encíclica Ad caeli reginam, § 30', '«A esse e outros cânticos devem juntar-se as Ladainhas lauretanas, que levam o povo cristão a invocar todos os dias nossa Senhora como rainha; e no santo rosário, que se pode chamar coroa mística da celeste rainha, já há muitos séculos os fiéis contemplam, do quinto mistério glorioso, o reino de Maria, que abraça o céu e a terra.»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 5;

-- glorious-5 · 1 Rs 2, 19-20
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Foi, pois, Betsabeia ter com o rei Salomão, para lhe falar em favor de Adonias; e o rei levantou-se para a vir receber, e saudou-a com profunda reverência, e sentou-se no seu trono; e foi posto um trono para a mãe do rei, a qual se sentou à sua mão direita. E ela disse-lhe: Eu só te peço uma pequena coisa, não me envergonhes com a repulsa. E o rei disse-lhe: Pede, minha mãe, porque não é justo que vás descontente.', '1 Rs 2, 19-20', 1
from public.mysteries m where m.type = 'glorious' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 1
join (values
  (0, 'São Germano de Constantinopla', 'Sermão I sobre a Apresentação da Santíssima Mãe de Deus, citado por Pio XII, Encíclica Ad caeli reginam, § 18', '«Senta-te, ó Senhora; sendo tu Rainha e mais eminente que todos os reis, pertence-te estar sentada no lugar mais nobre.»'),
  (1, 'Beato Pio IX', 'Bula Ineffabilis Deus, citada por Pio XII, Encíclica Ad caeli reginam, § 40', '«Com ânimo verdadeiramente materno para conosco … e ocupando-se da nossa salvação, ela, que pelo Senhor foi constituída rainha do céu e da terra, toma cuidado de todo o gênero humano, e — tendo sido exaltada sobre todos os coros dos anjos e as hierarquias dos santos do céu, e estando à direita do seu unigênito Filho, Jesus Cristo, nosso Senhor — com as suas súplicas maternas impetra com eficácia, obtém quanto pede, nem pode deixar de ser ouvida.»'),
  (2, 'São Germano de Constantinopla', 'Homilia I sobre a Dormição (PG 98, 348), citada por S. João Paulo II, Audiência geral de 23 de julho de 1997, n. 4', 'Cristo quis «ter, por assim dizer, a proximidade dos teus lábios e do teu coração; desta maneira Ele atende a todos os desejos que Lhe exprimes, quando sofres pelos teus filhos, e Ele realiza, com o Seu poder divino, tudo o que Lhe pedes».'),
  (3, 'Pio XII', 'Encíclica Ad caeli reginam, § 46 (texto abreviado)', '«Procurem pois todos, e agora com mais confiança, aproximar-se do trono da misericórdia e da graça, para pedir à nossa Rainha e Mãe socorro na adversidade, luz nas trevas, conforto na dor e no pranto; e, o que é mais, esforcem-se por se libertar da escravidão do pecado …»'),
  (4, 'Bento XVI', 'Audiência geral de 22 de agosto de 2012 (memória de Nossa Senhora Rainha) (texto abreviado)', '«Na serenidade ou na escuridão da existência, dirijamo-nos a Maria confiando-nos à sua intercessão contínua, porque do Filho nos possa alcançar toda a graça e misericórdia necessárias para o nosso peregrinar ao longo das sendas do mundo. … Portanto, Rainha é título de confiança, alegria e amor. E sabemos que Aquela que tem nas suas mãos em parte o destino do mundo é boa, que nos ama e nos ajuda nas nossas dificuldades.»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 5;

-- glorious-5 · Sl 44, 10-15
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'As filhas dos reis são tuas damas de honra. A rainha está à tua dextra, com manto de ouro, e engalanada com variedade (de adornos). Escuta, ó filha, e vê, e inclina o teu ouvido, e esquece-te do teu povo e da casa de teu pai. E o rei cobiçará a tua beleza, porque ele é o Senhor teu Deus, e adorá-lo-ão (todos). … Toda a glória da filha do rei está no interior, (quando ela está adornada) de franjas de ouro, vestida de vários adornos.', 'Sl 44, 10-15', 2
from public.mysteries m where m.type = 'glorious' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 2
join (values
  (0, 'Santo André de Creta', 'Homilia III sobre a Dormição da Santíssima Mãe de Deus, citada por Pio XII, Encíclica Ad caeli reginam, § 17', '«Rainha de todo o gênero humano, porque, fiel à significação do seu nome, se encontra acima de tudo quanto não é Deus.»'),
  (1, 'Santo Ildefonso de Toledo', 'Da virgindade perpétua de Santa Maria (PL 96, 58), citado por Pio XII, Encíclica Ad caeli reginam, § 20 (texto abreviado)', '«Ó minha senhora, minha dominadora: tu dominas em mim, ó mãe do meu Senhor … Senhora entre as escravas, rainha entre as irmãs.»'),
  (2, 'São Sofrônio de Jerusalém', 'Sermão sobre a Anunciação da Bem-aventurada Virgem Maria (PG 87, 3238.3242), citado por Pio XII, Encíclica Ad caeli reginam, § 38 (texto abreviado)', '«Tu finalmente … superaste em muito todas as criaturas … Que poderá existir mais sublime que tal alegria, ó Virgem Mãe? Que pode existir mais elevado que tal graça, a qual por divina vontade só tu tiveste em sorte?»'),
  (3, 'Santo Afonso Maria de Ligório', 'Glórias de Maria, parte I, cap. 1, § 1, citado por Pio XII, Encíclica Ad caeli reginam, § 24', '«Porque a virgem Maria foi elevada até ser Mãe do Rei dos reis, com justa razão a distingue a Igreja com o título de Rainha.»'),
  (4, 'Bento XVI', 'Audiência geral de 22 de agosto de 2012 (memória de Nossa Senhora Rainha) (texto abreviado)', '«E o mesmo é válido para Maria: é rainha ao serviço de Deus e da humanidade, é rainha do amor que vive o dom de si a Deus para entrar no desígnio da salvação do homem. Ao anjo, responde: Eis-me, sou a serva do Senhor (cf. Lc 1, 38) … É rainha precisamente amando-nos, ajudando-nos em todas as nossas necessidades; é a nossa irmã e serva humilde.»'),
  (5, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Instrução sobre as festas do Senhor, da B. Virgem e dos Santos, Parte II, cap. V «Da Assunção de Maria Virgem», 6ª pergunta do capítulo. Tradução a partir do italiano.', '«— Como podemos nós merecer a proteção de Maria Santíssima? — Nós podemos merecer a proteção de Maria Santíssima imitando as suas virtudes, e especialmente a pureza e a humildade.»'),
  (6, 'Pio XII', 'Encíclica Ad caeli reginam, § 47 (texto abreviado)', '«Com vivo e diligente cuidado todos se esforcem por copiar nos sentimentos e nos atos, segundo a própria condição, as altas virtudes da Rainha do céu e nossa Mãe amantíssima. … Nem presuma alguém ser filho de Maria, digno de se acolher à sua poderosíssima proteção, se a exemplo dela não é justo, manso e casto …»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 5;

-- glorious-5 · Ap 2, 10
insert into public.passages (mystery_id, text, reference, sort_order)
select m.id, 'Não temas nada do que terás que sofrer. … Sê fiel até à morte, e eu te darei a coroa da vida.', 'Ap 2, 10', 3
from public.mysteries m where m.type = 'glorious' and m.sort_order = 5;
insert into public.commentaries (mystery_id, passage_id, text, author, source, sort_order)
select m.id, p.id, v.text, v.author, v.source, v.sort_order
from public.mysteries m
join public.passages p on p.mystery_id = m.id and p.sort_order = 3
join (values
  (0, 'São Pio X', 'Catecismo Maior de São Pio X (Roma, 1905), Parte II, cap. III «Da Ave-Maria», 11ª pergunta do capítulo. Tradução a partir do italiano.', '«— Que pedimos nós com as últimas palavras da Ave-Maria? — Com as últimas palavras da Ave-Maria pedimos a proteção da Santíssima Virgem no curso desta vida, e especialmente na hora da nossa morte, na qual dela teremos maior necessidade.»'),
  (1, 'Concílio Vaticano II', 'Constituição dogmática Lumen gentium, 62 (texto abreviado; grafia adaptada ao Brasil)', '«Esta maternidade de Maria na economia da graça perdura sem interrupção, desde o consentimento, que fielmente deu na anunciação e que manteve inabalável junto à cruz, até à consumação eterna de todos os eleitos. De fato, depois de elevada ao céu, não abandonou esta missão salvadora, mas, com a sua multiforme intercessão, continua a alcançar-nos os dons da salvação eterna. Cuida, com amor materno, dos irmãos de seu Filho que, entre perigos e angústias, caminham ainda na terra, até chegarem à pátria bem-aventurada.»'),
  (2, 'São Bernardo de Claraval', 'In laudibus Virginis Matris (Super Missus est), homilia II, 17 (texto abreviado)', '«Ó tu, que na instabilidade deste mundo sentes que és mais sacudido pelas tormentas … não desvies o olhar do fulgor desta estrela … olha para a estrela, invoca Maria.» … «Nos perigos, nas angústias e nas incertezas, pensa em Maria, invoca Maria.» … «Seguindo-a, não te desviarás; invocando-a, não desesperarás … se te é propícia chegarás ao fim.»'),
  (3, 'Santo Efrém', 'Oração à Santíssima Mãe de Deus, citada por Pio XII, Encíclica Ad caeli reginam, § 10', '«… Virgem augusta e protetora, rainha e senhora, protege-me à tua sombra, guarda-me, para que Satanás, que semeia ruínas, não me ataque, nem triunfe de mim o iníquo adversário.»'),
  (4, 'São Bártolo Longo', 'Súplica à Rainha do Santo Rosário de Pompeia, citada por S. João Paulo II, Rosarium Virginis Mariae, § 43 (grafia adaptada ao Brasil)', '«Ó Rosário bendito de Maria, doce cadeia que nos prende a Deus, vínculo de amor que nos une aos Anjos, torre de salvação contra os assaltos do inferno, porto seguro no naufrágio geral, não te deixaremos nunca mais. Serás o nosso conforto na hora da agonia. Seja para ti o último beijo da vida que se apaga. E a última palavra dos nossos lábios há de ser o vosso nome suave, ó Rainha do Rosário de Pompeia, ó nossa Mãe querida, ó Refúgio dos pecadores, ó Soberana consoladora dos tristes.»')
) as v(sort_order, author, source, text) on true
where m.type = 'glorious' and m.sort_order = 5;
